window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_030"]={"n":"李攀龙","dyn":"明","poems":[{"t":"于郡城送明卿之江西 其二","f":"七言绝句","c":["青枫飒飒雨凄凄，秋色遥看入楚迷。","谁向孤舟怜逐客，白云相送大江西。"]},{"t":"挽王中丞 其二","f":"七言绝句","c":["司马台前列柏高，风云犹自夹旌旄。","属镂不是君王意，莫作胥山万里涛。"]},{"t":"挽王中丞 其八","f":"七言绝句","c":["幕府高临碣石开，蓟门丹旐重裴徊。","沙场入夜多风雨，人见亲提铁骑来。"]},{"t":"塞上曲四首送元美 其四","f":"七言绝句","c":["白羽如霜出塞寒，胡烽不断接长安。","城头一片西山月，多少征人马上看。"]},{"t":"杪秋登太华山绝顶 其二","f":"七言律诗","c":["缥缈真探白帝宫，三峰此日为谁雄。","苍龙半挂秦川雨，石马长嘶汉苑风。","地敞中原秋色尽，天开万里夕阳空。","平生突兀看人意，容尔深知造化功。"]},{"t":"答寄俞仲蔚 其一","f":"五言古诗","c":["太乙贶汉德，名驹生渥洼。","赤汗沾青云，长嘶振流沙。","饥龁玉山刍，渴则饮其涯。","翘尾以踯躅，騊駼相经过。","不愿游阊阖，况乃服盐车。","世岂无伯乐，垂耳奈我何。","天子发素书，使者出蹉跎。","駪駪十二闲，驽马常苦多。","虽有千里姿，羁绊非所加。"]},{"t":"集开元寺","f":"五言古诗","c":["流阴拂层岑，返照翳深谷。","古寺入萧条，回岩抱幽独。","梵影净香台，钟声殷石屋。","绝壁栖禅诵，悬厓下樵牧。","秋花雨还瘦，老树霜逾秃。","寒泉可瑩心，白云况极目。","登临客自佳，摇落时何速。","蔬色荡腥膻，苔光清简牍。","新诗发神秀，旧游耿初服。","归来杖屦便，老去烟霞伏。","高城出睥睨，灯火通林麓。","言旋转多兴，后期此同宿。"]},{"t":"同皇甫缮部寒夜城南咏月","f":"五言律诗","c":["片月挂遥岑，层城曳素阴。","寒分宫树净，影落御沟深。","结冷悲征笛，匀霜上捣砧。","西园芳宴后，白雪复谁吟。"]},{"t":"赋得屏风","f":"五言律诗","c":["虚屏汉宫里，有女《白头吟》。","色倚琉璃怯，秋来湘水深。","欢情张画烛，愁坐掩清砧。","莫为苍蝇误，君王在上林。"]},{"t":"送皇甫别驾往开州","f":"七言律诗","c":["衔杯昨日夏云过，愁向燕山送玉珂。","吴下诗名诸弟少，天涯宦迹左迁多。","人家夜雨黎阳树，客渡秋风瓠子河。","自有吕虔刀可赠，开州别驾岂蹉跎。"]},{"t":"署中有忆江南梅花者因以为赋","f":"七言律诗","c":["欲问梅花上苑迟，座中南客重相思。","开帘署有青山色，对酒人如白雪枝。","驿使书来春不见，仙郎梦断月应知。","偏惊直北多烽火，昨夜关山笛里吹。"]},{"t":"怀子相","f":"七言律诗","c":["蓟门秋杪送仙槎，此日开樽转岁华。","卧病山中生桂树，怀人江上落梅花。","春来鸿雁书千里，夜色楼台雪万家。","南粤东吴还独往，应怜薄宦滞天涯。"]},{"t":"张驾部宅梅花","f":"七言律诗","c":["仙郎雪后建章回，清夜西堂拥上才。","笛里春愁燕塞满，梁间月色汉宫来。","即看芳树催颜鬓，莫厌寒花对酒杯。","共忆故人江北望，因君赋罢倚徘徊。"]},{"t":"上朱大司空 其二","f":"七言律诗","c":["河堤使者大司空，无领中丞节制同。","转饷千年军国壮，朝宗万里帝图雄。","春流无恙桃花水，秋色依然瓠子宫。","太史但裁《沟洫志》，丈人何减汉臣风。"]},{"t":"按察李公诞子公蜀人先以中书舍人为御史","f":"七言律诗","c":["高才染翰五云中，复道登车揽辔同。","雏有一毛殊是凤，驹无千里不为骢。","名乌业已承家学，字犬文堪命国工。","君自蜀人杨马在，同乡奕叶播清风。"]},{"t":"夜度娘","f":"五言绝句","c":["侬来星始集，侬去月将夕。","不是地上霜，无人见侬迹。"]},{"t":"寄登宗秀才茂登池亭 其二","f":"五言绝句","c":["窗中采莲舟，落日菱歌起。","坐见浣沙人，红颜照秋水。"]},{"t":"戏呈子坤 其二","f":"五言绝句","c":["家有秦台女，青云路不遥。","但愁明月夜，天上唤吹箫。"]},{"t":"戏呈子坤 其三","f":"五言绝句","c":["丹灶几时开，妆成倚镜台。","不须嗔窃药，本自月中来。"]},{"t":"汝思见过林亭 其一","f":"七言绝句","c":["五柳阴阴逼酒清，一杯须见故人情。","明朝马上听黄鸟，不似樽前唤友声。"]},{"t":"早夏示殿卿 其一","f":"七言绝句","c":["长夏园林黄鸟来，百花春酒复新开。","主人把酒听黄鸟，黄鸟一声酒一杯。"]},{"t":"早夏示殿卿 其二","f":"七言绝句","c":["湖上青山绕屋斜，萧条重枉使君车。","到来纵遣柴门闭，只在东邻卖酒家。"]},{"t":"挽杨生 其二","f":"七言绝句","c":["平生裘马最翩翩，不惜黄金结少年。","今日萧条君不见，白杨秋色有谁怜。"]},{"t":"送潘润父（已下出遗集）","f":"五言律诗","c":["摇落荒山道，君行日独深。","解装迎暮雨，秣马发秋林。","僮仆知乡泪，风尘见客心。","十年悲未遇，归卧㟙湖阴。"]},{"t":"寄许殿卿","f":"五言律诗","c":["漠漠雨如沙，翩翩燕子斜。","官贫轻逆旅，乡远重携家。","昨夜怀人去，春风抚岁华。","独行临御水，问使到梅花。"]},{"t":"十五夜谢山人同李明府见过得宵字","f":"五言律诗","c":["客有山中约，人来江上遥。","张灯传彩笔，换酒出金貂。","贫病看交好，文章慰寂寥。","天涯还此会，留醉驻春宵。"]},{"t":"重别李户曹","f":"五言律诗","c":["旧游京陌满，何处珥貂行。","念子从王事，令人识宦情。","春风吹远别，芳草送孤征。","莫叹谋身拙，前贤重请缨。"]},{"t":"秋夜","f":"五言律诗","c":["岂敢欹芳树，多时信转蓬。","乡心生夜雨，客病卧秋风。","大药三山外，浮名四海中。","自知成汗漫，还与众人同。"]},{"t":"郊游","f":"五言律诗","c":["何为驱车马，终岁惨尘颜。","偶出城西寺，因看湖上山。","水流芳草外，人醉落花间。","复值岩耕客，春风荷筱还。"]},{"t":"东门行 其二","f":"古风","c":["出东门，不顾归。","来入门，怆欲悲。","舍中无儋石储，还视身上衣参差。","慷慨出门去，儿女牵裾啼。","他家自愿富贵，贱妾与君但餔糜。","但餔糜，上用穹窿天故，下用匍匐小儿。","时吏清廉法不可干，一旦缓急当告谁。","行吾望君归，嗟少年，莫轻非。"]},{"t":"陌上桑","f":"五言古诗","c":["日出东南隅，照我西北楼。","楼上有好女，自名秦罗敷。","罗敷贵家子，足不踰门枢。","性颇喜蚕作，采桑南陌头。","上枝结笼系，下枝挂笼钩。","堕髻何缭绕，颜色以敷愉。","缃绮为下裙，紫绮为上襦。","行者见罗敷，下担故绸缪。","少年见罗敷，袒裼出臂韝。","樵者忘其薪，刍者忘其刍。","来归但怨怒，且复坐斯须。","使君自南来，驻我五马车。","遣吏前致问，为是谁家姝。","罗敷小家女，秦氏有高楼。","西邻焦仲卿，兰芝对道隅。","罗敷年几何，十五为人妇。","嫁复一年馀，力桑以作苦。","孰与使君俱，使君复为谁。","蚕桑所自娱，小吏无所畏。","使君一何迂。","罗敷他人妇，使君他人夫。","东方千馀骑，夫婿在上头。","左右三河长，负弩为先驱。","何用识夫婿，飞盖随高车。","象牙为车轸，桂树为轮舆。","白马为上襄，两骖皆骊驹。","青丝为马靷，黄金为辔头。","腰中千金剑，自名为鹿卢。","起家府小吏，拜为朝大夫。","稍迁郡太守，出入专城居。","月朔朝京师，观者盈路衢。","为人既白晰，鬑鬑有髭须。","四十尚不足，三十尚有馀。","坐中数千人，皆言夫婿殊。"]},{"t":"长相思","f":"古风","c":["秋风清，秋月明。","叶叶梧桐槛外声，难教归梦成。","砌蛩鸣，树鸟惊。","塞雁行行天际横，偏伤旅客情。"]},{"t":"子与以服散卧病因赋姬人怨服散三章戏赠 其二","f":"七言绝句","c":["桃花流水赤城山，当日刘郎去复还。","若道不如天上好，何缘二女忆人间。"]},{"t":"二子诗 其二 谢茂秦","f":"五言古诗","c":["谢榛吾党彦，轗轲京华陌。","黄金自不留，朱颜亦已掷。","韦布岂尽愚，咄嗟名士籍。","握手金闺人，中情多所适。","目若营俦匹，踯躅难自释。","倒屣公卿前，将须坐其席。","冠盖罗长衢，染翰日相索。","遂令清庙音，乃在褐衣客。","一出游燕篇，流俗忽复易。","还顾望鹿门，矫矫青云翮。"]},{"t":"五子诗 其四 徐子与","f":"五言古诗","c":["徐生一何俊，本自青云姿。","十年住天目，含意多素辞。","既闻风雅音，三叹文在兹。","眄睐生荣名，徙倚即前绥。","念为理清曲，高言倡者谁。","踯躅流俗间，携手不相疑。","时髦满要路，各谓中心私。","世人岂同愿，吾道欲委蛇。","黄金买大药，朱颜庶可持。","物理率如此，和光难独窥。"]},{"t":"五子诗 其五 梁公实","f":"五言古诗","c":["梁生起南海，负气何倜傥。","北交中原士，徘徊得吾党。","高名岂宿著，一朝奋鸿响。","时俗既淆浊，振衣念独往。","礼法难为工，局促向天壤。","王乔可等期，服食理非枉。","引领还罗浮，愿言税尘鞅。","俯视大河流，逶迤浮云上。","盛衰随物化，世情自卤莽。","吾意当告谁，黄金妒偃仰。"]},{"t":"五子诗 其三 宗子相","f":"五言古诗","c":["婉婉维扬士，早岁绝人识。","结撰有至思，先民乃遗则。","时俗徒嗷嗷，此物知者得。","郁郁独往心，百折江河力。","披睹他自媚，我意安所测。","念兹携手驩，荣名与令德。","浩荡阴阳移，吾道相终极。","语及千载事，愀愀动颜色。","中怀谁可喻，文章亦经国。","一为麟凤言，三叹加餐食。"]},{"t":"五子诗 其一 王元美","f":"五言古诗","c":["元美何翩翩，夙昔秉灵异。","京洛多冠盖，操觚各自媚。","所遇无此物，识曲听其伪。","大雅久沈邈，时淆作者至。","俛仰知音稀，含兹未伸意。","但坐奋逸响，侧身向天地。","虚名喜误人，依依千载事。","浮云相揽持，白日一高视。","四顾命俦匹，中怀谁可致。","凌厉子长气，文章此未坠。"]},{"t":"怀元美","f":"七言绝句","c":["琅琊山上越王台，秋色高临海色开。","莫向中原看落日，浮云万里为君来。"]},{"t":"怀明卿","f":"古风","c":["豫章西望彩云间，九?长江九叠山。","高卧不须窥石镜，秋风憔悴侍臣颜。"]},{"t":"怀子相","f":"七言绝句","c":["越王城上黯销魂，万里秋风动蓟门。","君自平生称国士，南迁岂负信陵恩。"]},{"t":"怀子与","f":"七言绝句","c":["青山忽送七闽秋，大海遥连百粤流。","落日孤城风雨合，褰帷何处不堪愁。"]},{"t":"同元美与子相公实分赋怀太山得钟字柬顺甫","f":"七言律诗","c":["域内名山有岱宗，侧身东望一相从。","河流晓挂天门树，海色秋高日观峰。","金箧何人探汉策，白云千载护秦封。","向来信宿藤萝外，杖厎西风万壑钟。"]},{"t":"渡滹沱","f":"五言律诗","c":["滹沱来不极，晓色荡孤城。","击楫中流过，褰帷下吏情。","天衔纡岸转，日上大波行。","独在知津后，风尘见濯缨。"]},{"t":"子与自芦台量移瑞州 其一","f":"七言律诗","c":["题坐高名汉署来，鱼盐小吏混芦台。","谁怜汝海分符客，自是南皮作赋才。","老骥霜蹄千里动，佩刀寒色九河开。","量移休道非知遇，难得君恩一日回。"]},{"t":"子与自芦台量移瑞州 其二","f":"七言律诗","c":["遥传雨露一时新，不负漂零恋主身。","高卧中原堪有客，雄飞尔辈可无人。","屏星色动双龙曙，锦水光分五马春。","诗兴宦情堪并美，南州孺子况为邻。"]},{"t":"黄泽辞","f":"古风","c":["皇之麋，其马八骊，皇人委蛇。","皇之水，其马騄耳，皇人受祉。","皇之曲洛，其马沃若，皇人薄薄。","皇人孽孽，其马喷雪，我心如结。"]},{"t":"白云谣","f":"古风","c":["白云在天，山陵逶迤。","率彼东土，诸夏间之。","将子能来。"]},{"t":"瑶池谣","f":"古风","c":["白云在山，亦洽而野。","予归三年，将顾见女。"]},{"t":"南山歌","f":"七言古诗","c":["南山白石白离离，尔牛之角何其悲。","车下短衣歌者谁，国有叔牙当见知。","佐命伯王独后来。"]},{"t":"越人歌","f":"楚辞体","c":["山有隈兮江有汜，歌拥枻兮见王子。","揄修袂兮披长云，举绣被兮风纷纷。","蒙诟耻兮心靡它，君不知兮可奈何。"]},{"t":"采葛妇歌","f":"七言古诗","c":["卧下之薪何绸缪，欲寐不寐思寇雠，我今采葛以遨游。"]},{"t":"易水歌","f":"楚辞体","c":["缭天兮白虹，萧萧兮北风。","壮士怒兮易水飞，羽声激兮云不归。"]},{"t":"垓下歌","f":"楚辞体","c":["从美人，拥骏马，涕从横兮垓之下。"]},{"t":"大风歌","f":"楚辞体","c":["大风沸兮云薄天，驱万乘兮纷来旋。","纷来旋兮沛之宫，士桓桓兮福攸同。"]},{"t":"秋风辞","f":"楚辞体","c":["秋风萧萧兮白云晶晶，草木黄落兮鸿雁于征。","兰可佩兮菊可餐，遗佳人兮汾之干。","挟飞龙弓下中流，横大波兮放远游。","灵偃蹇兮翳日来，憺容与兮纷裴徊。","顾帝京兮何壮哉。"]},{"t":"天马歌","f":"古风","c":["天马下阊阖开，汗以血騑离哉。","河之精龙之子，视浮云无万里。","绝流景蹑遗风，今安驾幸回中。","天马徕从西极，经千里归有德。","天马徕竦予身，挟飞电化若神。","天马徕循东道，承灵威服帝皂。","天马徕岁执徐，陕四海将安如。","天马徕出峤山，逝昆仑排玉关。","天马徕龙为友，北击胡驱群丑。"]},{"t":"李夫人歌","f":"古风","c":["去邪来邪，就而视之，纷何被被其徘徊。","寤邪梦邪，就而视之，包红颜其弗明。","步傩傩者谁邪，就而视之，风何萧萧其蔽帷。"]},{"t":"陇上歌","f":"七言古诗","c":["陇上壮士乘䯀骢，带桑鞬服挟秦弓。","七尺大刀搏白虹，丈八蛇矛盘怒风。","战始三交失大刀，且荡且走亡其曹。","弃我䯀骢岩中逃，为我谓乌为客豪。","陇上之水流潺潺，壮士一去不复还。"]},{"t":"蹛林歌","f":"古风","c":["单于庭，阴山下，汉家和亲刑白马。","刑白马，祭龙城，今年蹛林大会兵。"]},{"t":"铙歌 其一 朱鹭","f":"古风","c":["朱鹭猎其缨，茄下行。","鱼在梁，纵复横。","鹈何飞，濡其羽，上书谏其主。"]},{"t":"铙歌 其二 思悲翁","f":"古风","c":["思悲翁，凤凰安宿阿阁中。","夺我美人，思悲翁。","凤凰飞上天，枭子拉沓随转蓬。","狗逐狡兔走，取尔枭子食枭母。"]},{"t":"铙歌 其三 艾如张","f":"古风","c":["艾而张罗罗若云，中有黄雀呼其群。","毛羽摧颓离哉纷。","山出黄雀山嵯峨。","鸿鹄绝四海，君亦难为罗。","我欲从之谗言多，鸿鹄徘徊奈雀何。"]},{"t":"铙歌 其四 上之回","f":"古风","c":["上之回，萧关开。","以待边，单于台。","勒兵十八万，羽林材。","振大旅，鬗长驰。","詟匈奴，臣月支。","朝诸侯王甘泉宫，郡国受计福来同。"]},{"t":"铙歌 其五 翁离","f":"古风","c":["拥离趾中，可筑宫。","兰用葺之，艾尔蓬。","拥离趾中。"]},{"t":"铙歌 其六 战城南","f":"古风","c":["战城南，走城北，转斗不利号路侧。","谓我枭骑，且行出攻。","宁为野乌食，不逐驽马徘徊蒲苇中。","水深黝黝，蒲苇骜骜。","乌亦自不去，客亦自不豪。","梁以集，乌子五，乌母六。","禾黍不食攫腐肉，愿为忠臣何可覆。","伤子良臣，良臣诚可伤。","远道之人，枯骨何葬。"]},{"t":"铙歌 其七 巫山高","f":"古风","c":["巫山高，自言高。","江水深，自言深。","勿复相思，君有他心。","山以蔚蔚，水以汤汤。","何用度之，石用梁。","徘徊远望，泣下沾裳。","愿托黄鹄，东归故乡。"]},{"t":"铙歌 其八 上陵","f":"古风","c":["上陵亦诚美，下津以尚羊。","问客从何来，自言水中央。","芰荷为君衣，芙蓉为君裳。","木兰为君佩，江蓠间杜蘅。","铜池之芝以九茎，光华烛天披金英。","凤凰之集，乍开乍合，蜚览上林，曾不知日月明。","赤翅之鸿，翁杂相随。","白雁何蔚蔚，云为车，风为马。","游阊阖，守谒者。","五色露，何泥泥。","乃在仙人金掌中，凝如膏，美如饴。","愿奉我主饮，延年万岁期。"]},{"t":"铙歌 其九 将进酒","f":"古风","c":["将进酒，称我觞。","纷佳哉，以浩倡。","心所作，未尝闻，徘徊三叹一为君。","君之臣明四时和，国有良工悉索歌。","观者不苦奈子何。"]},{"t":"铙歌 其十 君马黄","f":"古风","c":["君马黄，臣马骊，二马异体同权奇。","徘徊四海美人子，二马相得以千里。","故东非我东，西非我西，南非我南，北非我北。","驾如六飞龙之翼，路訾邪，谓何览。","遨游安终极，二马视驽马。","局促食辕下，将以问驭者。"]},{"t":"铙歌 其十一 芳树","f":"古风","c":["芳树如此之蔚蔚，上有黄鹄以翱翔，下饮兰池鸣锵锵。","二而为侣，三而为行。","芳树拉杂黄鹄伤，秋风萧萧思其乡。","妒人之子妒杀我，君有它心无不可。","黄鹄高飞亦有罗，目欲顾之奈乐何。"]},{"t":"铙歌 其十二 有所思","f":"古风","c":["有所思，乃在燕山隅。","何用问遗君，大秦明月珠。","结以连理带，荐以合欢襦。","又何问遗君，青丝系玉环。","可直千万馀，翠羽绍缭之黄金错其间。","闻君有它心，拉杂其珠摧其环。","摧其环，临高台。","反袂以障之，当风扬其灰。","从今以往，勿复相思。","若复相思，有如此珠，有如此环。","非我可为，鸡鸣狗吠。","我视兄嫂，不言谓何。","东方须臾高奈何。"]},{"t":"铙歌 其十三 雉子","f":"古风","c":["雉子斑如此之趋跄跄，雄来蜚从雌拉沓曳水集于梁。","目以顾之，蔚蔚冥冥，艾而张罗，雉子知得奈我何。","王孙有罗以雉子，黄鹄之罗当千里。","驾以南，驾以北。","朝行出遨游，暮从美人食。"]},{"t":"铙歌 其十四 圣人出","f":"古风","c":["圣人出，应熛怒，赫炎精。","文教洽，武功成。","寒暑德，河海清。","驾六龙，何騑离。","圣人哉，圣人御天以调之。","日月星辰和四时，郡国吏功上所治。","君之臣明远如期。"]},{"t":"铙歌 其十五 上邪","f":"古风","c":["上邪。","我欲与君同心，乐以不可禁。","相思绍缭，谗言罔极，大驾六龙处天侧。","日月出入沧海中，妒人之子难为工。"]},{"t":"铙歌 其十六 临高台","f":"古风","c":["临高台，望江水，江水之流以千里。","黄鹄知得高蜚止，愿遗香草美人子。","关弓问鹄从何来，我主万年亦诚哉。","禾黍不获鹄何食，遨游四海安终极。"]},{"t":"铙歌 其十七 远如期","f":"古风","c":["远如期，宜四海。","皇帝日月所置，有甘露三载。","单于自归大佳以万人，稽首陛下北藩臣。","左右贤王奉国珍，谒者令引之乡殿陈。","橐佗拉沓，就羽蒙戎。","酪酒乃是阏氏之所饮，駃騠生自余吾中。","将进酒，顾其豪，挠以留犁径路刀。","何用赐之，黄金犀毗，赤绨锦袍。","扶伏沮泽，曾不知天子神灵。","从今以往，但居光禄塞下不愿归庭。"]},{"t":"铙歌 其十八 石流","f":"古风","c":["石流津以梁。","无敢曳水，君安所薄，秋风汤汤。","东飞者鹄，北游者河。","中有冥冥之白沙，远道之人谓之何。","兰以有香君不知，愿言怀之遗所思。"]},{"t":"五凤曲","f":"五言律诗","c":["梧桐生高冈，凤凰鸣中央。","三百六十鸟，翁杂朝四方。","其东鸣青鹖，其西鸣鹔鹴。","鸑鷟鸣其阴，鹑雀鸣其旁。"]},{"t":"精列","f":"古风","c":["欲何为？","虽有一介志，慷慨非其时。","慷慨非其时，言从吾所好，混迹于鸱夷。","入宫无美女，名士常见持。","名士常见持，卞和乃卫足，白璧以终疑。","白璧以终疑，还君十五城，抱之宁自奇。","抱之宁自奇，周孔圣殂落，世人莫我知。","虽有一介志，慷慨非其时。"]},{"t":"东光","f":"古风","c":["胡儿平，倭奴何不平。","倭奴利水战，海堑船为城。","诸军彀骑士，驰射难纵横。"]},{"t":"对酒","f":"古风","c":["对酒歌阳春，含意未能申。","请客听其真。","男儿居世无依因，诚独难自绝于要津。","视扶风，称三辅，吏共理之臣。","奉职亦何状，盘桓磬折，关石和钧。","为积书以报诸天官，自公卿大夫士，咸颔其人以君子经纶。","是时贱玉而贵珉，独䠞迫濩落非其伦。","素无跅?之才，四载不迁，敢辞于积薪。","此道当何以具陈，彷徨所欲，归洁其身。"]},{"t":"乌生","f":"古风","c":["黄口四五雀，罗坐秦氏桂树间。","啄啄树上蠹，母子相哺自言安。","唶我。","三河不知为谁家，有轻薄少年。","臂坐一鹞子，鹞子小小如人拳。","出入雀东西，一纵即中两黄口。","毛羽摧颓，魂魄飞上沧浪天。","鹞子下来还少年。","阿母生黄口时，乃在高堂欂栌间。","唶我人民安知雀乳处，窈窕紫深宫中，安从通。","白兔乃在平原大泽中，罗者尚复得脯腊之。","唶我猛虎斑斑南山间，射工尚复得枕藉之。","明珠乃在合浦深渊中，后宫尚得剖以缀其襦。","唶我人民生各有寿命，何须尚复计会贤愚。"]},{"t":"平陵东 其一","f":"古风","c":["太山阳，璆琳琅，有美一人坐明堂。","坐明堂以王者德，大从群臣朝万国。","朝万国，如会同，顾见白云生封中。","生封中，禅梁父，今上皇帝圣神主。"]},{"t":"平陵东 其二","f":"古风","c":["阴山旁，马牛羊，不知何人城朔方。","城朔方，绝大荒，虏两阏氏一贤王。","一贤王，战失利，虎头将军顾骠骑。","顾骠骑曰，归止单于，敢望汉天子。"]},{"t":"王明君吟","f":"五言古诗","c":["我本良家子，承恩入汉宫。","光彩射绮罗，语笑生春风。","君王希召幸，在远谁为通。","汉宫三十六，处处种梧桐。","美女八千名，各各分当熊。","黄金买颜色，丹青多益工。","宁知佳丽人，不出所图中。","黄金犹粪土，丹青复何功。","颜色非可恃，粉黛故难同。","因念长门赋，夙昔亦相蒙。","君王宠自娱，贱妾以和戎。","岂惜贱妾去，但惜长门空。","涕泣顾长门，从此逐秋蓬。"]},{"t":"安期生","f":"古风","c":["安期生，参驾白鹿云中行。","参驾白鹿云中行，下游来，安期生。","白鹿皎皎金为羁，玉为缨。","顾见蓬莱三山十二城，安期生自署其名。","过谒四海五岳，后从麒麟赤凤迎。","禹汤文武不足令，令我今上应太平。","拥护左右贤公卿，稽首圣人大道成。","仙女罗坐吹笛笙，天神八面侍卫明。","流乌衔符翔殿廷。","悲吟我主享万年，皇帝求一得命延。"]},{"t":"长歌行 其一","f":"五言古诗","c":["嗟我谷中兰，猗猗复英英。","秋气日夜至，鶗鴂乃先鸣。","百草不重芳，霜露浩纵横。","栖栖就一役，慷慨非其情。","少壮复何为，老大无成名。"]},{"t":"长歌行 其二","f":"五言古诗","c":["仙人揽紫芝，芳灿如芙蓉。","两耳委其肩，短发以蒙茸。","侍从几玉女，导我入云中。","奉我一丸药，期我于空同。","服之生羽翼，婥约变形容。","顾见云中鹿，婉蜿成白龙。"]},{"t":"长歌行 其三","f":"五言古诗","c":["累累城上星，河汉流清光。","耿耿不能寐，寤言起彷徨。","彷徨立中庭，辽辽夜未央。","白云涂我衣，北风吹我裳。","还坐顾四壁，兰灯一何明。","缄书寄远道，涕泣下纵横。","倦鸟无故林，游子无故乡。","驱车出门去，徒侣相扶将。"]},{"t":"短歌行","f":"古风","c":["驷马可縻，去日难追。","清酒载觞，短歌苦悲。","遨当以游，何能坐愁。","全身遗名，唯有庄周。","凤凰于飞，览彼九围。","但为君故，驾言旋归。","杜门似鄙，离俗似骄。","彷徨所欲，此一何劳。","斑斑猛虎，其尾可履。","郁郁壮心，猝不可抵。","倾侧势利，还自相戕。","覆车不戒，踌躇雁行。","秋风駪駪，转蓬如轮。","漂扬四野，莫知所臻。","鸟不厌高，鱼不厌深。","尔其肆志，载浮载沉。"]},{"t":"当虾䱉行","f":"五言古诗","c":["日月扬光华，云汉垂文章。","五岳高摩天，江海百谷王。","周孔圣有作，大雅岂沦亡。","曲士徒嗷嗷，此道非所详。","嗟予滞末位，慷慨志四方。","左伏吴越波，右以笞中行。","立发而虎视，厉马抚干将。","吾谋适不用，驾言归故乡。"]},{"t":"董逃行","f":"古风","c":["吾欲上谒从蓬莱，遨游三山戏九垓。","阊阖詄荡开，斑璘宫阙楼台，流光倒景徘徊。","但见织女弄杼往来白榆，累累支机十二枚。","河流逶迤，但见丈夫牵牛饮其隈。","问尔凡吏所为，客谢主人乐哉。","教敕酌彼金罍，织女长跪进酒，牵牛陪。","桂树一何摧颓，嫦娥端坐颔其颐。","白兔抱杵，戛树虾蟆栽。","采取甘露一玉杯，服此露，寿以崔嵬。","服此甘露，颜色自好。","陛下长生不老，坐享万年有道。","君臣欢如鱼藻，陛下长与天相保。"]},{"t":"塘上行","f":"五言古诗","c":["塘上双鸳鸯，芙蓉翳其阴。","不自行仁义，何能知妾心。","青蝇一堕耳，琴瑟难为音。","新人入宫时，意已无同衾。","君子在万里，颜色安可任。","念妾平生时，岂谓有中路。","新人断流黄，故人断纨素。","新人种兰苕，故人种桂树。","新人操阳春，故人操白露。","新人日以驩，故人日以悲。","浮云顾我庭，北风动我帷。","恩爱傥中还，皓首以为期。"]},{"t":"秋胡行 其一","f":"古风","c":["太行易驱仕路难为工，太行易驱仕路难为工。","䛕佞丧志，罄折不衷。","自负者忌，自异者攻。","智力相御，莫知所终。","歌以言之，仕路难为工。"]},{"t":"秋胡行 其二","f":"古风","c":["河清可须钟期未易逢，河清可须钟期未易逢。","国士见知，非以先容。","虽有骨肉，中怀莫从。","伯牙绝弦，甘此不恭。","歌以言之，钟期未易逢。"]},{"t":"秋胡行 其三","f":"古风","c":["闇妒相成周客一何疏，闇妒相成周客一何疏。","维彼燕石，明月是居。","爰发深藏，庶用见誉。","即曰瓦甓，孰救其初。","歌以言之，周客一何疏。"]},{"t":"秋胡行 其四","f":"古风","c":["好恶何常显者易为名，好恶何常显者易为名。","一犬吠形，百犬吠声。","如草偃风，夜虫附明。","西子虽姣，不属于盲。","歌以言之，显者易为名。"]},{"t":"相逢行","f":"五言古诗","c":["相逢狭斜间，狭斜不容车。","不知何年少，夹毂问君家。","君家诚易知，甲第城南隅。","黄金为君堂，白玉为门枢。","坐客高堂上，击钟吹笙竽。","将军起行酒，何论冯子都。","兄弟两三人，出入长相须。","大子侍中郎，中子中大夫。","小子复何官，稍迁执金吾。","五日一来归，观者罗长衢。","二弟为雁行，长兄上头居。","东方千馀骑，兄弟一何殊。","入门游后园，银床缠辘轳。","梧桐十二树，一凤将九雏。","梧桐自相值，凤凰自相呼。","音声何啾啾，枝叶以扶疏。","大妇董妖娆，中妇秦罗敷。","小妇邯郸女，颜色世所无。","大人且安坐，为乐良未徂。"]},{"t":"燕歌行 其一","f":"七言古诗","c":["秋风萧瑟吹我裳，蟋蟀寥寥啼我床。","出门四顾非故乡，谁能客游不断肠。","短歌微吟激繁霜，浮云千里一彷徨。","仰看明月流清光，二十八宿罗成行。","高台非阁遥相望，河汉纵横难为梁。","胡马北鸣雁南翔，忧来不知从何方。","慊慊伏枕聊自当，涕从中零安得防，岂不怀归道阻长。"]},{"t":"燕歌行 其二","f":"七言古诗","c":["会日苦少别日多，为君盛年行蹉跎。","忧来援琴聊短歌，羽声慷慨调不和。","悲风四起扬尘沙，浮云摧颓互相加。","人生奄忽若春华，谁家客游常无家。","中曲不觉泪滂沱，揽衣出户夜如何。","众星历历月低河，鸿雁嗷嗷鸣相过，欲往从之畏蔚罗。"]},{"t":"善哉行 其一","f":"古风","c":["来日难期，少合多离。","今日相乐，不醉何为。","寥寥北堂，哀竹苦丝。","短歌裂耳，慷慨以悲。","白日云没，秉烛继之。","何昼何夜，迨我盛时。","烹肥击鲜，斗酒自随。","安知王乔，八公者谁。","促坐行觞，交属所私。","百年如寄，当复何疑。","慊慊惜费，智者所嗤。","计会有无，将以奚遗。"]},{"t":"善哉行 其二","f":"古风","c":["巢父洁身，天下为污。","四岳九官，而无匹夫。","傅说筑岩，维时商实。","爰立作相，不俟终日。","尚避海滨，二老是丽。","既载后车，三圣所师。","仲未伯齐，三逐何鄙。","生有父母，知有鲍子。","伯阳犹龙，和光同尘。","刍狗万物，圣而不仁。","丘明修辞，古之国工。","纵横六经，化裁与同。","干木偃息，大魏以藩。","式则闭门，迫则踰垣。","庄周非人，蓬累而行。","逍遥弄世，乃称达生。"]},{"t":"西门行","f":"古风","c":["出西门，步踟蹰。","相逢不作乐，当复何须。","但作乐，勿复问有无。","安知家人生产当复溷吾徒。","君击筑，我和歌。","请为燕市饮，旁人当奈何。","人生欲知己，结交不在多。","岂无车马客，富贵相经过。","自非名卿鲍叔牙，虽有国士谁当知。","自非名卿鲍叔牙，虽有国士谁当知。","与君重自爱，中道有别离。","区区抱苦心，可用不相疑。"]},{"t":"东门行 其一","f":"古风","c":["出东门，顾且望。","欲何归，向洛阳。","座下两走马，马上结束千金装。","挥鞭酒家去，调笑邯郸倡。","作使博，徒数辈，掷钱百万少年场。","少年场，朝用广平公故，暮为琅琊大王。","男儿结交愿得豪贤，君复自爱莫相忘。","男儿结交愿得豪贤，君复自爱莫相忘。","恩仇分所当，翩翩轻薄殊未央。"]},{"t":"饮马长城窟行","f":"五言古诗","c":["萧萧山上草，悠悠山下道。","长城一何长，远望多悲伤。","远望不如归，游子日依依。","依依复累累，涕泣当为谁。","高台知天风，鸿雁知天霜。","欲媚更无人，欲去更彷徨。","浮云西北来，我马顾之鸣。","愿附尺素书，迢迢东南行。","浮云不可托，素书不可成。","十年违室家，安知即平生。"]},{"t":"上留田行","f":"古风","c":["人生一何相悬，哲士常见未然。","愚夫不睹目前，所较以千年。","今尔忽怨苍天非、世淆乱，谁贵圣贤。"]},{"t":"孤儿行","f":"古风","c":["孤儿生，孤儿生，命不如，一抔土。","父母在时坐长筵，雷大鼓。","父母已去，兄嫂令我报府。","今年护羌，明年击胡虏。","六月来归，不得自言苦。","目汁稠浊，头面生疮。","大兄言视饭，大嫂言溉釜。","上高堂，不见父与母。","下堂孤儿，泪下如缕。","使我朝行薪，暮不得束刍。","顷筐敝漏，缉之用荼。","钩折无喙，镰钝无肤。","舍镰拔丛，棘棘断行。","复苏刺伤我手，复裂我襦。","自念犹人，谁使为奴。","兄嫂如此，为不早去。","下从地下，当复何须。","高秋八九，月堕严霜。","百草凋枯，牧竖绝粮。","驱羊下山，逸入他群，不辨所亡。","愿取我羔，莫攘我羊。","羊复恋子，箠之不将。","弃箠挽角，羊僵道傍。","拽羊回家，兄与嫂睨。","三年不乳，毛尾空长，作何校计。","乱曰：羊鸣一何芊芊。","父母地下，将书寄与兄嫂：尔爱其羊，我爱其子。"]},{"t":"怨诗行","f":"五言古诗","c":["荆山何岩岩，白璧何齿齿。","圭璋满朝廷，尔胡独在此。","千载抵尘沙，一抱即知己。","瓦砾生目中，众人纷所指。","五都当一顾，三献不得理。","一刖藏白虹，再刖涸沂水。","玉石苟不分，安用存吾趾。","昭王遣使问，慷慨不可止。","一剖属白虹，再剖折沂水。","至今为宗器，天下称其美。","愿以陵阳侯，还之乐正子。"]},{"t":"白头","f":"五言古诗","c":["青如雪中柏，凿如水中石。","自君有两意，事事非畴昔。","畴昔共绸缪，何尝不胶漆。","今日不胶漆，明日即参商。","东西大道上，车马遥相望。","新人此一时，故人彼一时。","难将故人意，持与新人知。","非不结同心，人情中道还。","白头百年期，岂作斗酒间。","云汉何绳绳，星宿何累累。","意气一以失，黄金不可为。","决如溃防川，绝如蹶张弦。","有亲相推与，无亲私自怜。"]},{"t":"艳歌何尝行","f":"古风","c":["何尝快独平生。","但当被华縠，猎长缨。","起家为二千石，四十以专城。","兄弟纵横要路，车马络绎，往来公卿显者行。","但当在高堂，置酒快独，呼我所欢。","五陵少年，任侠知名。","主人称寿，以乐上宾。","揽持绮丽，杂坐弹筝。","触抵安足诤，岁月忽如流。","愿言重自爱，吾夙昔与君共绸缪。","朝亦复苦愁，暮亦复苦愁。","辟彼东逝之川，汎汎不系之舟。","浮云转薄心悠悠，有似客游难久留。"]},{"t":"艳歌行 其一","f":"五言古诗","c":["皎皎月中兔，罗网安得错。","夫婿流宕子，翩翩长道路。","上堂事舅姑，下堂力蚕作。","日出行采桑，春风动纨素。","不知何年少，踟蹰西北顾。","请君且莫顾，黄金徒自误。","黄金道路傍，谁当见国卿。"]},{"t":"艳歌行 其二","f":"五言古诗","c":["童童河上柳，朝荣暮来朽。","人生天地间，何可日无酒。","偃蹇谁当闻，忼慷谁当有。","赖得心所欢，嚼我以大斗。","醉后唱高言，掩耳使一走。","语卿且勿走，不如舌在口。","舌在难为扪，叹尔欲行恩。"]},{"t":"艳歌行 其三","f":"五言古诗","c":["南海一何长，明珠一何光。","大珠抵明月，小珠烛中堂。","洛阳发中使，明珠窃自伤。","没海采是珠，珠泪以从横。","持作木兰匮，送至洛阳宫。","后宫莫不叹，问珠从何方。","谁能复市此，隋侯与孟尝。","用玉绍缭之，黄金错其中。","缀之用翡翠，薰用苏合香。","本自南海珠，今为后宫珰。"]},{"t":"满歌行","f":"古风","c":["得意良独难。","大带如河，高弁如山。","功名侮予，心不遑安。","遥望故乡，郁郁漫漫。","忧来自中，不逊于颜。","鄙士患得失，达士多所宜。","智不斗时。","我斯荡荡，天下熙熙。","俛拾仰取，日竞刀锥。","逝将掉臂，弃而违之。","东蹈沧海，宁居九夷。","崄巇可为，念为偃息，乃在草莱。","蹲而踰垣，嗒焉凿坯。","流俗落落，岂无友生。","门一以杜，其可复开。","蜉蝣之裳，视此末荣，宠辱者惊。","寓言愤世，混迹躬耕。","贫贱肆志，惰傲相成。","徘徊千古，载浊载清。","饮酒而已，谁知其它。","即有三公，相去几何。","百年如寄，孰少孰多。","胡朝谋夕，自贻蹉跎。","屹彼在位，经营四方。","天道病愚，人道趋彊。","退而为乐，辽辽未央。"]},{"t":"企喻歌 其一","f":"五言绝句","c":["男儿自言彊，出门思故乡。","陇水流离下，泪落铁裲裆。"]},{"t":"企喻歌 其二","f":"五言绝句","c":["放马大泽中，马饱勿复驱。","宁断壮士肉，不断骏马刍。"]},{"t":"企喻歌 其三","f":"五言绝句","c":["鹞子下狡兔，不顾黄雀群。","男儿饱百战，少年笑杀人。"]},{"t":"企喻歌 其四","f":"五言绝句","c":["男儿重意气，结伴不须钱。","谁能无兄弟，千里不相怜。"]},{"t":"琅琊王歌 其一","f":"五言绝句","c":["阳春二三月，单衫绣裲裆。","系马临大道，值女行采桑。"]},{"t":"琅琊王歌 其二","f":"五言绝句","c":["炎天五六月，挈枕逐阴凉。","絺服不掩体，唤女汲寒浆。"]},{"t":"琅琊王歌 其三","f":"五言绝句","c":["初寒八九月，银烛照高堂。","端然坐不睡，看女织流黄。"]},{"t":"琅琊王歌 其四","f":"五言绝句","c":["盛冬十一月，调笑酒垆傍。","玉壶出纤手，索女弄丝簧。"]},{"t":"琅琊王歌 其五","f":"五言绝句","c":["主人但置酒，烹肥击其鲜。","男儿好还乡，不愿持一钱。"]},{"t":"琅琊王歌 其六","f":"五言绝句","c":["孤儿当门泣，门外霜皓皓。","今年许裁襦，兄但视其嫂。"]},{"t":"琅琊王歌 其七","f":"五言绝句","c":["骏马似人长，金鞭五尺强。","往来渭桥上，琅琊大道王。"]},{"t":"琅琊王歌 其八","f":"五言绝句","c":["新买五尺刀，摩挲不离手。","但来看此物，军中谁更有。"]},{"t":"钜鹿公主歌","f":"七言古诗","c":["邯郸女儿年十五，能弹琵琶唱乐府。","头上明珠间翠羽，客与酒钱笑不数。","可怜误嫁阳翟贾，遂使黄金暗如土。"]},{"t":"紫骝马歌 其一","f":"五言绝句","c":["出入渭城中，少年独妍雅。","不知是阿谁，但识紫骝马。"]},{"t":"紫骝马歌 其二","f":"五言绝句","c":["紫马从西来，道逢一骊驹。","两人下马揖，便入酒家胡。"]},{"t":"紫骝马歌 其三","f":"五言绝句","c":["问客复何为，昨日发东平。","袖中出短书，心知自刘生。"]},{"t":"紫骝马歌 其四","f":"五言绝句","c":["对客读短书，慷慨不能止。","拔剑出门去，报雠燕市里。"]},{"t":"黄淡思歌 其一","f":"五言绝句","c":["肠作辘轳转，泪作素绠垂。","独坐不能言，傍知思忆谁。"]},{"t":"黄淡思歌 其二","f":"五言绝句","c":["胡马代州出，还骑出代州。","黄金装马勒，青丝络马头。"]},{"t":"地驱乐歌","f":"古风","c":["萧萧条条，风雨漂摇。","饿杀鹪鹩，撑杀䲭鸮。","倦鸟不飞，非无羽翼。","贫女不嫁，非无颜色。","枕郎右臂，郎侧向左。","看郎颜色，似不在我。","宛转郎怀，坐郎左膝。","郎有它人，不自今日。"]},{"t":"雀劳利歌","f":"七言绝句","c":["稂莠骄骄雀劳利，前有鹞子后老鸱。","与郎十期九不果，郎有它人休误我。"]},{"t":"捉搦歌 其一","f":"七言绝句","c":["仕宦还须论知己，结交还须论君子。","男儿失意悔人指，老女不嫁难为理。"]},{"t":"捉搦歌 其二","f":"七言绝句","c":["东家女儿大狡狯，屋里烧香出墙外。","供养世尊作佛会，愿得百媚无菑害。"]},{"t":"捉搦歌 其三","f":"七言绝句","c":["邯郸城南夜逆旅，楼头十五谁家女。","可怜白马空儃伫，不见其人但闻语。"]},{"t":"捉搦歌 其四","f":"七言绝句","c":["骏马凭陵粟在口，男儿精神钱在手。","何不结伴日沽酒，出臂苍鹰使黄狗。"]},{"t":"折杨柳歌 其一","f":"五言绝句","c":["上马折杨柳，杨柳郁葳蕤。","马上吹长笛，愁杀虏家儿。"]},{"t":"折杨柳歌 其二","f":"五言绝句","c":["不惜折杨柳，孟津杨柳西。","本是虏家女，嫁作汉儿妻。"]},{"t":"折杨柳歌 其三","f":"五言绝句","c":["放马孟津岸，饮马孟津河。","虽是虏家儿，爱听汉儿歌。"]},{"t":"折杨柳歌 其四","f":"五言绝句","c":["莫折杨柳枝，婆娑动郎意。","自有珊瑚鞭，出入擐郎臂。"]},{"t":"折杨柳歌 其五","f":"五言绝句","c":["上马出门去，马鞭持与郎。","郎度孟津水，何时还故乡。"]},{"t":"幽州马客吟歌 其一","f":"五言绝句","c":["客从幽州来，百万为摴蒱。","钱自它人有，意气良所无。"]},{"t":"幽州马客吟歌 其二","f":"五言绝句","c":["今日但一掷，何言无所持。","庭前两走马，千里任君骑。"]},{"t":"幽州马客吟歌 其三","f":"五言绝句","c":["自怜十指镮，玉壶不离手。","女儿行无赖，故劝郎君酒。"]},{"t":"幽州马客吟歌 其四","f":"五言绝句","c":["南山固言高，上有北流泉。","女儿固言好，须得郎自怜。"]},{"t":"幽州马客吟歌 其五","f":"五言绝句","c":["郎赍千金装，结客行三秦。","那能论家计，少年喜作人。"]},{"t":"慕容家自鲁企由谷歌","f":"五言绝句","c":["鸟中有鹞子，人中有慕容。","慕容家此谷，少年多相从。"]},{"t":"高阳乐人歌 其一","f":"五言绝句","c":["欲知马上儿，但复看儿马。","结束殊轻薄，不在汉儿下。"]},{"t":"高阳乐人歌 其二","f":"五言绝句","c":["郎来但坐饮，百壶分自当。","见郎行仁义，无钱何所妨。"]},{"t":"团扇郎","f":"古风","c":["白团扇。","明月入君怀，清光满流盼。","霜雪散炎天，是侬歌始变。","合欢自一时，秋风欢不见。"]},{"t":"前溪歌 其一","f":"五言绝句","c":["逍遥东武亭，下有独桑路。","欢但宿侬家，前溪不可度。"]},{"t":"前溪歌 其二","f":"五言绝句","c":["朝思出前溪，暮思出前溪。","溪流乱漫下，谁见倚门啼。"]},{"t":"前溪歌 其三","f":"五言绝句","c":["女萝著长松，蔓与长松长。","虽非岁寒姿，愿得被风霜。"]},{"t":"前溪歌 其四","f":"五言绝句","c":["黄葛生溪边，溪水东西流。","枝枝自缠绕，叶叶自绸缪。"]},{"t":"前溪歌 其五","f":"五言古诗","c":["春容故易老，红粉岂常鲜。","郎归定何日，憔悴复谁怜。","怜亦异当年。"]},{"t":"前溪歌 其六","f":"五言古诗","c":["谁能采黄葛，逍遥独桑头。","黄葛断还生，春风不可留。","烂漫使侬愁。"]},{"t":"前溪歌 其七","f":"五言古诗","c":["葵藿自有心，兰蕙自有香。","黄瓜一小草，春风独不忘。","枝叶顿芬芳。"]},{"t":"子夜歌 其一","f":"五言绝句","c":["涉江种芙蓉，青荷几时有。","但使莲心生，何虑不成偶。"]},{"t":"子夜歌 其二","f":"五言绝句","c":["桑叶老欲尽，春蚕已就眠。","那能不作茧，丝子自缠绵。"]},{"t":"子夜歌 其三","f":"五言绝句","c":["彊言共寝食，十日九不俱。","桐花夜夜落，梧子暗中疏。"]},{"t":"子夜歌 其四","f":"五言绝句","c":["出亦阴忆汝，入亦阴忆汝。","石阙四面生，悲来定何许。"]},{"t":"子夜歌 其五","f":"五言绝句","c":["荡舟芙蓉池，红颜在池水。","侬与芙蓉花，有何不相似。"]},{"t":"子夜歌 其六","f":"五言绝句","c":["宿昔结同心，丝发与眉齐。","转动如春风，不离郎君怀。"]},{"t":"子夜歌 其七","f":"五言绝句","c":["相怜须及时，红颜不难老。","郎自行由豫，它人已相保。"]},{"t":"子夜歌 其八","f":"五言绝句","c":["始欲识侬时，白头誓相怜。","一日三唐突，持底解千年。"]},{"t":"子夜歌 其九","f":"五言绝句","c":["欢心杨柳花，春风为颠倒。","到头有感化，不离浮萍草。"]},{"t":"子夜歌 其十","f":"五言绝句","c":["愿因斗酒会，发欢桃花容。","蹉跎自不饮，双杯持劝侬。"]},{"t":"四时子夜歌 其一","f":"五言绝句","c":["春鸟既集渚，春花复著林。","高台不可望，春色荡侬心。"]},{"t":"四时子夜歌 其二","f":"五言绝句","c":["绮窗媚初月，罗帐褰春风。","欢复自顾虑，崎岖当奈侬。"]},{"t":"四时子夜歌 其三","f":"五言绝句","c":["三伏天雨火，郎但笼窗坐。","何处汲寒浆，金瓶井中堕。"]},{"t":"四时子夜歌 其四","f":"五言绝句","c":["婉伸华簟上，不下葳蕤钥。","郎君已自前，罗衣那及著。"]},{"t":"四时子夜歌 其五","f":"五言绝句","c":["庭含明月光，蟋蟀入床语。","独自理寒衣，秋风动砧杵。"]},{"t":"四时子夜歌 其六","f":"五言绝句","c":["荧荧斜月辉，累累清露垂。","中宵不还卧，徘徊独为谁。"]},{"t":"四时子夜歌 其七","f":"五言绝句","c":["郎从何处来，重袍那如水。","酒无沙糖味，为他沃寒尔。"]},{"t":"四时子夜歌 其八","f":"五言绝句","c":["北风振枯林，严霜杀百草。","欢不与时竞，独向相思老。"]},{"t":"懊侬歌 其一","f":"五言绝句","c":["五丝合欢被，还得五丝缝。","侬为懊恼曲，还持懊恼侬。"]},{"t":"懊侬歌 其二","f":"五言绝句","c":["布帆百馀幅，阿娜自生风。","江水满如月，那得不愁侬。"]},{"t":"懊侬歌 其三","f":"五言绝句","c":["夙昔幽闺性，冶游持自惑。","旦夕三千里，不复作颜色。"]},{"t":"懊侬歌 其四","f":"五言绝句","c":["长江得春风，使帆如使马。","朝发牛渚矶，暮宿白门下。"]},{"t":"神弦歌三首 其一 宿阿曲","f":"五言绝句","c":["天门詄荡荡，地户郁沈沈。","真官下云中，窈窕从苏林。"]},{"t":"神弦歌三首 其二 道君曲","f":"古风","c":["中庭有树，其实诩诩。","道君出入，先以风雨。"]},{"t":"神弦歌三首 其三 圣郎曲","f":"五言古诗","c":["梧桐何翼翼，凤凰何将将。","左坐青溪姑，右坐白石郎。","姑自翳瑶草，郎自命椒浆。"]},{"t":"娇女诗 其一","f":"五言古诗","c":["朝游青溪南，暮游青溪北。","娇女年十五，芙蓉比颜色。","终日奏弦歌，小姑独相识。"]},{"t":"娇女诗 其二","f":"五言古诗","c":["徘徊白石江，蹀躞赤山矶。","湘绮为下裳，紫绮为上衣。","自绣双鸳鸯，十十五五飞。"]},{"t":"白石郎曲 其一","f":"古风","c":["郎之徕，何纷员。","车以清风马以云。","前有明姑后道君。"]},{"t":"白石郎曲 其二","f":"五言绝句","c":["石子如弹丸，累累江之渚。","有郎独自居，艳于十五女。"]},{"t":"青溪小姑曲","f":"古风","c":["青溪汤汤，白石为梁。","小姑不嫁，谁谓无郎。"]},{"t":"湖就姑曲","f":"五言古诗","c":["北游赤山湖，遥望中芙蓉。","裁衣赠大姑，大姑舞白鸠。","仲姑渌水歌，不共小姑愁。"]},{"t":"姑恩曲 其一","f":"古风","c":["明姑遵云中，葳蕤六萌车。","前驾斑璘兽，后从朱鸟麟辟邪。"]},{"t":"姑恩曲 其二","f":"五言绝句","c":["诸姑亦道同，独有明姑尊。","桂酒黄金色，持以报姑恩。"]},{"t":"采莲童曲 其一","f":"五言绝句","c":["扣楫声太苦，听我采莲歌。","且将盛年容，持比芙蓉花。"]},{"t":"采莲童曲 其二","f":"五言绝句","c":["西湖采莲舟，上有愁思妇。","不摘芙蓉花，何因出素手。"]},{"t":"明下童曲 其一","f":"五言绝句","c":["走马上越桥，遗却黄金鞭。","遥望射堂头，徘徊骄不前。"]},{"t":"明下童曲 其二","f":"五言绝句","c":["赭白千里姿，斑骓八百馀。","乘不独自去，日与陆郎俱。"]},{"t":"同生曲 其一","f":"五言绝句","c":["盛时不再逢，百岁一何促。","愿以南山松，秉作夜游烛。"]},{"t":"同生曲 其二","f":"五言绝句","c":["蟋蟀空局促，人命安可为。","但当饮美酒，醉即蒿里歌。"]},{"t":"石城曲 其一","f":"五言绝句","c":["可怜冶游郎，大马高缠騣。","冶游石城下，闻名少年中。"]},{"t":"石城曲 其二","f":"五言绝句","c":["珂峨同心髻，环插三子钗。","种种随时变，懊恼郎君怀。"]},{"t":"石城曲 其三","f":"五言绝句","c":["阳春二三月，花与郎同色。","明知苦淹留，盛年不可得。"]},{"t":"石城曲 其四","f":"五言绝句","c":["大艑十八橹，长篙如竹林。","张帆看风色，知是下江陵。"]},{"t":"乌夜啼 其一","f":"五言绝句","c":["石城诸少年，歌舞日相新。","刘生安东平，是郎得意人。"]},{"t":"乌夜啼 其二","f":"五言绝句","c":["长樯百幅帆，常著千里风。","婀娜樯上佳，飞逐不成双。"]},{"t":"乌夜啼 其三","f":"五言绝句","c":["大帆曳云还，长樯柱天起。","非是不相留，势已无千里。"]},{"t":"乌夜啼 其四","f":"五言绝句","c":["乌生秦氏家，不从秦氏栖。","夜夜将九子，石城城上啼。"]},{"t":"乌栖曲 其一","f":"七言绝句","c":["芙蓉如绣柳如织，浣纱渡头日将匿。","高髻双珠玳瑁簪，采莲一曲倾江南。"]},{"t":"乌栖曲 其二","f":"七言绝句","c":["珠履错落华灯光，长袖宛宛属羽觞。","含笑一转心相知，谁能不前复自持。"]},{"t":"乌栖曲 其三","f":"七言绝句","c":["黄金匼匝葳蕤钥，北斗阑干城上落。","美人空床夜不眠，双双玉箸下灯前。"]},{"t":"乌栖曲 其四","f":"七言绝句","c":["江南女儿蹋蹀歌，阳春窈窕出绮罗。","黄金辔头紫骝马，长安少年事游冶。"]},{"t":"估客乐 其一","f":"五言绝句","c":["估客从杨州，大艑载何来。","有无郎寄书，但语莫徘徊。"]},{"t":"估客乐 其二","f":"五言绝句","c":["估客广州人，出入三江口。","一艑载三千，娘但日沽酒。"]},{"t":"莫愁乐 其一","f":"五言绝句","c":["何来诸少年，石城迎莫愁。","莫愁石城西，门前江水流。"]},{"t":"莫愁乐 其二","f":"五言绝句","c":["莫愁善西曲，曲曲变新声。","含意娇不发，春风感人情。"]},{"t":"莫愁乐 其三","f":"五言绝句","c":["莫愁幽闺性，非但倾城色。","石城诸少年，人人自相识。"]},{"t":"莫愁乐 其四","f":"五言绝句","c":["何处寻莫愁，石城诸少年。","可怜六萌车，不送莫愁还。"]},{"t":"襄阳乐 其一","f":"五言绝句","c":["朝上大堤头，暮上大堤头。","大堤诸女儿，游冶不知愁。"]},{"t":"襄阳乐 其二","f":"五言绝句","c":["女萝复可缝，兔丝复可织。","唯有菖蒲花，郎自不曾识。"]},{"t":"襄阳乐 其三","f":"五言绝句","c":["大堤诸女儿，歌舞日相逐。","郎今定怜谁，夙昔谁家宿。"]},{"t":"襄阳乐 其四","f":"五言绝句","c":["郎君但坐饮，听我白雪弦。","十三工西曲，自不工数钱。"]},{"t":"襄阳乐 其五","f":"五言绝句","c":["杨州大估客，千金作一装。","谁敢攀贵德，牵坏侬衣裳。"]},{"t":"襄阳乐 其六","f":"五言绝句","c":["诧侬断信使，还书亦不作。","微薄自怜侬，欢岂自微薄。"]},{"t":"三洲歌 其一","f":"五言绝句","c":["何处估客豪，杨州估客豪。","象牙持作樯，鍮石持作篙。"]},{"t":"三洲歌 其二","f":"五言绝句","c":["闻欢扬州去，大艑居上头。","一载五百万，两载千万馀。"]},{"t":"三洲歌 其三","f":"五言绝句","c":["何来板桥湾，持底唤沽酒。","两丛蒱锻镮，问侬取不取。"]},{"t":"襄阳蹋铜蹄 其一","f":"五言绝句","c":["白马蹋铜蹄，着地铜蹄鸣。","往来大堤上，出入襄阳城。"]},{"t":"襄阳蹋铜蹄 其二","f":"五言绝句","c":["大马珂峨头，一步三舂锄。","借问马上儿，家在襄阳不。"]},{"t":"襄阳蹋铜蹄 其三","f":"五言绝句","c":["白马金络头，一步三駊騀。","便是马上郎，何尝不婀娜。"]},{"t":"襄阳蹋铜蹄 其四","f":"五言绝句","c":["阳春二三月，襄阳好徘徊。","渌酒汉江色，与郎传一杯。"]},{"t":"青骢白马","f":"七言古诗","c":["青骢踯躅八尺强，黄金络头丝作缰。","可怜白马如人长，着地徘徊自生光。","青骢白马冶游郎，劳君下都看三阳。","可怜白马逐青骢，石桥柏梁五湖东。","青骢白马六萌车，可怜今夜宿谁家。","借问窈窕西曲娘，白马青骢去无常。","借问窈窕西曲女，石城莫愁凭寄语。","齐唱可怜泪沾裳，可怜三声忘故乡。"]},{"t":"长松标","f":"五言绝句","c":["落落南山松，长标一何拙。","上栖万里风，下覆千年雪。"]},{"t":"双行缠","f":"五言绝句","c":["朱丝葳蕤绳，是侬双行缠。","绕腕结同心，傍人那得见。"]},{"t":"黄督","f":"五言绝句","c":["谁能见歌舞，不自爱阳春。","少年双泪落，知是他乡人。"]},{"t":"作蚕丝 其一","f":"五言绝句","c":["拾蚕蚕如指，出桑桑如掌。","一日三箔眠，交侬那得往。"]},{"t":"作蚕丝 其二","f":"五言绝句","c":["大茧大如卵，小茧垂其腴。","三秋上织作，君看罗绣襦。"]},{"t":"碣石篇 其一","f":"古风","c":["碣石中怒，沧海北倚。","元气吐欱，若偃若起。","长风相薄，跳波千里。","悬流冒颠，天汉外纪。","地轴高摽，毂转白日。","与齐俱入，与汩偕出。"]},{"t":"碣石篇 其二","f":"古风","c":["凉秋九月，塞外草衰。","白日萧条，北风苦悲。","边声四起，胡马成群。","爝火如星，列障如云。","钱镈既置，修我戈矛。","裹粮坐甲，唯敌是求。"]},{"t":"碣石篇 其三","f":"古风","c":["委蛇者河，千里一曲。","方之舟之，匪刍伊粟。","太行诘屈，西北是经。","车辙马迹，日不遑宁。","于铄圣人，依其在京。","差次吏功，郡国以成。"]},{"t":"碣石篇 其四","f":"古风","c":["羽翼未就，鸿鹄徘徊。","神龙失水，蝼蚁所裁。","珠不暗投，剑不倒持。","能弗用利，勿处于疑。","高才者妒，匪但在人。","逃名避世，以保其身。"]},{"t":"白纻舞歌 其一","f":"七言古诗","c":["华镫参差月舒光，笛箫笙竽琴瑟张。","馆娃窈窕夜未央，西施起舞属吴王。","白纻飒沓零繁霜，浮云绰约凝且翔。","将绝复引歌为长，回身急入促管藏。","扬跗摩趺匝洞房，流风徘徊生绣裳。","答桴应节蹈鼓行，挺钗欲堕复不遑。","罗袖缭绕满中堂，与志变化无恒常。","诸工竞写忽已忘，迁延就次进羽觞。"]},{"t":"白纻舞歌 其二","f":"七言律诗","c":["二八齐容罗象筵，激楚之结独秀先。","白纻萧索阳春前，回风飞雪相流连。","玉腕缭绕萦繁弦，朱唇宛转含蹁跹。","将行复却私自怜，愿君蹋歌及盛年。"]},{"t":"白纻舞歌 其三","f":"七言古诗","c":["春日荏苒花落英，吴姬起舞媚前楹。","回身顿趾迅且轻，纤尘暗暧不及生。","投袂一转激楚成，徘徊复进为新声。","二八敛手停鸣筝，中曲再变豪竹惊。","如矜若怨意未明，馀姿逸态犹纵横。","妙技绝世色倾城，谁能顾盻感人情。"]},{"t":"白纻舞歌 其四","f":"七言古诗","c":["双袖徐起若有思，逸态一放横难持。","淫衍诘屈纷陆离，流纨曳縠风委迤。","萦尘逗节利屣施，纡形赴曲影不知。","纤腰欲结行缀移，众变沓至生繁姿。","踌躇中止人尽疑，浮腾绝迹称神奇。","游精荡志君自治，大乐万岁远如期。"]},{"t":"霹雳引","f":"七言古诗","c":["平成天地剖九州，罗列五岳江河流。","明堂受计朝诸侯。","人马辟易气纵横，悲歌慷慨志不平。"]},{"t":"天马引","f":"楚辞体","c":["胡风雨駪駪而空，山有人踯躅兮悲鸣。","匝余室兮三行。"]},{"t":"蝶蝶行","f":"古风","c":["蝶蝶翻翻戏，游来东园苜蓿中。","不知谁家涎涎乳子燕，衔之我入窈窕紫深宫。","紫深宫，欂栌间，高坐顑颔待哺两黄口。","睨之阿母得食还，摇头鼓翼。","谁忍视蝶蝶，轻薄亦可怜。"]},{"t":"悲歌","f":"古风","c":["慷慨乃知故人，徘徊乃知故乡。","远道多怀，久客自伤。","欲驾车无輗，欲渡河无梁。","中夜顾形影，泣下沾衣裳。"]},{"t":"猛虎行","f":"古风","c":["饥且从漂母食，寒且从巢父栖。","石不为周客笑，玉不为楚王啼。","菅茅但塞路，桃李自成蹊。"]},{"t":"枯鱼过河泣","f":"五言古诗","c":["大鱼啖小鱼，小鱼啖虾䱉。","虾䱉啖沮洳。","啖多沮洳涸，请君肆中居。"]},{"t":"远游篇","f":"五言古诗","c":["万里未足步，过谒历遐荒。","一举驾黄鹄，再举凌云翔。","澄氛隐北斗，河汉集为梁。","山川自纡曲，天地自圜方。","六鳌抃蓬莱，十日弹扶桑。","潮水怒相击，昆崙出中央。","流览临九州，众人何茫茫。","絪缊造元气，控揣成阴阳。","黔羸秉大钧，丛脞不可当。","道逢王子乔，揖我还故乡。"]},{"t":"广齐讴行","f":"五言古诗","c":["不劳歌楚艳，请为罢吴趋。","上客但安坐，听我奏齐讴。","鹰扬表东土，赐履维青州。","沃壤既如膏，丝枲韧且柔。","鱼盐无俭岁，海王自春秋。","百二敌彊秦，八九吞徒州。","美哉一匡力，天下咸宗周。","朝服西济河，鞭箠使诸侯。","至今临淄途，诵义慕前修。","枹鼓立军门，意气纵横浮。","举袂成帏幕，攘臂赴仇雠。","先君务养士，奕世恢鸿猷。","晏婴以当路，结交鲁孔丘。","其人聘列国，终日无停辀。","及闻箾韶音，若与唐虞游。","三月忘寝食，栖栖此淹留。","季札本荆蛮，华夏多夷犹。","泱泱叹大风，观采不能休。","五伯桓称首，四豪文其尤。","拥彗为宾师，铁笼存主忧。","阔达有遗俗，功利非所谋。","驰骋一何䧺，冠剑常相求。","蠋辞万家邑，连谢千金酬。","即论二布衣，岂复商贾流。"]},{"t":"前缓声行","f":"古风","c":["海中之山，必有天上之河。","人知其一，莫知其它。","自非意气轻黄金，结交宁足多。","当复思东来之兔，必有西去之乌。","不舍昼夜，曾何爱于吾徒。","长笛不呼短笛呼，愿君有酒即饮无酒酤。"]},{"t":"结客少年场","f":"五言古诗","c":["翩翩白马客，游冶长安城。","自矜有侠骨，肮脏多交情。","羞倚将军势，讵借傍人名。","利剑一在掌，四海皆弟兄。","片言出肝胆，杯酒如平生。","恩雠等白日，然诺千金轻。","君看少年场，意气谁纵横。","骂坐亦已粗，探丸非老成。","浅之为丈夫，贤豪大所营。","长兄推鲁连，仲兄推虞卿。","小弟处囊中，黾勉荆楚行。","但令称国士，不必取先鸣。"]},{"t":"东飞伯劳歌","f":"七言古诗","c":["东飞伯劳西飞鹊，黄金仓琅葳蕤钥。","谁家女儿倚高楼，含娇吐怨弹箜篌。","明珠翠羽红粉妆，单衫婀娜春风香。","女儿年几十五馀，开颜发艳玉不如。","箜篌宛转作新声，可怜一曲倾人城。"]},{"t":"乐府","f":"古风","c":["群胡款朝那，请与汉家和。","紫貂黄羊白橐驼，单于阏氏乘六骡。"]},{"t":"河中之水歌","f":"七言古诗","c":["河中之水流迢迢，洛阳女儿名娇娆。","娇娆十三称绝色，十四怀春未可挑。","才梳堕髻即殊众，怕逐时人斗小腰。","学成织锦机犹涩，解度新声瑟懒调。","日出采桑城东路，路傍桃李花飘姚。","左手提笼丝作系，右手攀花折其条。","国卿下装不复顾，使君五马徒相邀。","董家高楼一百尺，归来谁见倚逍遥。"]},{"t":"郡斋同元美赋得阴字","f":"古风","c":["漳之浔，大陆阴。","天落落，日骎骎。","谁为郡，此滞淫。","君在坐，倍萧森。","嗟波及，邈陆沈。","酌我酒，听长吟。","秋无色，风雨深。","山欲出，薜萝侵。","泪相视，卧独临。","沧海梦，白云心。","来何处，别至今。","重握手，一知音。","孤城夜，枫树林。","漂短发，问抽簪。"]},{"t":"效阮公 其一","f":"古风","c":["太清孔阳，元气絪缊。","灵曜悬鉴，列宿垂文。","威凤振羽，神龙作鳞。","蕙兰幽郁，松桂轮囷。"]},{"t":"效阮公 其二","f":"古风","c":["日照月临，天高气清。","金支秀华，羽林翠旌。","六驾龙秋，四牡鸾鸣。","濯缨云汉，晞发增城。"]},{"t":"录别 其一","f":"五言古诗","c":["悠悠念往路，离别从此长。","何以酬明德，携手归故乡。","良时不须臾，且复各盈觞。","仰视日月驰，千载互相望。","浮云难独留，游子暮彷徨。","绸缪踰皓首，风波忽一方。"]},{"t":"录别 其二","f":"五言古诗","c":["千秋一嘉遇，此别安可知。","良时不努力，贱躯欲何为。","晨风野萧条，浮云西北驰。","河梁临往路，远望令人悲。","游子自有怀，悠悠当告谁。"]},{"t":"录别 其三","f":"五言古诗","c":["长思何益会，久留何益归。","行人怅明发，褰裳路徘徊。","嘉期能再至，安辞渴与饥。","浮云一相失，千里常依依。","我欲往从之，送子东南飞。"]},{"t":"录别 其四","f":"五言古诗","c":["秋兰怀芬芳，依依树前庭。","春华不再盛，枝叶皆已零。","念昔二三子，俛仰如流星。","羽翼一以乖，邈若隔平生。","徘徊顾四海，谁能喻中情。","结交各有时，千载一濯缨。","离别不在远，日月从此征。","长当为路人，独无弟与兄。","尊酒可自慰，愿言崇令名。"]},{"t":"录别 其五","f":"五言古诗","c":["乖疑起恩爱，离别生欢娱。","念子非一身，中怀难久俱。","握手一相失，奄忽秦与胡。","新知自言乐，山海日以殊。","行路方未央，出门思故庐。","浮云没景光，北风悲有馀。","褰裳复四顾，徘徊当路衢。","结发在战场，皓首为征夫。"]},{"t":"录别 其六","f":"五言古诗","c":["四海一黄鹄，千里命其俦。","悲风厉胡马，踯躅鸣相求。","何况同袍友，从此远行游。","离别无慷慨，去去且复留。","白日没边城，回首望中州。","浮云西北飞，河汉东南流。","视夜常苦早，寒冬正悠悠。","明月烛罗帏，严霜切绸缪。","俛仰已自喻，谁能不怀忧。"]},{"t":"录别 其七","f":"五言古诗","c":["念当首往路，千里邈已临。","丝竹发高堂，听我双龙吟。","泠泠江汉流，浮云寒以阴。","长风激羽翼，严霜摧北林。","慷慨有馀悲，新声怆人心。","游子失相视，征夫泪不任。","中曲一俛仰，从此无知音。","故乡一尊酒，愿言常酌斟。","徘徊恋景光，忽为辰与参。","来者自非昔，去者自非今。"]},{"t":"录别 其八","f":"五言古诗","c":["高楼耿长夜，揽衣歌且谣。","秋风一何悲，游子不得骄。","明月照空床，罗帏自萧萧。","三星既隅列，河汉东南朝。","黄鹄正徘徊，翩翩顾其曹。","故乡邈千里，慷慨命同袍。","浮云日西北，安知心所劳。","携手在须臾，经时复漂摇。"]},{"t":"录别 其九","f":"五言古诗","c":["河汉何皎皎，众星错其间。","揽衣立前庭，明月照苦颜。","悲风中夜起，萧萧有馀寒。","涕泪应声零，四顾惨无欢。","往路信可怀，为乐及盛年。","游子不自爱，故乡岂难旋。"]},{"t":"录别 其十","f":"五言古诗","c":["黄鹄难为群，游子常苦辛。","念当从此别，中怀日以新。","清光皎明月，远望不可亲。","高楼正萧条，徘徊四无人。","上有千里云，其下起飙尘。","各言还故乡，握手道何因。"]},{"t":"录别 其十一","f":"五言古诗","c":["穷冬盛阴气，白日西南微。","征人常早寐，皎月照我扉。","故乡千馀里，中夜起怀归。","干星驾言迈，严霜裂裳衣。","独行无俦匹，谁知渴与饥。","穹庐多悲风，萧萧边草衰。","身在天一隅，何得不徘徊。"]},{"t":"录别 其十二","f":"五言古诗","c":["颜色无常好，春华一以零。","悲风蔽地来，四顾何冥冥。","寤言怀往路，揽衣从此兴。","杀气拳毛发，涕泣断为冰。","仰视河汉星，离如水中萍。","景光不恋人，游子岂遑宁。","夜依牛羊宿，日驱驽马行。","努力及明时，安能爱其情。"]},{"t":"录别 其一","f":"五言律诗","c":["秋风既萧萧，浮云亦依依。","四顾但他乡，游子一何微。","驾言西北迈，中道正裴徊。","客行无好怀，万事不如归。"]},{"t":"录别 其二","f":"五言古诗","c":["三星跂相视，新月拳素光。","两宫高自出，双阙遥相望。","云霞绚河汉，机杼成文章。","罗帏彯四座，华烛摇中堂。","主人前进酒，弹瑟为清商。","流猋激长夜，杀气陨严霜。","萧萧堕白发，翩翩曳衣裳。","男儿不憔悴，谁知在他乡。"]},{"t":"录别 其三","f":"五言古诗","c":["北风著枯林，浮云苦多阴。","红颜日就衰，他乡日就深。","别离起中夜，对酒不能斟。","丝竹含妙伎，佳人怀好音。","眄睐适君意，慷慨动君心。","罢曲一俛仰，变为游子吟。","念当事行役，泪下难自禁。"]},{"t":"录别 其四","f":"五言古诗","c":["秋风西北来，萧萧动百草。","荡子无室家，悠悠在长道。","红颜能几时，弃捐一何早。","对客发素书，零涕复盈抱。","上言故乡好，下言故人老。"]},{"t":"录别 其五","f":"五言古诗","c":["冉冉年欲度，秋兰采间萎。","荡涤千岁情，结束欲何为。","美酒不误人，红颜多所宜。","万事自明日，行乐此一时。","四座惨无言，游子中心知。","浮云动悠悠，故乡难可期。"]},{"t":"录别 其六","f":"五言古诗","c":["悲风堕白日，天地何冥冥。","招摇弹北户，河汉条中庭。","征夫苦难夜，且复命新声。","芳言动君子，四座无不清。","人生即满百，长此千载名。","岂如饮美酒，赵女奏鸣筝。","慷慨尽逸响，慰我饥渴情。","惟念当离别，翩翩渺独征。"]},{"t":"录别 其七","f":"五言古诗","c":["明月促曙光，众星西北移。","游子工早行，起问夜何其。","揽衣出门去，长当渴与饥。","蒺藜穿我履，严霜薄我肌。","别离矜盛年，老至不自知。","努力事战场，泪下复无时。"]},{"t":"录别 其八","f":"五言古诗","c":["浮云满天地，荡子欲安之。","努力事行役，弃置以为期。","少年盛意气，慷慨生别离。","㷀㷀无根蓬，翩翩中林鵻。","马上不得语，涕泪各累累。","君但重自爱，远道归有时。"]},{"t":"录别 其九","f":"五言古诗","c":["秋风动千里，游子何翩翩。","早行多所怀，慷慨私自怜。","严霜覆四野，明星出高天。","涕泪一以下，中道忽言旋。","踟蹰恋徒侣，不知身弃捐。","客从远方来，遗我缯綵笺。","故人俱白头，安得独盛年。"]},{"t":"录别 其十","f":"五言古诗","c":["昭昭秋素景，明月涵金华。","清酒照朱颜，中堂发高歌。","游子在外单，结交常苦多。","别离动白头，人生复几何。","悲风摇枯林，严霜携女萝。","新知虽云乐，不如早还家。"]},{"t":"录别 其十一","f":"五言古诗","c":["高楼出浮云，零露缀绮疏。","明月照佳人，清光相有馀。","纷何下涕泪，纤纤结素书。","愿持千里心，托此双鲤鱼。","尊名不可处，白发难久居。","岂如及盛年，驾言归故庐。"]},{"t":"录别 其一","f":"五言古诗","c":["眇眇远行客，绵绵思故乡。","悲风绕车鸣，浮云立马傍。","边城苦多阴，秋气激繁霜。","白日匿何时，四野一茫茫。","落木委空庭，游响拂閒房。","霏霏罗帷影，明月在我床。","起视河汉流，寥寥夜未央。","出亦以徘徊，入亦以彷徨。"]},{"t":"录别 其二","f":"五言古诗","c":["大江多悲风，秋日澄清阴。","浮云无本根，天路难重寻。","故人一失所，结交良苦心。","游子易慷慨，抚剑吐哀吟。","白发行萧萧，繁霜悴我衿。","登城望四野，明月照北林。","悠悠委他乡，中怀安可任。"]},{"t":"录别 其三","f":"五言古诗","c":["去日苦太易，游子无常家。","别离在俯仰，素雪以朱华。","驱车就颓景，明发泛黄河。","浮云媵余征，流飙激其波。","顾眄当中原，慷慨为悲歌。","千里一萧条，故乡复如何。"]},{"t":"古意 其一","f":"五言古诗","c":["秋风西北起，吹我游子裳。","浮云从何来，安知非故乡。","萧萧胡马鸣，翩翩下枯桑。","暮色入中原，飞蓬转战场。","往路不可怀，行役自悲伤。"]},{"t":"古意 其二","f":"五言古诗","c":["新人一何好，年颇十五馀。","本自贵家子，秦氏有名姝。","故人行采桑，值我城南隅。","颜色各精妙，手爪亦相如。","故人工纨素，新人工笙竽。","笙竽未讵央，纨素色已渝。","人生无新故，夫婿自言殊。"]},{"t":"古意 其三","f":"五言古诗","c":["嶰阴有孤竹，常含千岁霜。","截为雄鸣管，其音中清商。","岂不在人耳，世已无凤皇。","新声自一时，艳曲乱高倡。","安得日相御，并坐君子堂。"]},{"t":"古意 其四","f":"五言古诗","c":["十五漳河女，出身邯郸庭。","丝竹妙一世，纤手何泠泠。","清商有馀悲，慷慨为新声。","中曲若无人，含意已独明。","知音难再遇，红妆日夜零。","奋响发浮云，摧耳不能听。"]},{"t":"古意 其五","f":"五言古诗","c":["英英天上云，不照浊水泥。","新婚日以亲，贱妾日以携。","繁声出皓齿，妙舞生春姿。","缟綦难为容，弃如秋草萎。","念当羽翼乖，依依即路岐。","良人无古欢，妾自中心知。"]},{"t":"古意 其六","f":"五言古诗","c":["中天起双阙，浮云出两宫。","驰道挺其间，甲第罗西东。","胡姬正当垆，邀客过新丰。","朱唇含绿酒，纤爪扣青铜。","堕髻似无意，绍绕一何工。","眄睐正愁人，流纨动春风。","双双羽林郎，翩翩五色骢。","挟瑟上高楼，调丝方未终。"]},{"t":"古意 其七","f":"五言古诗","c":["胡鹰一何劲，北风一何高。","朔方士马地，斗酒命同袍。","穷冬蹙四野，大猎出临洮。","荡石响深谷，烈火走平皋。","边声中夜起，杀气常萧萧。","积阴生战场，白日惨不消。","草枯牛羊瘦，雪盛狐鼠骄。","引领望交河，层冰正迢迢。"]},{"t":"咏古 其一","f":"五言古诗","c":["帝作大唐歌，八伯奏卿云。","钟石兴麓野，人声一以论。","日月发光华，烂然星具陈。","沈璧十二渚，岱宗乃于禋。","是时辟四门，穆穆咸所宾。"]},{"t":"咏古 其二","f":"五言古诗","c":["绥绥涂山狐，九尾不自多。","我往求平定，念子无室家。","明发兴岳庭，乃身参洪波。","宗疏事则裒，祝融扬英华。","玉牒沐日月，素书出江河。"]},{"t":"咏古 其三","f":"五言律诗","c":["江水一何沛，薄大趣归处。","朝周过故墟，宫室生禾黍。","伤彼西山士，采薇自相茹。","千载睹逸诗，斯人乃高举。"]},{"t":"咏古 其四","f":"五言古诗","c":["白云出山陵，乃在天一方。","东土既已洽，徂西聊倘佯。","虎豹自为群，乌鹊列成行。","惟帝立嘉命，诸夏发其祥。","愿言顾见女，中心以翱翔。","刊石树弇兹，千载遥相望。"]},{"t":"咏古 其五","f":"五言古诗","c":["杲杲炽日羽，施施掩飙斿。","我车既已写，四马亦孔柔。","射夫率原隰，君子循方舟。","杨柳囊其鲜，鹿豕填相求。","多士自允异，燕乐成王猷。","驾言徂东郊，出洛朝诸侯。"]},{"t":"咏古 其六","f":"五言古诗","c":["白石粲南山，赪鲤丽沧浪。","单衣裁及骭，缊缕远从商。","夜中起饭牛，任车自所将。","爝火辟列星，上客烂生光。","疾歌一不闻，何谓伯与王。"]},{"t":"咏古 其七","f":"五言古诗","c":["菀彼中林乌，拚飞不集枯。","齿牙一为猾，公子良见图。","矫矫上天龙，雾雨既已敷。","子推独耆乾，草莽空号呼。","悬书下宫门，绵山聊与娱。"]},{"t":"咏古 其八","f":"五言古诗","c":["庄王搆曾台，乃与云梦邻。","东延洞庭石，涔阳激清津。","赵魏方幸祸，况此狼虎秦。","谏者七十二，枕藉以前陈。","时非一耕夫，三楚讫无人。","因知沮溺流，用即社稷臣。"]},{"t":"咏古 其九","f":"五言古诗","c":["驾言九皋泽，揽彼渐水台。","罘罳蔽荆岑，绝流曲池隈。","婉彼三楚士，谏猎纡其才。","大雨忽盈河，疾风西北来。","洪潦起滔天，陨雹激以雷。","商梁正绥立，仆夫行告哀。","孤虚无妄设，荧惑谅为灾。","帝德眷荒淫，欲去此徘徊。"]},{"t":"咏古 其十","f":"楚辞体","c":["文驷陈大庭，膰肉宿所脩。","群婢一以盛，君子乃见咻。","孰谓彼妇口，于中可优游。","蟪蛄遂盈耳，凤兮当何求。","斧柯不在手，龟山郁绸缪。","翱翔七十国，交辙奸诸侯。","狄水衍其波，罔济非无舟。","驾言从吾好，还辕息我陬。"]},{"t":"咏古 其十一","f":"五言律诗","c":["忽忽岁已莫，太台役方作。","太上美遨游，禾黍未能穫。","滞穗满甫田，风雨殚零落。","相国一沾襟，罢酒不为乐。"]},{"t":"咏古 其十二","f":"五言古诗","c":["贪吏常苦富，廉吏常苦贫。","不见孙叔敖，其子行负薪。","五霸相代兴，主烈难为臣。","令名有遗封，馀财喜没人。","寝丘虽言恶，千载功无湮。"]},{"t":"咏古 其十三","f":"五言古诗","c":["阖闾为无道，厥欲如蛇豕。","荐食视上国，乃政从楚起。","昭王在草泽，群臣不复纪。","使者哭秦庭，七日未得理。","入郢既已甚，丘陇行见箠。","感兹告急言，誓彼同袍士。","贤臣亦多术，存亡尤独美。"]},{"t":"咏古 其十四","f":"五言古诗","c":["吴王既栖越，出游包山湖。","道逢一丈人，邀我洞庭隅。","灵墟发深藏，中有神禹书。","大文秘天地，乃传百六初。","金简歊浮云，玉宇回璇枢。","科斗不可辨，鸟迹互盘纡。","精华一以泄，厌气直国庐。","顾见二室颠，三石方扶疏。"]},{"t":"咏古 其十五","f":"五言古诗","c":["薛公得冯驩，门下知者谁。","十日居传舍，乃问客所为。","先生惟一剑，弹铗何其悲。","授室缔高国，驱车出中逵。","主人意已厌，同列宁见推。","田文既失位，倾身与持危。","片言悟齐主，复相名益垂。","奇士多侮世，藏用匪可窥。"]},{"t":"咏古 其十六","f":"五言古诗","c":["中春阳和起，嘉观临四方。","刻石颂功德，从臣纪攸长。","上以献泰成，下威六暴彊。","郡县乃作始，经纬不踰行。","荐号立大义，昭设咸有章。","濯俗谅已美，刑名非恒常。","鞭箠出顽夫，二世寻灭亡。"]},{"t":"杂兴 其一","f":"五言古诗","c":["伯牙负高操，引曲辄入神。","从师蹈东海，延颈四无人。","洪波荡大壑，悲鸟方号群。","白日坐失色，山林忽不分。","精气一以变，此调得其真。","世俗蔽闻见，千载递相因。","遗世伎始妙，绝弦多苦辛。","自非钟子期，古道难具陈。"]},{"t":"杂兴 其二","f":"五言古诗","c":["离朱不逆景，师旷不逆风。","所用一以失，化为瞽与聋。","辔策出大御，绳墨出巧工。","顾眄即千里，结构临层穹。","束手宁自甘，徇人道乃穷。"]},{"t":"杂兴 其三","f":"五言古诗","c":["良材出大国，群构集明堂。","欂栌相支持，榱桷硕且长。","飞栋郁云兴，高轩间重梁。","众人称壮丽，输子起彷徨。","柱小亦已挠，朽蠹处中央。","迨天方晦阴，室家罗四厢。","行者苦无休，居者歌慨慷。","风雨一漂摇，不知僵路傍。"]},{"t":"杂兴 其四","f":"五言律诗","c":["良马踬路岐，善言踬嫌疑。","称乐自云早，日月寝已驰。","黄金不可作，美酒多所宜。","清风响高唱，令德含妙辞。"]},{"t":"杂兴 其五","f":"五言古诗","c":["太元秉经纬，天地自生成。","阴阳递消息，四时相虚盈。","雷雨鼓神气，日月宣华英。","絪缊交二仪，周流列五行。","至和液甘露，盛德厌欃枪。","唐虞且法象，明良熙穆清。","垂衣御三事，大治无常名。"]},{"t":"杂兴 其六","f":"五言古诗","c":["翩何汉宫女，红妆郁荧荧。","本自良家子，十五充后庭。","是时得上意，宠至身逾轻。","贵幸霸天下，妙丽倾人城。","诏许领椒房，嫔御无不惊。","唇如齧丹饴，齿如锵玉声。","一当万乘主，常含中道情。","绝色动千载，旦夕谁见明。","美恶悬盛衰，弃置视合并。","所以尹婕妤，顾盻失平生。"]},{"t":"杂兴 其七","f":"五言古诗","c":["诡时苦难遇，直道苦不华。","挈瓶羸众口，绳墨矫群邪。","所以上古人，工拙无常家。","陆沈金马门，醉即据地歌。","世久自相玩，为德一何多。","在群既累生，孤贵亦失和。","首阳与柳下，一龙复一蛇。","同流虽所愿，迹迩心则遐。"]},{"t":"杂兴 其八","f":"五言古诗","c":["鸿鹄一以举，四海何悠悠。","局促人间世，岂若远行游。","明时不重至，中怀难久留。","遇合成佞倖，美女多所仇。","英雄既失据，片语解绸缪。","所以孔仲尼，舍车即于浮。"]},{"t":"杂兴 其九","f":"五言古诗","c":["洞庭大张乐，千乘朝昆仑。","在昔有行幸，轩穆一何尊。","楼船下河东，羽卫览西垠。","风起白云飞，陇首望中原。","箫鼓发哀情，长驰晻回辕。","入齧妃女唇，出接词客言。"]},{"t":"杂兴 其十","f":"五言古诗","c":["名马不受羁，足下有千里。","黄鹄不受罗，羽翼就四海。","贵贱自一身，出处无二轨。","时利适愚夫，势衰蹶智士。","祛长不揠臂，屦缩不截趾。","陆沈人间世，悠悠日复尔。"]},{"t":"杂兴 其一","f":"五言律诗","c":["鸿鹄摩苍天，万里一翱翔。","回飙生羽翼，浮云为低昂。","毕逋城上乌，黄口自成行。","俛啄仰相嚇，徘徊腐鼠傍。"]},{"t":"杂兴 其二","f":"五言古诗","c":["大鱼鼓长鬐，捷若举帆幢。","夜驱苍梧风，凌晨浮九江。","怒击胥山涛，洪波为汹汹。","本图运南溟，中更不相容。","何言一失水，湖海难再逢。","宁如涸辙鲋，斗水得所钟。"]},{"t":"杂兴 其三","f":"五言律诗","c":["江南有佳人，桃李蓊朱颜。","宕子行从军，閒房重其关。","明月一徘徊，形影自翩翩。","秋气响罗帷，萧萧难独眠。"]},{"t":"杂兴 其四","f":"五言古诗","c":["凤栖十围干，龙翔九回流。","圆景朝列宿，五岳尊陵丘。","圣人膺大命，多士自相求。","稷契功不刊，唐虞德无俦。","神明盛驱使，衣裳美优游。","诗书监二代，孔氏乃宗周。","在昔纡天经，群后有绸缪。","艰难戴王室，千载成咸休。"]},{"t":"杂兴 其五","f":"五言律诗","c":["长离自凤雏，天马乃龙子。","文采成九苞，骨法本千里。","箕颍出高人，岩穴有知己。","抗迹唐虞庭，清风振薄鄙。"]},{"t":"杂兴 其六","f":"五言律诗","c":["南山有奇鸟，朝阳曜其文。","下来兰池饮，罗网正纷员。","虽复就长缨，徘徊怀不群。","枳棘无安步，哀鸣激清云。"]},{"t":"杂兴 其七","f":"五言律诗","c":["翩翩西北风，萧萧枯桑林。","登高使人望，秋气悲我心。","丛台蔓寒草，易水清且深。","当时燕赵士，慷慨有遗音。"]},{"t":"杂兴 其八","f":"五言古诗","c":["驾出蓟北门，东望元英宫。","高台造浮云，碣石来悲风。","客卿既裂地，战士亦论功。","称系迁大吕，昭王气何雄。","汶篁一不植，千里生飞蓬。"]},{"t":"杂兴 其九","f":"五言古诗","c":["逍遥临蓬池，言陟梁王台。","还顾望大河，洪波渺悠哉。","飞雪蔽中原，北风千里来。","驰驱名利途，无骏不驽骀。","精卫自微鸟，东海生尘埃。"]},{"t":"杂兴 其十","f":"五言律诗","c":["古今一旦暮，俯仰成兴衰。","不见桑榆云，千里相蔽亏。","黄金苦易尽，红颜安可为。","如何膏粱士，拂拭使人悲。"]},{"t":"杂兴 其十一","f":"五言古诗","c":["万事无不有，何言能自持。","巢由乖世度，高行众人疑。","俯仰在当路，得丧未可期。","汤火煎太和，倾侧使神危。","终身系罗网，失势还相欺。","念我平生欢，临觞命妖姬。"]},{"t":"古诗后十九首 其一","f":"五言古诗","c":["行行万里馀，依依梦故乡。","见君累长夜，携手立彷徨。","寤言心尚尔，忽在天一方。","越鸟东南飞，胡马鸣相望。","眄睐人自好，弃捐人自老。","徘徊亦何益，努力苦不早。","思君度餐饭，岁月漫浩浩。","慷慨即别离，故乡勿复道。"]},{"t":"古诗后十九首 其二","f":"五言古诗","c":["摇摇车马客，依依燕赵女。","沾沾倚筝立，交交夹窗语。","盘盘高结出，飙飙巾带举。","浮云忽自归，荡子漫无所。","天寒锦衾薄，空床难独处。"]},{"t":"古诗后十九首 其三","f":"五言古诗","c":["白石何历历，松柏何离离。","人生天地间，一日不可知。","斗酒无常置，良会无常期。","沈吟厚与薄，为乐无乃迟。","宛洛美游戏，冠带自相随。","宫阙起云中，第宅罗四垂。","王侯负贵气，佳客以盛衰。","君但视车马，揽策振其绥。"]},{"t":"古诗后十九首 其四","f":"五言古诗","c":["良会属今日，弹筝倚新声。","唱苦令神伤，三变不可盈。","中曲忽自置，踯躅一再行。","欲因更促柱，难为听者情。","人生局一世，悠悠终何成。","要路多坎坷，先秋惨其荣。","来者率如此，焉知千岁名。"]},{"t":"古诗后十九首 其五","f":"五言古诗","c":["三五楼上女，徙倚当双扉。","红妆妙一世，谁不揽容辉。","弦歌入青云，新声亮所稀。","千载为一弹，含意有馀哀。","知音难再得，且复立徘徊。","终日不成曲，零涕沾裳衣。","三叹令人老，游子何时归。"]},{"t":"古诗后十九首 其六","f":"五言律诗","c":["烛烛芙蓉花，擢擢采兰妇。","怀袖忽已盈，馨香谁为有。","秋草一以萎，此物难独久。","驰情一水间，无因携素手。"]},{"t":"古诗后十九首 其七","f":"五言古诗","c":["摇光加孟冬，北风何惨慄。","寒至疏众星，蟾兔亦早缺。","四时既潜移，遗迹独难列。","不知空床下，蟋蟀安从出。","宛洛多故人，厚者如胶漆。","及其据要路，负我道非一。","织女无成章，牵牛策不发。","且复守贫贱，振翮各有日。"]},{"t":"古诗后十九首 其八","f":"五言古诗","c":["浮云何冉冉，亦在南山阿。","千里远徘徊，游子苦无家。","昔我同门友，策马驱高车。","两宫属眄睐，冠带日逶迤。","致身及盛时，结附一何多。","极宴累长夜，重闱发弦歌。","白露忽以零，迫此蕙兰花。","芳草随飙尘，谁能顾女萝。"]},{"t":"古诗后十九首 其九","f":"五言律诗","c":["独鹄西北逝，逸响一何哀。","念当生别离，欲去复徘徊。","不惜寒气厉，但伤羽翼摧。","我有鸳鸯绮，无衣谁为裁。"]},{"t":"古诗后十九首 其十","f":"五言古诗","c":["眄眄织女星，当机理纨素。","牵牛能几许，常为投杼误。","纨素欲遗谁，终日西北顾。","负轭复何时，轩车岁云暮。","揽衣即河汉，踯躅不得度。"]},{"t":"古诗后十九首 其十一","f":"五言古诗","c":["高楼出西北，下有故乡道。","浮云蔽天起，回飙响秋草。","四时更相至，人生自着老。","伤彼游子颜，戚戚难独好。","携手不须臾，弃捐一何早。","努力以为乐，泣涕复盈抱。"]},{"t":"古诗后十九首 其十二","f":"五言古诗","c":["东城属浮云，阿阁百馀尺。","岁暮多悲风，游子衣裳薄。","四野何萧条，所遇但遗迹。","来者自为今，去者自为昔。","盛年奄已衰，含意将安适。","燕赵出名倡，红颜照宛洛。","结束随时变，弦歌日相索。","未弹理怀袖，若在远行客。","弄指一何妙，列柱一何迫。","驰情视双燕，飞入王侯宅。"]},{"t":"古诗后十九首 其十三","f":"五言古诗","c":["磊磊丘与坟，郁郁郭北地。","白日松柏阴，悲风四面至。","谁能黄泉下，永含未伸意。","悠悠即长夜，千载一以弃。","漫漫待明发，迢迢正遥寐。","身世非胶漆，岂得常相寄。","此物无贤愚，万岁更相致。","神仙不可知，服食苦中置。","美酒与佳人，携手行游戏。"]},{"t":"古诗后十九首 其十四","f":"五言古诗","c":["郭北一极望，徘徊安所如。","新坟历历出，古墓附里闾。","薪者踯躅歌，弃女回其车。","白杨日夜疏，萧萧悲有馀。","三岁去故乡，一字无素书。"]},{"t":"古诗后十九首 其十五","f":"五言古诗","c":["处世苦无见，孤生非所忧。","高言唱同心，千载一相求。","穷贱解胶漆，弃置衰交游。","昔我同门友，上书哀王侯。","明月皎夜光，踯躅不得投。"]},{"t":"古诗后十九首 其十六","f":"五言古诗","c":["迢迢月既望，白露被庭中。","越女理前音，燕服罗清宫。","交游自远方，文彩复无双。","驾言出广陵，将以适曲江。","聊慄此何气，揽观不可穷。","帷车蔽日下，万马悲回风。","水力率已至，神物难为容。","秉意属南山，浩荡惟所从。","上客变其度，陈唱谁与同。","极命以成章，娱乐良未终。"]},{"t":"古诗后十九首 其十七","f":"五言古诗","c":["孟冬风已厉，揽衣有馀叹。","独宿知夜长，远客知天寒。","河汉直双阙，皎若素与纨。","黄鹄从西南，孤飞正漫漫。","一鸣缓中带，再鸣沾玉颜。","游子不可听，令君中道还。","所以生别离，慷慨亮为难。"]},{"t":"古诗后十九首 其十八","f":"五言古诗","c":["客从洛浦至，遗我合欢衾。","中有长相思，缘以结同心。","芙蓉发文彩，鸳鸯厉哀吟。","游子正无衣，天气复已阴。","故人此属意，徘徊独至今。"]},{"t":"古诗后十九首 其十九","f":"五言古诗","c":["皎皎罗帷月，揽之有馀辉。","寤言守长夜，依依未能归。","故乡无不可，道路亦何为。","客行各有怀，谁知我心悲。","出门一以望，浩荡沾裳衣。"]},{"t":"君子行","f":"五言古诗","c":["君子美百行，维日服厥衷。","车奔不易度，火灭不改容。","垢言一生口，盥漱难为工。","金多徒自秽，重名挠直躬。","幸勿少须臾，无替功乃崇。","九渊可浮游，所患溺愚蒙。"]},{"t":"远游篇","f":"五言古诗","c":["乘蹻万里外，言造太微庭。","云霞曜朱阙，日月夹丹棂。","群后俨金止，仙女纷玉亭。","随风列以雨，出窈而入冥。","沆瀣飞素液，芝草不复零。","虹霓为我带，杂佩摇华星。","濯缨河汉流，清波正泠泠。","俯视世间人，汎汎如浮萍。"]},{"t":"太山篇","f":"五言古诗","c":["大东有神岳，专名为岱宗。","日精摄海气，吴野控其峰。","明堂朝列后，金策纪元功。","维昔七十家，轩辕此登封。","云霞自窈窕，石室何青葱。","仙人揽玉树，须发生清风。","灵液飞潺湲，芝草如蒿蓬。","唯帝拥灵符，千载一升中。","愿言与问道，乘龙举太空。"]},{"t":"建安体 其一","f":"五言古诗","c":["转蓬遇回风，千里一遨游。","良时不自爱，汎汎亦何求。","西来既迂怪，周孔以坟丘。","患无纷葩名，年往非所忧。","烈士多壮心，对酒苦难酬。","枕石太华颠，俯漱江海流。"]},{"t":"建安体 其二","f":"五言古诗","c":["北风正徘徊，繁霜以霏霏。","经过至朔方，惆怅我武威。","白骨何籍籍，铠甲贯疮痍。","猛兽蹲高冈，狐兔失故蹊。","伐薪缺斧斨，饮冰胶马蹄。","远行多苦寒，中路渴与饥。","是时一介志，悠悠谁当知。"]},{"t":"建安体 其三","f":"五言古诗","c":["河汉悬清光，三五正参差。","西北起浮云，霏霏风入帷。","白发一何早，隐约当待谁。","快独饮美酒，登台临华池。","赵女荡奇舞，秦筝繁且悲。","忧来亦有方，安得常相随。"]},{"t":"代建安从军公燕诗并引 其一 代文帝","f":"五言古诗","c":["长驱下广陵，观兵东南疆。","方舟被大海，万骑纷纵横。","旌旗随波靡，组练远茫茫。","中流震金鼓，士马何激扬。","铠甲生悲风，千里一锵锵。","白羽所漂摇，浮云自低昂。","抚剑登高城，我军正相望。","零雨有遗篇，咏言难可忘。"]},{"t":"代建安从军公燕诗并引 其二 代明帝","f":"五言古诗","c":["太常摩回飙，旗帜何翩翩。","屯吹弥故垒，列舟竟长川。","登樯望四野，萧条无人烟。","高墉走狐兔，荆棘动参天。","抚剑下中流，甲士罗东西。","赋诗写其怀，随波以潺湲。","从军在万里，惆怅私其怜。"]},{"t":"代建安从军公燕诗并引 其三 代曹子建","f":"五言古诗","c":["丈夫志万里，慷慨事四方。","我后振威灵，六军乃激扬。","分旗建东岳，耀武临江湘。","鸣镝控流飙，利剑捷秋霜。","长驱下淮泗，人马自生光。","戈矛何参差，方舟正纵横。","何言为国雠，一举披旧疆。","解徒旆言入，歌舞旋许昌。","离宫大飨士，劳赐以次行。","君子念在御，赋诗垂华芳。"]},{"t":"代建安从军公燕诗并引 其四 代王仲宣","f":"五言古诗","c":["方舟何翩翩，素波亦萧萧。","蒹葭澹馀映，长樯激流飙。","抚剑登高防，人马且逍遥。","空城何所有，杀气蔽旌旄。","日夕见烟火，四野飞蓬蒿。","边声起大江，谁知我心劳。","从军殊复乐，菲薄愧铅刀。"]},{"t":"代建安从军公燕诗并引 其五 代陈孔璋","f":"五言古诗","c":["浮云肃四野，流飙殷悲音。","边地一何苦，慷慨难为心。","饮马长城下，水寒窟且深。","白骨撑路出，杀气驾重阴。","将建大举功，干戈日相寻。","骋哉书檄驰，纵横正如林。","身在记室中，慊慊匪自今。","男儿念钟鼎，谁能常滞淫。"]},{"t":"代建安从军公燕诗并引 其六 代徐伟长","f":"五言古诗","c":["自我出从军，涉旬东南行。","文学托后乘，顾瞻亦已深。","中流万艘集，陶陶层波生。","凄风旗帜繁，秋日戈甲精。","沈阴结战气，唯闻金鼓声。","壮士何飞扬，各愿一先鸣。","志已驰九关，岂但怀不庭。","虽君在只尺，搔首未遑宁。"]},{"t":"代建安从军公燕诗并引 其七 代刘公干","f":"五言古诗","c":["我后赫斯怒，整驾东南征。","六军如飞集，列植龙陂城。","皑皑霜风至，肃萧戈甲鸣。","长飙转沙砾，仰视白日冥。","流波一何劲，金鼓悲且清。","连鸢下青云，毛血洒隰坰。","发机入微妙，观者无不惊。","壮士以慷慨，各奋先登情。","释此荐嘉客，濡翰叙平生。","篇章信绮丽，新诗雅以精。","小臣在缇幕，起坐怀同声。","戎事谅非难，但恐沈痼婴。"]},{"t":"代建安从军公燕诗并引 其八 代应德琏","f":"五言古诗","c":["郁郁西北云，千里驱重阴。","临江大耀士，方舟载浮沈。","连波响风雨，长緤纷悲吟。","分曹命超距，逸气不可禁。","君子在行伍，常怀饥渴心。","非不愧细微，良遇日以深。","故山何时旋，徘徊中自任。"]},{"t":"代建安从军公燕诗并引 其九 代阮元瑜","f":"五言古诗","c":["高城苦多阴，秋日殊复悲。","边声薄暮起，但见浮云飞。","霜气劲且繁，河汉寒无晖。","三星何踯躅，皎月正徘徊。","流飙西北至，征马鸣相依。","自知从君乐，谁能常不归。"]},{"t":"公燕诗九首 其一 文帝","f":"五言古诗","c":["置酒高台观，逍遥芙蓉池。","兄弟夜行游，贵客郁参差。","明月照长筵，罗缨何霏霏。","翩彼众君子，展诗奏新辞。","弦歌入微妙，慷慨使心悲。","流尘荡清响，绮丽有馀姿。","吐握苦不悉，人生安可为。","在昔无乐方，彼此同一时。"]},{"t":"公燕诗九首 其二 明帝","f":"五言古诗","c":["三五明月满，四七灵宿繁。","清夜美行游，置酒西苑园。","华池滥轻波，芙蓉一何鲜。","飞盖拂流景，随风自潺湲。","主人延贵客，竟席列豪贤。","弦歌彻中堂，羽爵腾我前。","微音喟有和，甘醪发芳颜。","乐哉殊复乐，君岂不俱然。"]},{"t":"公燕诗九首 其三 子建","f":"五言古诗","c":["流飙起飞栋，群星集棂轩。","月出芙蓉池，清光满西园。","侍者夜行觞，绮缟一何繁。","玉颜可揽持，顾眄属所欢。","华镫正徘徊，步障随风还。","弦歌荡层台，激响拂潺湲。","公子多忧客，从横各成篇。","主人自和氏，披褐将谁愆。","绝缨纷陆离，堕钗复阑干。","取乐此一时，嘉会良独难。"]},{"t":"公燕诗九首 其四 仲宣","f":"五言古诗","c":["浮云撤重阴，流猋四座来。","西临柏阳山，南望铜雀台。","回首出中原，旷然千里开。","公子大置酒，弦管间行杯。","华镫吐清光，飞盖自徘徊。","古人一含情，于今安在哉。","乱离常苦多，欢极令我哀。"]},{"t":"公燕诗九首 其五 孔璋","f":"五言古诗","c":["羁客心无娱，閒居日悠悠。","驾言侍高会，公子招我游。","凯风飘怫郁，素晖荡清流。","中庭焕绮树，芳蕤自沉浮。","登台远顾望，高下见原畴。","肃肃山谷悲，黯黯阴气收。","篇章时间作，羽觞不及投。","逍遥何以立，功名为相求。"]},{"t":"公燕诗九首 其六 伟长","f":"五言古诗","c":["高台郁峨峨，其下临清池。","黄鹄比翼游，淫鱼戏涟漪。","微风起水裔，朱华纷陆离。","绮罗既生色，笑歌不自治。","旨酒但相属，羽觞随波移。","人生寄一世，岁月忽如驰。","岂忘诵君恩，贱躯未可知。"]},{"t":"公燕诗九首 其七 公干","f":"五言古诗","c":["月出西掖垣，双阙郁苍苍。","白石烂素波，蘋藻槩金塘。","方舟转清流，飞盖纷翱翔。","轻飙洒前庭，明镫皦中堂。","渌酒溢尊罍，嘉殽充圆方。","公子多妙制，藻思何纵横。","高谈自宠珍，濡翰安能详。","婴疾日沈痼，簿领非所长。","愿言贻令德，僶俛不可忘。"]},{"t":"公燕诗九首 其八 德琏","f":"五言古诗","c":["群士谐佳会，置酒君子堂。","清言解饥渴，四座生芬芳。","云雨濯高翼，沙石明夜光。","连篇命音响，好合兴文章。","三台开艺苑，爱客擅词场。","伸眉就存慰，千载以为常。"]},{"t":"公燕诗九首 其九 元瑜","f":"五言古诗","c":["知己难再遇，揽衣及良辰。","天衢飞高翼，清流濯纤鳞。","摇落易为感，孰能爱此身。","恩义不潜畅，举座皆异人。","公子善养士，中外常所亲。","侍会此高堂，羽觞何纷员。","翰墨风雨集，兴文若浮云。","翩翩致足乐，愿言守明贞。"]},{"t":"效应璩百一诗","f":"五言古诗","c":["殽函命关谷，泾渭达黄河。","终南既面列，沃野开其阿。","帝王信佳丽，天府郁嵯峨。","铜雀鸣云中，员阙夹丹霞。","三秦盛西气，小戎乃遗歌。","扬马翼炎光，流风激颓波。","使臣典文字，执宪临群邪。","春秋大校士，与世陈四科。","祗役在末位，兴言念皇家。","筐筴有玺书，翩翩为国华。"]},{"t":"感怀 其一","f":"五言古诗","c":["寥寥高秋气，凉风激中庭。","明星一何的，皓月复泠泠。","清夜使心悲，幽人起屏营。","罗帷徐动摇，丹镫发寒荣。","短歌易慷慨，伏枕通鸡鸣。","伴侣稍稍单，独立非其情。"]},{"t":"感怀 其二","f":"五言古诗","c":["四海一流览，为乐遽何央。","经传有因依，大雅未沦亡。","知名自前代，骋翰各专场。","微音可通灵，新辞协宫商。","绮丽漫星陈，江河郁纵横。","岂不多苦心，世士竟茫茫。","中原二三子，春秋足翱翔。","离别致仓卒，千载不相当。"]},{"t":"感怀 其三","f":"五言古诗","c":["明珠出大海，豫章擢清云。","宗臣开国功，王佐难其群。","公朝日举士，愚者甘不闻。","披褐玩明时，骋翰流华芬。","分适中自谐，知己俟其真。","磬折难为容，弹冠各有人。","谁令君独往，踟蹰失要津。"]},{"t":"感怀 其四","f":"五言古诗","c":["明堂飨元祚，称岁朝京师。","侵晨宴鸾台，日夕宿兰池。","翩翩佳公子，三五相追随。","十千平乐酒，羽爵何参差。","长歌激清风，顾眄生光辉。","秉我径寸翰，兴文一如飞。","旁人徒嗷嗷，匹侣当自知。","离别难预图，乐往自成悲。","仰观素雪流，俯见朱华披。","弃置安足陈，亡没无还期。","百年譬影响，倏忽谁能持。"]},{"t":"感怀 其五","f":"五言古诗","c":["在我游帝京，冯宠私自奇。","当年值数子，无复新相知。","中原一顾眄，凌厉有馀姿。","用身常苦拙，此志安得施。","浮沉托大道，四海一栖迟。","时俗溺鄙议，长往不可追。","愿言反初服，白日且逶迤。","酒中念故人，千载为等期。"]},{"t":"感怀 其六","f":"五言古诗","c":["鸿鹄不啸侣，鸷鸟难为俦。","双美无常玩，江汉故分流。","坚芳喻兰石，千载一绸缪。","佳言盈耳哉，良时安可留。","在昔誇中原，数子从我游。"]},{"t":"感怀 其七","f":"五言古诗","c":["孤行苦难立，耿介伤其躬。","世路有姿态，悠悠安所终。","美服光照人，言笑一何工。","抱鼓若籧篨，磬折如转蓬。","轻薄不可视，妖蛊谁能穷。","车马从狭邪，棘生九衢中。"]},{"t":"感怀 其八","f":"五言律诗","c":["浮云翳高城，回飙生战场。","金鼓使人悲，旗帜亦飞扬。","千载一如此，丘陇递相望。","奈何转蓬士，翩翩常道傍。"]},{"t":"酬皇甫虞部","f":"五言古诗","c":["青阳一何丽，冉冉西南驰。","言念庭中树，率已萎华滋。","昔我同心友，欢宴及良时。","携手理清曲，各谓无人知。","天衢多高足，冠盖自相随。","所愿不与俱，朝亲夕生疑。","含意恋明世，皓首为君期。","谅兹久识察，红颜坐盛衰。"]},{"t":"寄许殿卿","f":"五言古诗","c":["西山匿冬日，北风悽以繁。","念兹岁方晏，徘徊白云垣。","俛首事尺牍，儋石聊自存。","悠悠尘中心，夙昔非所论。","感彼硕人情，独歌矢弗谖。","庶此涉时艰，遂用安丘园。","路傍磬折子，高足策华轩。","咄唶金兰客，来当蹈斯言。"]},{"t":"赋得何仲默","f":"五言古诗","c":["仲默自天秀，弱龄负遐瞩。","十六游京邑，艺苑策高足。","挥毫坐华观，怀人理清曲。","归来放情志，日晏从所欲。","结好玩遗芳，明德以相勖。","古道谅寡谐，遂令伤局促。"]},{"t":"五子诗 其二 吴明卿","f":"五言古诗","c":["吴生荡涤士，明德复何早。","高举凌风翮，青云漫浩浩。","良士冠带会，斗酒弄辞藻。","一弹中清商，下里难为好。","知音率已稀，隐几存吾道。","众言纷盈庭，胶漆各自保。","掩耳走淆乱，褰裳度潢潦。","骂坐岂尽狂，流俗令人老。","陆沈金马门，怀袖谏书草。","白日有弃捐，游子悲不造。"]},{"t":"二子诗 其一 卢次楩","f":"五言古诗","c":["卢楠起河朔，本自千金子。","荡涤诸生间，销骨于积毁。","世无临邛令，焉得心尚尔。","深文类缪恭，罪罟中狙喜。","乃系黎阳狱，十年攻一技。","既出浮丘赋，始知有株累。","三叹不同时，帝曰付诸理。","寥寥相如后，谁能识察此。"]},{"t":"酬元美 其一","f":"五言古诗","c":["妾本秦宫女，少小扬蛾眉。","早辱君王宠，朱颜骄自持。","卷衣皆罗纨，明珠纵横垂。","头上翠琅玕，爵钗珊瑚枝。","盛年处深殿，容华天下知。","一朝在里巷，遂为生别离。","此身托古欢，南山犹可移。","东邻荡子妇，泥沙委路岐。","中心指秋日，同穴乃所期。"]},{"t":"酬元美 其二","f":"五言古诗","c":["有鸟名黄鹄，乃在琪树柯。","下来太液饮，唼喋荇与荷。","周游视中土，少年多罗家。","金衣菊为裳，不受矰缴加。","一举绝四海，离哉天可摩。","毛羽未摧颓，鼎俎奈尔何。"]},{"t":"再答元美 其一","f":"五言古诗","c":["盈盈猗兰花，深谷何逶迤。","秋风凋奇树，陨萚以葳蕤。","含英即蔓草，不复扬华滋。","岂无王者香，结根非其宜。","孤生感霜雪，采折中心知。","幸君置怀袖，慰此长相思。","亭亭西山柏，自茂凌寒姿。","下流难久居，壮士多所悲。"]},{"t":"再答元美 其二","f":"五言古诗","c":["采苓首阳巅，青蝇止于棘。","结发奉欢宴，柏舟矢靡慝。","上堂理琴瑟，上堂视蚕织。","眤若形与影，在远复相忆。","岂不防未然，萋菲成罔极。","爱深生百忧，弃捐衢路侧。","贱妾抱区区，中道蒙察识。","琴瑟听其真，蚕织五文色。","非君胶漆心，群小志亦得。"]},{"t":"郡斋同元美赋","f":"五言古诗","c":["游子苦行役，驱车自溟渤。","依依平生亲，斗酒日云没。","秋风亦已厉，萧条众芳歇。","何以赠君子，徙倚揽明月。","燕婉当及时，霜雪变华发。","高足蔽天衢，浮云望双阙。","令德一见疑，积毁能销骨。","中怀不复喻，邈若胡与越。","绸缪有故人，知音无仓卒。","常恐远别离，含意向明发。"]},{"t":"送元美 其一","f":"五言古诗","c":["有凤衔灵文，栖栖北海湄。","临流理毛羽，五采以自奇。","飞如摛群星，击若朝霞披。","翱翔千仞冈，亦集梧桐枝。","一鸣叶清庙，再鸣中咸池。","凄风振大野，青云顾我悲。","世无伶伦耳，谁为度参差。","回首顾丹穴，摧藏不可持。","将止帝东园，恐令鶗鴂知。","阿閤在万里，哀号乃见疑。","啁啾榆枋间，燕雀相追随。","清光蔽白日，何当复来仪。"]},{"t":"送元美 其二","f":"五言古诗","c":["夙昔二三子，慷慨扬奇声。","文章凌先秦，词赋无西京。","零落如流星，各怀饥渴情。","念尔策高足，北海日以清。","顾盻当中原，冠盖徒纵横。","明发咏蓼莪，依依恋所生。","悲风蓟门来，涕泣沾我缨。","解带谢时人，驱车薄姑城。","千里见大河，踯躅浮云征。","罢酒不能别，萧萧驷马鸣。","骨肉非一身，意气乃合并。","景光老自爱，率已识荣名。"]},{"t":"答寄俞仲蔚 其二","f":"五言古诗","c":["郁郁龙门山，下临千仞溪。","孤桐生其间，干与浮云齐。","湍水击其隈，回波荡其涯。","野火燔其东，飞雪涂其西。","莫则止黄鹄，朝则啼鹍鸡。","悲风从天来，清商以凄凄。","伯牙不能去，倾耳中自谐。","匠石空扼腕，运斤路何阶。","琴瑟和神人，无乃非其怀。","结根既已异，雨露难独乖。","愿言俯大壑，往就长离栖。"]},{"t":"送李明府入奏","f":"五言古诗","c":["西北夏云列，飞盖亦相望。","供帐被城隅，父老皆扶将。","天子秉百度，作新大明堂。","榱桷曼且硕，抡才自南乡。","山河俯壮丽，肃穆垂衣裳。","是时薰风至，五月开未央。","既奏解愠曲，或和斯干章。","圣颜慰饥渴，帝心简四方。","冢宰上绩书，召见伏明光。","用等课高第，视事称维良。","小臣奉威灵，不得施其长。","谁谓一邑轻，治行乃无疆。","愿言备侍从，珥笔述陶唐。","策勋谅有期，遗爱匪可忘。"]},{"t":"许殿卿郭子坤见枉林园 其一","f":"五言古诗","c":["明时再婴疾，隳官此悠悠。","永言命沮溺，二子乃从游。","田家何所有，樽酒结绸缪。","散发坐园中，辘轳牵寒流。","击我青门瓜，聊且充庶羞。","雨气荡暄浊，披襟御南楼。","开轩纳山色，馀映一以收。","云霞罗四隅，烟火蔽林丘。","伏阴秀禾黍，饷妇媚田畴。","西望华阳宫，若见清河舟。","登临信亦美，旷然销人愁。","愿君爱景光，多暇还相求。"]},{"t":"许殿卿郭子坤见枉林园 其二","f":"五言古诗","c":["佳客即良夜，此会安可期。","结发为兄弟，晤言今在兹。","层台挺浮云，河汉宛其垂。","积阴濯列宿，三五正参差。","前山殿影乱，雨势坐已移。","皎月出平陵，徘徊当照谁。","清光澄暑气，飒若撤长帷。","潦水明树间，流飙澹华榱。","零露响空林，蟪蛄以鸣悲。","世路良独难，斗酒多所宜。","达人忌荣名，千载同一时。"]},{"t":"杪秋同右史南山眺望","f":"五言古诗","c":["南山有幽意，驾言此徘徊。","湖波荡寒城，四座清光开。","金天澄素景，秋气何悲哉。","繁阴递白日，浮云间往来。","落木飒中林，流飙激岩隈。","朝昏上烟火，原隰被楼台。","故乡无滞淫，世路多尘埃。","念我平生欢，离思壮难裁。"]},{"t":"九日集殿卿池亭分赋 其一","f":"五言古诗","c":["卜幽命词客，冠盖至如麇。","白云澹萧晨，黄花媚新酝。","洒翰湖山清，开樽鱼鸟近。","零露偃池荷，凄风携篱槿。","径回片桥出，林瞑寒城隐。","临流濯长缨，飘然袪尘坌。"]},{"t":"九日集殿卿池亭分赋 其二","f":"五言古诗","c":["寒空鹊岭秀，霁野湖水阔。","墟落散城隅，池亭入幽豁。","云阴出水鲜，石色含霜活。","白鸟下烟际，归鸿起天末。","返照款长林，群流乱相聒。","紫蟹壮可持，浊醪美堪掇。","秋高吹台兴，老剧文园渴。","佳节有独醒，吾生岂云达。"]},{"t":"集张使君别业","f":"五言古诗","c":["清河迅寒流，金舆杳空翠。","秋气下高原，苍然西北至。","返照散疏林，萧条烟景异。","零落复佳期，茅茨况幽致。","握手平生人，笑谈出往事。","旧游数子尽，风流吾党备。","千金抵白发，一醉满君意。"]},{"t":"秋夜白雪楼同许右史袭茂才分韵 其一","f":"五言古诗","c":["林烟既曳绡，湖霞亦披绛。","鸡犬静荒村，蓬蒿翳深巷。","烧微见月出，钟清识霜降。","各称浮白乐，未觉呼卢戆。","更赋梁园雪，如流华渚虹。","预愁还城邑，车马纷相撞。"]},{"t":"秋夜白雪楼同许右史袭茂才分韵 其二","f":"五言古诗","c":["返照入平陵，白云出西陇。","天清雁影澹，山空岚气重。","三径何萧条，高人乃接踵。","诸生稷下秀，词客梁园宠。","松菊有佳色，琴樽亦怂恿。","但醉不须眠，寒灯坐相拥。"]},{"t":"送许史得弟字","f":"五言古诗","c":["秋风一萧条，白云自相缀。","翩翩尔曳裾，惨惨吾分袂。","鼓楫大河流，扬帆下衡卫。","平台壮登眺，邹枚俨兄弟。","既出兔园篇，颇兼子虚制。","词赋有知遇，王门即恩惠。"]},{"t":"答张秀才问疾","f":"五言古诗","c":["青阳荡积晦，素雪亦云熙。","仲月陶嘉树，閒庭暧流滋。","微风中夜兴，清光动遥帷。","残灯出四壁，钟鼓一何痴。","闭关抵百役，内热耿于罹。","养痾终年岁，人生能几时。","服散代晨餐，匕箸厌相持。","哲夫秉大观，一往不复疑。","所愧乏明德，盈缩无常期。"]},{"t":"寄题离薋园 其一","f":"五言古诗","c":["芙蓉媚昭质，初服一何好。","繁霜日夜零，悲风起中道。","鶗鴂既已鸣，所遇无芳草。","驰骛终年岁，红颜足用老。","美人怨迟暮，回车自不早。","芜秽沫荣名，同心以相保。"]},{"t":"寄题离薋园 其二","f":"五言古诗","c":["兰生有幽性，零露峻其姿。","含芳在空谷，清风来御之。","孤根亦何伤，众草故难为。","萎绝同粪壤，中情君岂知。","愿言置怀袖，延伫及良时。","荃茅一以化，奈此菉与施。"]},{"t":"赠元美兄弟","f":"五言古诗","c":["唯帝飨金石，拊髀封疆臣。","二子越枕戈，避雠栖海滨。","及时列冤状，含意遂俱申。","乃望渔阳戍，北风飘沙尘。","若见姑蔑旗，阴雨施威神。","吴门有丘陇，旧与要离邻。","陈尸赫中寝，国命委荆榛。","楚王黜费氏，棠君纪人伦。","何如上公服，宠光襚所亲。","愿无废前劳，报恩致其身。"]},{"t":"虎跑寺泉","f":"五言古诗","c":["大士始结构，凿空偏此丘。","二虎自南岳，掉尾从师游。","神威攫地脉，佛力驱阳侯。","枯火迸石罅，松根解绸缪。","势宁决蹯去，挥锡怒不休。","至今喷岩壑，水犹咆哮流。","酌言生壮心，一啸风飕飕。","海眼在其下，潮汐故可求。","不然胡僧咒，争使波澜浮。","穿壁吐长涧，夹寺潴龙湫。","疑作故山雨，片云驻岣嵝。","归应出东林，无为惠远留。"]},{"t":"求志园","f":"五言古诗","c":["吴门有奇士，二弟偕好修。","鞍马照红颜，往来长者游。","带剑何良绮，垂缨亦绸缪。","岂不揽豪贤，我志非所求。","驾言旋北郭，灌园依一丘。","白云荡虚壑，馀映翻寒流。","置酒临高台，邈焉怀其俦。","鸿鹄既云举，千里常悠悠。","清风动帷幕，皎月光沉浮。","读书见古人，鸣琴调逾幽。","无取广川观，昔在汉阴叟。","天子御飞轩，龙蠖时乃瘳。","回首望中原，壮心未可收。"]},{"t":"子与至武林","f":"五言古诗","c":["良时能自至，嘉会无常期。","长飙吹浮云，奄忽东南驰。","依依曳景光，泠泠发馀悲。","非君命俦匹，游子安可为。","大江折其流，武林怆以摧。","念今在往路，执手野徘徊。","何必同一身，中怀贵不疑。","弹冠有逸响，驾言即前绥。"]},{"t":"古意寄德甫 其一","f":"五言古诗","c":["悠悠我行役，往路殊未央。","春华不须臾，奄忽践严霜。","安知疑与喻，风波起褰裳。","浮云邈无所，游子依故乡。","长当远别离，何必复彷徨。","鸳鸯自踟蹰，黄鹄已翱翔。"]},{"t":"古意寄德甫 其二","f":"五言古诗","c":["嘉会在俛仰，良时不可留。","悲风自远至，大江以悠悠。","中怀有白璧，千载为一投。","飞龙双欲乖，胡马群相求。","徘徊视四海，含意各未酬。","念此平生亲，从彼浮云游。"]},{"t":"古意寄德甫 其三","f":"五言古诗","c":["明月照我床，清风感重闱。","遗书发怀袖，彷佛见容辉。","古欢匪自今，游子当何依。","千秋一高唱，岂独知音稀。","莫言苦行役，极宴不如归。","努力两黄鹂，为尔故乡飞。"]},{"t":"赠德甫","f":"五言古诗","c":["豫章生庭中，结根西山隈。","江流一荡潏，悲风千里来。","丝萝谢依托，冰雪抱崔嵬。","非不曼且硕，时无柏梁灾。","截为玉女瑟，绝胜龙门材。","展我清商曲，弹作临高台。","洪厓颔颐坐，五凤郁徘徊。"]},{"t":"灌甫东陂宴","f":"五言古诗","c":["王孙古城隅，东陂托偃仰。","回薄始蓊杂，高台忽峻敞。","风波一以交，沦漪恣遐放。","列雉翳中流，返照幕鱼网。","曲磴盘层阴，清房殷清响。","并逸金谷韵，兼诣濮阳赏。","恢台戒隆曦，披发命吾党。","美酒涤烦嚣，泠言发神爽。","至今河朔人，垂声得倜傥。","直置病游梁，为心任独往。"]},{"t":"送靳颍州子鲁","f":"七言古诗","c":["华阳馆前桑叶飞，荆轲台上送将归。","为言击筑悲歌者，当时酒人今是非。","太守褰帷蓟北来，燕山忽断楚天开。","郡中晓月雩娄出，雾里秋涛桐柏回。","黄金玺书发明光，东走颍州西豫章。","君家兄弟二千石，承恩不数尚书郎。","朱轓双出领专城，五马踟蹰五马行。","汉主乘春徵计吏，小冯何让大冯名。"]},{"t":"送新喻李明府伯承","f":"七言古诗","c":["尔昔红颜客蓟门，献书不报哀王孙。","一朝致身青云里，座上还开北海樽。","余亦题诗郭隗台，燕山秋色对衔杯。","论交共惜黄金尽，此处空悲骏马来。","可怜郢曲今亡久，下里之歌吾何有。","文章稍近五千言，雅颂以还十九首。","才子新传白雪篇，江城忽借使君贤。","那堪西署为郎者，多病离居卧日边。"]},{"t":"赠张子含茂才","f":"七言古诗","c":["忆昔中丞全盛时，少年裘马相追随。","忽逢世变夙心违，逆旅荒凉旧识稀。","古来万事皆如此，何用空悲昨是非。","流水无情白日速，红颜犹在黄金微。","饮君莫辞燕市酒，欲行不行且携手。","青云今有故人存，好赠绨袍哀王孙。"]},{"t":"刁斗篇","f":"七言古诗","c":["阴山战合胡天黑，汉兵大呼单于北。","边秋日落五原屯，碛火夜连千灶食。","骠骑横戈拂铁衣，悲风黄草白榆飞。","渡河鸟阵旌旗伏，卧壁龙沙鼓角希。","征人马上援枯骨，满地清霜刁斗发。","朔气遥传瀚海云，寒声乱动轮台月。","掩笳骄雏听垂泣，按剑材官怒指发。","宫女琵琶咽逝波，使臣旄节凋幽窟。","谁能绝漠靖边氛，哀响如今不可闻。","六郡少年思转斗，摐金犹忆李将军。"]},{"t":"送张子参募兵真定诸郡","f":"七言古诗","c":["蓟门昔在烽尘中，匈奴火照西山红。","毡庐相望赤县隘，枭骑未厌神畿空。","君王拊髀过郎署，侍臣扼腕谈边功。","每饭不忘钜鹿战，千金先发华阳宫。","邯郸少年游侠子，腰间匕首悬秋水。","出身愿属羽林儿，横行誓夺单于垒。","腾装夜别纵博场，贳酒朝辞挟瑟伎。","马上风云八阵成，帐前鼓角三军起。","故人新贵宠轩墀，乱后高名众始知。","国士渐看投笔至，主恩况许请缨为。","天寒恒岳倚长剑，雪满滹沱拥大旗。","归来汉苑生春草，见尔论兵散幕迟。"]},{"t":"齐侠行","f":"七言古诗","c":["简书八道发明光，诏徙群豪赴朔方。","神武临轩耽虎视，将军秉钺郁鹰扬。","山东十二诸侯国，海滨五百义士乡。","厌乱齐臣思定伯，殷忧汉使出勤王。","敌骄拟纵田单火，客愤能飞驺衍霜。","彀骑人人白羽箭，民兵处处绿沈枪。","九河寒色旌旗动，岱岳秋阴鼓角长。","各倚少年轻燕颔，曾经遣戍守渔阳。","一匡九合岂受赐，排难解纷不可当。","往岁潢池先陷阵，三时大战银冶场。","功名未致有庄贾，肝胆欲倾无孟尝。","天子只今顾西北，男儿侠骨埋边疆。"]},{"t":"赋得金谷园障子","f":"七言古诗","c":["谁将金谷传毫素，座上无人不回顾。","乍展旋惊涧水流，才开已识河阳路。","四壁真看片锦围，中庭如见双鬟度。","移席休临坠妓楼，解衣欲挂沙棠树。","彷佛明妃出塞吟，听来未必梁尘误。","诗成酌我我岂辞，便过三斗无论数。","绿珠安在恰当垆，似留且往势可呼。","意惨昆崙紫䆗窱，色寒沧海红珊瑚。","君家富贵合如此，此时那知有障子。","纵然客散掩空堂，犹闻夜夜春风起。"]},{"t":"送申职方谪莱州推官","f":"七言古诗","c":["嫖姚三疏奏明光，九月王师扫大荒。","不求十万羽林骑，从军但请尚书郎。","看君未是侯门客，草檄论兵一当百。","片言不合径拂衣，坐使元戎气萧索。","汉主临轩送逐臣，褰帷海上及行春。","正逢匹妇衔冤雨，一洒浮尘不污人。","游燕曾携短匕首，袖里虹蜺今在否。","出关若见弃繻生，为余持赠单于走。"]},{"t":"送赵员外行边","f":"七言古诗","c":["狐白之裘紫骝马，鸣鞭东走渔阳野。","自言天子授长缨，明光殿前三使者。","飞檄远度桃花山，昨日辽西校战还。","吹律春风回黍谷，扬旌暮雪洒榆关。","关门一望烟尘色，抵掌志驰伊吾北。","岂独秦人重绕朝，誓令羌虏避充国。","此行不按督亢图，欲画地形取匈奴。","指挥千障铁如意，出入双鞬金仆姑。","骠骑将军绿沈甲，鹴鸠大夫黄石法。","碛里兵屯种玉田，云边燧起弹琴峡。","元戎幕府赠吴钩，太守离歌岐麦秋。","看君归奏称上意，何足道哉万户侯。"]},{"t":"赋得狼居胥山送李侍御","f":"七言古诗","c":["材官十万绝大幕，踰河一战胡儿却。","夜纵翼兵袭章渠，系以往封狼居胥。","姑衍山头列旗鼓，中坛拥纛陈首虏。","帐前面缚三当户，骠骑将军醉歌舞。","北风千里云摧颓，瀚海波涛蹴日回。","汉家天子雄才哉，捷书亲发柏梁台。","君持绣斧五原郡，牧马单于不敢问。","黄沙白草寒冥冥，今年为王犁二庭。"]},{"t":"送徐汝思郎中入蜀","f":"七言古诗","c":["岷江东流何渺茫，仙舟西去指华阳。","峡深当画暗雷雨，白帝青天豁大荒。","一望峨眉山上月，风吹寒影堕潇湘。","益州部里占星使，草色春时接夜郎。","客将河汉支机石，归自乘槎历七襄。","苌弘碧血埋难化，杜宇啼魂怨未忘。","胡不为我排阊阖，愿君致之北斗傍。","即今叱驭九折坂，金精元气参翱翔。","雪峰突兀三飞梁，中挂鸟道通蛮方。","司马长卿子虚赋，其文可以陵太苍。","临邛小监杨得意，亟荐词臣谒建章。","后来此事益寂寞，烟尘万里遥相望。"]},{"t":"叶舍人","f":"七言古诗","c":["舍人家世称儒素，供奉班联起居注。","仙郎尽识凤凰毛，父老相传骢马步。","当日兰台抗疏还，读书高卧柳亭山。","至今犹忆张文纪，年少官微犯帝颜。","闻君夜入蓬莱直，归梦时时动秋色。","翰染金茎彩露寒，庐开玉树青天逼。","回首南云春事繁，浮丘峰下小桃源。","他时摇艇新安水，坐把江花醉故园。"]},{"t":"送谢茂秦","f":"七言古诗","c":["孝宗以来多大雅，布衣往往称作者。","谢家玉树操郢音，其音弥高和弥寡。","寓梁曾曳王门裾，游燕欲荐中涓马。","岂无冠盖映当时，满眼悠悠世上儿。","文章千载一知己，交结何须钟子期。","此物有神兼有分，富贵浮云不与之。","卢楠坐衔越石恩，醉后感激肝胆言。","苍鹰睚眦鹦鹉赋，身挂罗网何由翻。","殷忧楚奏秦庭哭，遂雪黎阳国士冤。","归去东将钓沧海，安能贫贱常丘樊。","早借江鸿报消息，或卧春云且故园。"]},{"t":"送太医令周一之从大将军出塞","f":"七言古诗","c":["武皇按剑明光宫，夜发材官六郡雄。","临轩亲遣上将军，誓扫匈奴成大功。","白羽九边传汉月，霜戈千里排胡空。","辕门岂闻天子诏，帷幄宁多策士风。","书记翩翩尔其选，志勒燕然禅姑衍。","业许原尝念已深，情忧平勃交仍浅。","药囊每拟提荆轲，骢马何曾避桓典。","淮阴恶少旧相轻，朔方健儿知姓名。","身为揖客元戎府，意气秋高出塞行。","二百年来无一战，今日王师遂北征。","便当灭虏始朝食，不击单于不解兵。"]},{"t":"南溪老树行","f":"七言古诗","c":["老树横溪十亩阴，下有跳浪三百顷。","酒罢扪萝坐其上，白眼青天何不逞。","牛斗之间见浮槎，苍茫宇宙成漂梗。","念我平生湖海客，衣裳泠泠风驭冷。","文章八代俱望洋，心事几人同哀郢。","醉里谁堪此陆沉，侠来气与千涛猛。","洛浦明珠旧寂寥，渥洼神骏空驰骋。","翻然大叫观者摧，那知世路沧洲永。","投足还探河伯宫，俯身欲拾中流影。","骊龙蜿蜒垂雾雨，虹霓缭綟含光景。","须臾力疲神亦眩，乾坤低昂发深省。","最奇披发泅吕梁，愿言洗耳临箕颍。","初看长驾出鼋鼍，岂云吾道终蛙黾。","王郎驱石到渤澥，徐子招招回舴艋。","此时共济失狂澜，却悲胥溺情难整。","泥涂岂可困豪㑓，男儿相逢誇项领。","遂忆鸣鞭昨夜归，湘娥汉女犹延颈。","群灵至今未敢散，寒江飒飒开尘境。"]},{"t":"送公实还南海","f":"七言古诗","c":["梁生偃蹇谁与伦，梁生偃蹇无与伦。","为郎十月不厌意，上书乞归南海滨。","文章往往迕时好，富贵安得婴其身。","独存肝胆论交者，一一凌云作赋人。","忆昨击筑饮燕市，酒酣以往气益振。","黄金之台空嶙峋，华阳之馆谁为薪。","騊駼騄耳俱良马，剑客博徒皆俊民。","梁生徐生情最亲，宗生王生诗更新。","经过但坐歌白云，罢曲彷徨若有神。","挥毫夜夜摇星辰，襟期矫矫何能驯。","梁生此事成万古，欲别牵裳遂具陈。","罗浮之山何崔嵬，下临莽苍波涛开。","维舟跋浪长鲸出，倚杖垂天大鸟来。","北望中原寥廓哉。","飞厓坐揽百粤色，群峰黝渺行风雷。","梁生之庐搆烟雾，千寻薜荔青摧颓。","有时高咏反招隐，岩壑无人秋雨哀。","尉佗椎结本赵侠，陆贾纵横一汉才。","丈夫有道在龙蠖，还能与世相裴徊。","梁生何为终蒿莱，梁生慎勿终蒿莱。"]},{"t":"击鹿行","f":"七言古诗","c":["徐卿意气殊不偶，买鹿百金求其牡。","华堂燕客忽自放，醉把邯郸铁匕首。","须拟麟从帝薮游，未闻鹿触匈奴走。","高材吾党复谁过，文章矫矫驱群丑。","失日难将四海求，逐来定死诸公手。","毛洒旋疑霜雪寒，角摧更见珊瑚朽。","王郎大叫捧铜盘，接饮其血㰱以酒。","顾我前呼历下生，与君相爱为君寿。","旧时疾足今能否，安得新诗满人口。","须臾碧眼胡儿至，落砧脯腊无不有。","下箸已畏翠釜空，纤羹更出青闺妇。","众看杌上肉如陵，覆蕉尚在隍中守。","嗟乎曲士梦何久，徐卿独醒可与友。"]},{"t":"送元美","f":"古风","c":["王生二十趋明光，是时作者不可当。","世上之名他自误，须君千载垂文章。","夙昔陆沉秋宪府，风尘惨淡尚书郎。","心知此物难再遇，片语论交燕市傍。","携手七陵朔漠色，悲风九月吹白杨。","居然宇宙见雄俊，睥睨今古神飞扬。","流俗纷纷失肝胆，那能结客声利场。","近日操觚满京洛，江河决注非其长。","家握灵珠户和璧，及逢周客皆深藏。","高才楩楠与杞梓，吾道麒麟或凤凰。","清庙遗音壮昭代，天庭火藻悬衣裳。","生也经纶斯滥觞。","混尘安取金跃冶，养锐更羞锥处囊。","伊周屈宋傥易地，钧衡艺苑俱称良。","生也为情诚彷徉。","但愿右挹击筑之荆卿，左拍接舆之楚狂。","二豪侍侧乃蜾蠃，四子讲德如蜩螗。","举觞白眼天茫茫，秋风胡为归故乡。","亦欲送生从此去，留生不住悲河梁。","彩虹千尺挂碣石，赠生千里为帆樯。"]},{"t":"杨山人 其一","f":"七言古诗","c":["苕溪之水何泠泠，吴山一峰天目青。","千林万壑子云亭，从他世人还解事，白头不厌太玄经。"]},{"t":"杨山人 其二","f":"七言古诗","c":["吴门市卒能逃名，长安贵人非其情。","南山薄田春自耕，盛世为农亦足老，少年何用随诸生。"]},{"t":"杨山人 其三","f":"七言古诗","c":["千篚湖绵白雪开，满江稻色黄云来。","山中客醉颔其颏，自言七十岩耕者，帝于我有何力哉。"]},{"t":"杨山人 其四","f":"七言古诗","c":["长裾不为王门宾，千金散尽江湖人。","菰城一卧三十春，看尔红颜逐燕雀，终然白发行风尘。"]},{"t":"送子相","f":"古风","c":["自作白云郎，未厌沧洲意。","偶然薄禄混风尘，论交千里贤豪至。","元美翩翩多奇气，南越梁生亦雄视。","二子招携从此逝，尔今卧病缘何事。","绿鬓还乡已壮游，锦帆十月下扬州。","移家好住昭明楼，种瓜莫羡东陵侯。","文章万古垂大业，富贵浮云非所求。","知君林壑百不忧，图书四壁高枕秋。","世人那识淮海士，须行便为名山留。","丈夫义岂辱颜色，使我摧眉去即休。","安能訾哫向权势，咄唶空令达者羞。","夙昔竟寥阔，后来复泱莽。","相看一别雨坠天，他时神剑来精爽。","既言郊薮走麟凤，朝廷宁得无吾党。","卿也抽簪且偃仰，渔阳日影黯如黡，蓟门雪花大于掌。","马上燕歌变徵声，壶中酒尽君当往。"]},{"t":"侠客行为子与赠吴生","f":"古风","c":["本自吴越冶游郎，结交燕蓟少年场。","长裾不曳朱门里，樗蒱大叫青楼旁。","被酒目摄羽林骑，拥金作使邯郸倡。","弟畜灌夫，师事田光。","得意一言，失意一言。","相怨一方，相慕一方。","男儿过逢好惊座，世事握龊宁陆梁。","姓名何惜借轻薄，出处未须论侯王。","亲知犹向隅，有钱徒充囊。","雠家犹戴天，有客徒满堂。","猛虎可值，俗子莫当。","平生片心照秋水，明日报恩还故乡。"]},{"t":"留别子与","f":"七言古诗","c":["从君几醉燕京酒，旧游花月回白首。","相看零落眼中人，二子河梁重携手。","忆昨青山坐西署，于今此事成不朽。","交态萧条尔自谙，浮名惨淡吾何有。","争道贤豪拥上林，华阳台馆尽黄金。","长卿词赋徒壁立，曼倩佯狂合陆沉。","平生得意向知己，常将颜色当同心。","北望诸陵一拊髀，悲风千里来寒阴。","春草如云覆四野，我行逶迟五其马。","十载为郎愿已违，出门况复悠悠者。","汉臣犹未老冯唐，每饭岂忘钜鹿下。","岁晚江湖梦独遥，秋深鸿雁书堪把。"]},{"t":"题申职方五岳图","f":"古风","c":["谁将五拳石，错落余之堂。","坐看素璧缠云雾，安得群峰挂屋梁。","更愁深林暝难入，岚影明灭侵衣裳。","左眄欲生沧海日，右临少昊凝清霜。","扫练白沙走朔漠，回毫紫盖垂炎荒。","须臾二室崚嶒出，杳然置我烟霞傍。","不闻吹笙控飞鹤，浮丘子晋俱冥茫。","良工拓笔天为开，长风西逐层阴来。","中庭无人数移席，巅厓乍堕松杉摧。","眼前突兀太古色，九州惨淡如浮埃。","宓牺神农未诞降，元气始判洪濛哉。","大江浩浩黄河流，巨野相望悬莫秋。","异代犹探秦汉策，真形或结金银楼。","凭轩忽惊去千里，青鞋竹杖胡在此。","复疑窈窕迷归路，何当税驾聊徙倚。","捲帘逾添空翠寒，张镫更爱夕阳紫。","邢襄小吏困时名，知君雅意怜泥滓。"]},{"t":"送永宁许使君 其一","f":"七言古诗","c":["邢州十月凋白杨，城头出云垂太行。","把酒相看日欲堕，五马踟蹰大道傍。","问君胡为万里去，小臣罪合投穷荒。","我闻西南罗施国，风气郁塞殊阴阳。","长官椎髻见朝吏，海蛮醉鼓橐中装。","男儿贵至二千石，何地不可称龚黄。","壮游须令百粤尽，探奇更得浮沅湘。","永宁自恶无瘴疠，明年雨露生还乡。"]},{"t":"送永宁许使君 其二","f":"古风","c":["使君落魄高阳徒，结交李生仍狂夫。","醉后裂眦一相视，怒发上指浮云徂。","白日并堪出肝胆，黄金谁为收泥涂。","长安少年太巧宦，依倚权门何事无。","失策始就公府辟，得意岂领蛮夷符。","尔今折腰揖下吏，我更掩泣临穷途。","奇数能令遇合变，美才常被功名愚。","武溪毒淫须自爱，九重沈深不可呼。","忆昔终军击南越，乡里小儿何其粗。","荒服尽沾大汉德，单车入郡歌来苏。","固知永宁之州才如斗，天子求贤三辅图。","傥有徵书到迁客，五马好过秦罗敷。"]},{"t":"送王给事使潞","f":"七言古诗","c":["忆昔胡尘暗蓟门，六军如云集阙下。","天子授钺临轩槛，宜阳王公其人者。","风流旧出城朔方，简在新除大司马。","是时将帅实跋扈，倾耳履声入北斗。","引经答诏动称意，草檄提兵常在手。","帝力自堪制阃外，股肱佐命吾何有。","一从诛乱朝廷清，四海亦重尚书名。","看君少年青琐客，汉家今得韦玄成。","袖里弹章百不避，囊中谏疏垂欲行。","主恩三晋持节使，上党诸侯带砺功。","泛槎春度浊漳水，设醴夜宴虒祁宫。","归米炼石补造化，论思庭诤才何雄。"]},{"t":"郡斋同元美赋","f":"七言古诗","c":["夙昔红颜一大夫，乘轺河朔何为乎。","除书岁下不得调，鼓其刀笔宁壮图。","帝恩初欲存折槛，谓尔祝网从皇都。","相逢但饮邢州酒，太守况即高阳徒。","庭前秋色正惨淡，囊里新诗复有无。","醉歌出塞云中曲，朔气飒沓来飞狐。","路傍小臣久汩没，安得座上开江湖。","眼前大雅竟谁是，作者如山道各殊。","更须一日论万古，挥毫振臂群雄呼。","维时海内称二子，高名自喜王生俱。","白雪青天动萧瑟，台郎郡吏同崎岖。","楚璧照邻不敢献，蛾眉在宫还自涂。","王生仰视浮云徂，矫手捋我颔下须。","与君周旋在今日，还能百万来长驱。","忽然神气回莽苍，孤城摇落相踟蹰。"]},{"t":"跳梁行寄慰明卿","f":"七言古诗","c":["武昌季子吴国伦，左迁三载匡庐春。","红颜便着青云色，白眼岂是功名人。","邢州太守昔入计，犹自金闺侍从臣。","顾问片言摇日月，弹章一字动星辰。","虽然旧属平津吏，常苦跳梁不可致。","调笑纵横倒四筵，交驩往往非其意。","世间那得郢中歌，君但论诗吾且睡。","何须更比谢生肩，但应独把王郎臂。","萧条颇似东方生，南康郡里忆承明。","文彩纵然倾汉王，恢谐难以取公卿。","画眉石镜二女裸，濯足长江九派清。","此儿寻常未易识，偷桃卖药行妖精。","近来犹尚凭陵否，俯仰浮沉无不有。","朝读司空城旦书，夜沽茂宰柴桑酒。","成败宁关达士心，卷舒终在朝廷手。","随他肉食作雄飞，饶我褐衣称下走。","党禁重开祝网年，一时逐客宠光偏。","晚收已抱泥涂恨，更谪如何不可怜。","事急谁能驰叩阙，家贫未拟罢归田。","再来地僻逾高枕，就使荒凉给俸钱。","壮游万里君须见，青琐凤池元不贱。","使气能令魑魅藏，出身曾厌欃枪变。","楚狂岂止接舆贤，秦孽犹堪背城战。","回首畏途真自知，一官不绝才如线。","难将此物斗翱翔，妒口含沙未可当。","四海弟兄堪并起，中原我辈正相望。","总看弃置风尘里，不作踟蹰道路傍。","鼓枻更逢渔父笑，岂应憔悴老沧浪。"]},{"t":"此儿行重寄明卿","f":"七言古诗","c":["我闻南康大如斗，明卿佐理常什九。","昨日中丞抗疏荐，贤声辄满朝廷口。","豫章计吏入图事，爱君未敢援以手。","小臣怜才上白状，相公良久疾其首。","量移亦已从浩荡，不然径逐此儿走。","谁知片言触忌讳，毕竟功名成掣肘。","丈夫失意分自当，穷来傍人人避藏。","苦我折腰骨太劲，看他伏谒项能强。","纵令慢世无不可，似尔干时岂所长。","莫作拂衣少年态，宦游须使及春阳。","大舒楚歌小舒舞，是处江山好断肠。","王郎至今栖北海，帐前万骑绿沈枪。"]},{"t":"拂衣行答元美","f":"七言古诗","c":["五原驱车兴殊浅，三秦卧病秋云高。","束带那能见长吏，谈经何以随儿曹。","上书一日报明主，愿乞骸骨归蓬蒿。","小臣采薪业不佞，闻道巢由亦已逃。","拂衣中原风雨来，群公祖帐青门开。","二疏一去三千载，大夫未老宁贤哉。","新乡城西重回首，当时叱驭其人走。","路傍伏谒莫敢动，囊里俸钱君但取。","此辈交情虽可见，吾徒大名终在口。","于今偃息南山陲，闭户不令二仲知。","负海少年大跋扈，遣使问我抽簪期。","百尔不分一狂客，余发种种何能为。","玄经半卷常自诵，浊酒千钟醉不疑。","五子江湖正漂泊，黄鹄摩天慕者谁。"]},{"t":"答许右史 其一","f":"七言古诗","c":["黄须芃芃田舍翁，倾身坐向钱孔中。","长颊便便美少年，行步顾影私自怜。","谁知腐鼠能为祟，纵是神仙有播迁。","使君似识浮云意，蹉跎实为功名利。","已拚酒隐富贵世，潦倒佯狂百无忌。","浊醪恰供十日饮，酣法须与当时异。","五斗乍可调燥吻，飞觞二子雄相视。","醉杀不作傲杯人，迩来那得独醒事。","魏文大白满如月，曾托属车称国器。","若言此物非其任，尔家破瓢亦应弃。"]},{"t":"答许右史 其二","f":"七言古诗","c":["王门隐者身坎坷，老曳长裾裾婀娜。","自言能料一生事，及至干时计常左。","从它惨淡复为谁，即得新诗题向我。","雨雪蓬蒿共三径，春色俜伶馀药裹。","浊醪但熟贫亦足，微官才罢病辄妥。","胸中㙼块故须浇，乘兴往往无不可。","白眼生成薄禄相，青山合就渔樵夥。","赵壹疾邪众所摈，邹阳暗投才应坐。","羡尔悠悠世上情，回头数子殊么么。"]},{"t":"送莱芜萧簿","f":"七言古诗","c":["萧生业本儒术起，稍因读法得其指。","栖息十年白鹿洞，担囊一卷青乌子。","岱宗雄蟠大海滨，衣冠气王中有人。","我家松槚三千树，鞍山东望华不注。","为说干时常轗轲，独怜明主能知遇。","莱芜作簿更谁群，但恨无过范史云。","釜里蠹鱼堪自见，鞭下虫蛆讵忍闻。","看君才岂催科拙，请谒公门非所屑。","藩臣答诏误承恩，翻然遂就迁官列。","匹马悠悠复路岐，即今失意欲何之。","同乡冢宰谙名姓，府掾郎曹伫可期。"]},{"t":"岁杪放歌","f":"七言古诗","c":["终年著书一字无，中岁学道仍狂夫。","劝君高枕且自爱，劝君浊醪且自沽。","何人不说宦游乐，如君弃官复不恶。","何处不说有炎凉，如君杜门复不妨。","纵然疏拙非时调，便是悠悠亦所长。"]},{"t":"赠殿卿","f":"七言古诗","c":["前年赐环承主恩，去年解裾辞王门。","身经畏途色不动，心知世事口不论。","自顾平生为人浅，羡君逃名我不免。","自怜垂老尚凭陵，羡君混俗我不能。","有酒便呼桃叶妓，得钱即饭莲花僧。"]},{"t":"金吾行赠戴将军","f":"七言古诗","c":["先皇诸将何其雄，君家大人国士风。","赐钱留起嫖姚第，诏宴数入兰台宫。","五云忽变石城气，七校亲随万乘东。","当年带砺山河在，四海车书日月通。","侍从敢闻潜邸事，朝廷竟录代来功。","此时十岁羽林孤，跃马能弯两石弧。","汉主临轩求故剑，承恩一拜执金吾。","生成燕颔宁辞武，得奉龙颜不羡儒。","三提卤簿陪陵寝，再护楼船下郢都。","禁中自失张安世，天上还看周亚夫。"]},{"t":"逼除过右史水村江山人同赋","f":"七言古诗","c":["夜来北渚北风急，打头雪花大如笠。","片纸东飞右史书，诘朝小作湖中集。","到门白鸟出高巢，系马南山迸人入。","使君亭午未解醒，肃客登筵一长揖。","地僻兼无俗子妨，樽空况有邻家给。","意气还须我辈看，功名但任儿曹立。","瞥眼旋惊青岁徂，沾唇莫放金杯涩。","世上悠悠已自谙，即今不饮嗟何及。","醉听楚调起寒云，綵笔凭陵朱丝湿。","平生多少伯牙心，此日因之寄篇什。"]},{"t":"赋得雁池送许右史游梁分奈字","f":"七言古诗","c":["汉家藩国称冠带，雁池多暇为高会。","宾序同推枚叟尊，星潢共指梁王大。","赋成锦字映长流，酒酣飞羽传寒濑。","藻翰常生授简中，潺湲不散鸣筝外。","清影朝含竹苑霜，悲声夜杂吹台籁。","白首君恩岂稻粱，朱门旅迹非萧艾。","极知慕侣倦游人，秋来肺病谁能奈。"]},{"t":"道逢郭子坤拥妾戏柬","f":"七言古诗","c":["城东桃花喷路光，春风吹送孝廉郎。","自拥佳人驮细马，时临绿水照红妆。","罗裙已夺石榴色，秃袖单衫杏子黄。","蹋镫微笼双玉趾，扬鞭笑起两鸳鸯。","同栖孔雀言犹妒，并蒂芙蓉愿始偿。","为谢使君休借问，郭家少妇身姓王。","二八盛年真擅宠，只今三十尚专房。","持斋能苦头陀行，发誓曾烧顶庙香。","浩劫自知仙女分，他生常在世尊傍。","每修好事辞书舍，但有佳期入道场。","才着霓裳颜更少，但盘云髻婿先狂。","假令不信吹箫侣，试向秦台看凤凰。"]},{"t":"和许长史筝伎篇","f":"古风","c":["君不闻秦筝多慢声，平台女儿新长成。","家本邯郸行步好，生年十三指爪清。","安得此双弦索手，那能独酌高阳酒。","正值倾囊无俸钱，将来换马还肯否。","自从解赠同心结，不惜樽前香腕折。","几回玉柱雁池飞，春愁散作梁园雪。","合就罗敷陌上桑，含颦一啭发中堂。","遥知华发王门客，纵是风流也断肠。"]},{"t":"答寄殿卿见梦之作","f":"七言古诗","c":["忆昔红颜日携手，一别三年非不久。","纵使天台记阮郎，也应梁苑称枚叟。","故人多病卧青春，华发如蓬自看丑。","漫尔风流更旁骚，从他憔悴仍醉酒。","悠悠世上竟须疑，梦里相逢知是否。"]},{"t":"和殿卿春日梁园即事","f":"七言古诗","c":["梁园高会花开起，直至落花犹未已。","春花着酒酒自美，丈人但饮醉即休。","才到花前无白头，红颜相劝若为留。","春风何处不花开，何处花开不看来，看花何处好空回。"]},{"t":"答寄子威","f":"七言古诗","c":["刘生家本安东子，不尔高名那如此。","十载论交少闻问，君胡尺书数千里。","苍头大奴前置辞，主人束发重知己。","家本阖闾城下儿，清风独为延陵起。","便从出刺三河还，揽辔争誇按百蛮。","早岁升公趋汉署，只今谢客卧江关。","虽言万事归来好，乍可论交到谁老。","犹作凤凰池上看，穷途杀更耽文藻。","中间跌荡复王郎，伏腊扁舟发太仓。","但语即翁常在口，彼时多士俨成行。","宦情渐觉绨袍胜，秋兴翻随綵笔强。","魏倩一珠才照乘，主人双璧竟登场。","倡余和汝篇相及，日居月诸业以集。","共道提戈虎穴回，傥容投谒龙门入。","开椷寒色散阳湖，白雪楼空岳影孤。","不尽雄才推二妙，止如古调已吾徒。","一当单于则岂敢，相遇中原尚足图。","但语主人须自爱，一时长句似君无。"]},{"t":"酬李东昌写寄白雪楼图","f":"七言古诗","c":["诗名东郡沈隐侯，那复擅奇顾虎头。","江湖槃薄有能事，画我山中白雪楼。","推毫已经海色至，无乃兼驱蛟蜃游。","须臾百里岱阴合，咫尺疑闻清河流。","华不注山得非雨，平陵以西胡独秋。","松风似欲卷绡起，良久看云失去留。","丹青快意痴如此，丘壑过人老即休。","使君实解郢中调，为尔深知宋玉愁。"]},{"t":"送郑生游大梁诗","f":"古风","c":["君不见黄鹄高飞未可罗，榆枋之雀奈我何。","拂衣春色为黯淡，故山高卧白云多。","风尘谁识大梁行，夷门轻薄笑侯生。","虚左莫言公子事，今日邯郸已罢兵。","金丹初出照人寒，瑶草千年老鹖冠。","更欲清秋观渤海，那能渴病滞长安。"]},{"t":"代香山寺老僧答","f":"七言古诗","c":["老僧何处来迎客，身无袈裟足无舄。","虽有弟子今流离，独向空山种麻麦。","先时长者布黄金，大师说法如来席。","浮图中霄天乐下，禅台雨花坐盈尺。","共道当朝少游幸，唯此祗园有恩泽。","綵丈晴连鹦鹉林，宫娥晚傍蟾蜍石。","侍从求看贝叶编，焚香再拜开琳碧。","我往能言西域文，珠函为取华严译。","自复悬灯香炉峰，君其问腊庭中柏。","何曾马绕招提鸣，未见沙门畜四兵。","突厥公然驰赤县，湖外秋风笳吹声。","犹疑穷谷岂遽至，已闻野哭尸纵横。","裹创被血窜榛棘，问之不答惨且惊。","须臾马驼蔽陵壑，三骑五骑擐长缨。","抨弓北岭饮南涧，骄气直欲凌欃枪。","一骑常驱百汉人，一人常联二骑行。","翻身仰射罘罳落，束茅纵火烧朱甍。","岂无卓锡笞其背，佛力不祐人心倾。","西堂北丘缘业恶，寺前荒冢遂峥嵘。","亦是官军入援急，匈奴飏去归其营。","匍匐渐从草莽出，昼伏夜走同狐鼪。","衣钵荡尽微躯在，性命真如飞鸟轻。","丈人岂愿闻丧乱，神州岂宜有战争。","故人更邀住庐岳，万乘垂衣右北平。","燕中耆旧寄书说，早晚单于和议成。","语罢空林转萧瑟，茫茫天地终何情。"]},{"t":"酬皇甫虞部寒夜书怀见寄","f":"五言律诗","c":["兄弟播清徽，词林振羽飞。","再来郎署重，何谓宦情违。","夜雪留沽酒，寒灯坐掩扉。","共嗟羁物役，岁晏此依依。"]},{"t":"圆砚效徐庾体","f":"五言律诗","c":["片石分云出，良工向月删。","自疑临璧水，谁为缩壶山。","洗墨沉金镜，呵冰断玉环。","画眉京兆妇，纤指曲池间。"]},{"t":"秋扇","f":"五言律诗","c":["自从团扇弃，空复掩梁尘。","寒影收云叶，清光暗月轮。","谁怜班氏女，薄命汉宫人。","但使缄兰笥，君情会更新。"]},{"t":"元夜","f":"五言律诗","c":["公子联镳语，佳人把袂欢。","星桥云外出，火树雪中看。","夜色开清禁，春酺许从官。","仍闻祠太乙，达曙礼仙坛。"]},{"t":"登省中楼望西山晴雪","f":"五言律诗","c":["忽见西山雪，高楼重倚阑。","数峰城上出，落日署中寒。","佳色繁天㐲，清光切露盘。","小臣操郢曲，愿献圣人看。"]},{"t":"忆弟","f":"五言律诗","c":["新醪杨柳色，不醉欲何如。","蓟北三春雁，山东二弟书。","宦情閒遂浅，人事病全疏。","未拟酬恩去，空令忆旧庐。"]},{"t":"初夏赵氏园亭","f":"五言律诗","c":["独值春风后，幽期此重过。","开樽黄鸟至，高枕绿阴多。","簪绂殊閒事，乾坤一放歌。","淹留君莫厌，吾道本岩阿。"]},{"t":"送孟得之","f":"五言律诗","c":["十载蓟门客，秋风见长年。","思家明月夜，驱马白云天。","来雁授衣后，黄花落帽前。","何人过携酒，共醉黎阳川。"]},{"t":"登省中楼","f":"五言律诗","c":["萧瑟赋悲哉，西山爽气开。","白云海色断，落日秋阴来。","砧高长乐苑，雁下华阳台。","如何此时望，客思转难裁。"]},{"t":"酬徐员外舟中新咏见示","f":"五言律诗","c":["何处逢摇落，秋风又别家。","天清鸿雁影，江满荻芦花。","明月留仙佩，寒星犯客槎。","到来开箧笥，新句动京华。"]},{"t":"送诸光禄还于越","f":"五言律诗","c":["几年东省月，坐忆故园游。","忽有缄书至，兰亭褉事脩。","芙蓉天镜晓，风雨石帆秋。","到夜应逢雪，门多乘兴舟。"]},{"t":"长陵","f":"楚辞体","c":["明禋趋岁序，陟降俨昭回。","容物中原在，乾坤北极开。","松楸千骑入，风雨百灵来。","共话犁庭役，遗兮重可哀。"]},{"t":"朝陵夜作","f":"五言律诗","c":["上陵无不美，秋杪更宜看。","风雨朝佳气，旌旗拥汉官。","星流千嶂过，月出万松寒。","倚马清钟外，新霜满玉鞍。"]},{"t":"白雪楼","f":"五言律诗","c":["诸郎难得意，非是敢沈冥。","拙宦无同病，清时有独醒。","千家寒雨白，双阙晓烟青。","又值高楼雁，寥寥不可听。"]},{"t":"送杨子正还济南","f":"五言律诗","c":["我家白云渚，落日掩孤城。","读书草堂上，濯缨湖水清。","古来失意事，不独名未成。","北风敝裘雪，谁见弃濡情。"]},{"t":"重送杨生","f":"五言律诗","c":["十年湖上别，风雪此相亲。","把酒论时事，沾衣向故人。","浮名青岁换，生计白云贫。","但去卧芳草，山中鸿雁春。"]},{"t":"殿卿至","f":"五言律诗","c":["骏马何当出，金高郭隗台。","云中春酒熟，书后故人来。","白首文章事，青云王伯才。","谁为一知己，念子正悠哉。"]},{"t":"送殿卿","f":"五言律诗","c":["嗟君复失意，吾道转堪疑。","白雪论先达，青云合后时。","落花寒食过，载酒故山期。","莫以杨朱泪，春风洒路岐。"]},{"t":"章行人使潞藩","f":"五言律诗","c":["使者持符下，风尘叱驭前。","诸侯城赤狄，列嶂党青天。","牟麦祈年畤，芙蓉避暑筵。","相逢多爱客，共赋远游篇。"]},{"t":"十六夜集刘子成宅","f":"五言律诗","c":["羽书三十度，飞骑动长安。","今夜樽前月，还同燧火看。","入门清影满，久坐素华寒。","何处关山引，如悲行路难。"]},{"t":"闻砧","f":"五言律诗","c":["永夜卢家妇，深闺坐自伤。","拭砧散明月，投杵上清霜。","别恨繁鸳绮，哀音急雁行。","同袍征战尽，刀尺断人肠。"]},{"t":"送张比部募兵秦晋诸郡","f":"五言律诗","c":["天威严灭敌，使者出秋官。","白羽徵兵入，黄金结士欢。","风云千骑动，雨雪二陵寒。","无易行间客，能登汉将坛。"]},{"t":"送沈郎中守顺庆","f":"五言律诗","c":["见说褰帷处，千山拥使君。","嘉陵渡春水，栈道转秋云。","郡下平蛮檄，家传谕蜀文。","病馀饶卧理，能不忆离群。"]},{"t":"春日韦氏园亭同元美赋 其一","f":"五言律诗","c":["春坞花冥冥，斜阳倒玉瓶。","风尘犹傲吏，天地此空亭。","共醉蓟云白，相看燕草青。","我来吟泽畔，不是独为醒。"]},{"t":"春日韦氏园亭同元美赋 其二","f":"五言律诗","c":["藉草到流水，看花延落晖。","客中过寒食，马上改春衣。","移席青山出，开樽白鸟飞。","天涯有朋好，能使宦情微。"]},{"t":"夏日同元美徐子旋贾守准刘子成集张氏园亭得谈字","f":"五言律诗","c":["共载杯中物，聊停尘外骖。","路人终白眼，世事岂清谈。","高枕夏云出，空亭斜照含。","竹间有流水，可以漱馀酣。"]},{"t":"初夏同元美汪伯阳皇甫子循集姚明府园亭得春字","f":"五言律诗","c":["五柳陶潜宅，犹藏杜曲春。","绿阴衣上满，黄鸟席边新。","河朔当年事，风流我辈人。","胡为日车马，扰扰向红尘。"]},{"t":"送蔡少府之阳武","f":"五言律诗","c":["君归寒食后，犹及县中花。","趋府具茨野，鸣鞭博浪沙。","大河秋色外，使者白云槎。","岂不劳行役，风尘见岁华。"]},{"t":"为殿卿悼亡","f":"五言律诗","c":["歌梁尘未断，舞袖影方閒。","落月窥珠镜，青春暗玉颜。","为云归峡里，窃药去人间。","安得招䰟术，姗姗步幄还。"]},{"t":"答殿卿","f":"五言律诗","c":["故园春草后，书札问同袍。","海岳游当壮，风尘卧正高。","大名诗里出，浮世酒中逃。","顾我仍多病，时危小吏劳。"]},{"t":"送获嘉郭明府","f":"五言律诗","c":["仙舟新出宰，秋色渡淇河。","官属诸侯贵，君才百里多。","政齐吴季重，地接卫朝歌。","汉主忧南服，长缨送尉佗。"]},{"t":"霅溪徐山人 其一","f":"五言律诗","c":["风尘馀鬓发，天地此栖迟。","不问家人产，宁求国士知。","门无荷蒉过，邻有灌园期。","得道凭乌几，藏名号鹿皮。"]},{"t":"霅溪徐山人 其二","f":"五言律诗","c":["自有浮云恋，非因倦鸟还。","林光清客梦，湖色驻人颜。","岁序高悬榻，风尘老抱关。","不投明月璧，甘隐大雷山。"]},{"t":"毛刺史姑蔑高斋","f":"五言律诗","c":["武陵看花处，二仲得相闻。","雨白闽天合，山青越徼分。","书声散秋瀑，翰墨染春云。","府檄何年事，犹馀猿鹤群。"]},{"t":"出郭","f":"五言律诗","c":["出郭随吾适，人家杜曲边。","溪流萦去马，山路入鸣蝉。","禾黍殷秋作，茅茨足昼眠。","可能祛物役，归买汶阳田。"]},{"t":"张氏园亭","f":"五言律诗","c":["辟疆开别业，载酒雨中看。","亭敞千花瞑，楼空万竹寒。","呼童携枕簟，劝客解衣冠。","宿我山窗下，听诗坐夜阑。"]},{"t":"碧云寺禅房","f":"五言律诗","c":["佛土秋逾净，花台夜复香。","一灯醒梦幻，孤磬散清凉。","月上梵轮满，湖开天镜光。","新诗分妙偈，病客对空王。"]},{"t":"早春元美公实访茂秦华严精舍同赋","f":"五言律诗","c":["招提多病客，拥褐世间情。","法自传灯得，诗先卓锡成。","年光云树丽，春昼雨花明。","若许东林住，还携漉酒生。"]},{"t":"十四夜同王徐宗梁四君子集灵济宫 其一","f":"五言律诗","c":["爱此壶中约，人皆曼倩才。","华灯悬日月，仙树接蓬莱。","青鸟衔诗去，金貂换酒回。","明宵祠太乙，方士汉宫来。"]},{"t":"十四夜同王徐宗梁四君子集灵济宫 其二","f":"五言律诗","c":["逍遥玄圃望，清切紫微层。","月出三山树，春回万井灯。","无悲田变海，但愿酒为渑。","门外金羁影，王孙自五陵。"]},{"t":"张山人","f":"五言律诗","c":["吾乡张仲蔚，未是蓬蒿人。","伏腊东篱下，渔樵北海滨。","官家还赋役，客路且风尘。","织妾齐纨素，开筵娇上春。"]},{"t":"春日","f":"五言律诗","c":["为客淹归骑，思家过断鸿。","春衣花发后，寒食雨声中。","生事羞人问，时名与众同。","自甘郎署隐，不哭宦途穷。"]},{"t":"柬公实","f":"五言律诗","c":["如何梅发后，更忆故园春。","海上多归梦，天涯一病人。","世情元惨淡，宦迹好逡巡。","莫作鸿冥客，青云未可亲。"]},{"t":"同元美与诸比部早夏城南放舟 其一","f":"五言律诗","c":["岂悟风尘客，还能汗漫游。","天涯唯短发，海内此扁舟。","宦迹清时劣，人才画省优。","百年浑绿醑，一日且沧洲。"]},{"t":"同元美与诸比部早夏城南放舟 其二","f":"五言律诗","c":["最怜行役久，为乐未言疲。","自起投车辖，长歌覆羽卮。","江湖青雀舫，僚友白云司。","醒后惊相问，佯狂信有之。"]},{"t":"同元美与诸比部早夏城南放舟 其三","f":"五言律诗","c":["谁为河朔饮，吾愿罄交驩。","杯动沧波色，舟空白日寒。","题诗溪鸟过，岸帻野人看。","不是江湖兴，风尘此道难。"]},{"t":"同元美与诸比部早夏城南放舟 其四","f":"五言律诗","c":["落日维舟好，君其问水滨。","举觞遥送鸟，倚树醉看人。","各负诗无敌，翻惊会有神。","明朝在城郭，骑马共风尘。"]},{"t":"同元美与诸比部早夏城南放舟 其五","f":"五言律诗","c":["春归兴不孤，胜地此相呼。","公等称词伯，余将混酒徒。","山光含浩荡，秋意飒江湖。","乐事关穷达，浮生敢自诬。"]},{"t":"同元美与诸比部早夏城南放舟 其六","f":"五言律诗","c":["言寻韦杜曲，与客放船行。","树影含衣动，溪光逼酒清。","狂来出真态，醉里见浮生。","所以山公后，寥寥达者名。"]},{"t":"寄茂秦","f":"五言律诗","c":["向来燕市饮，此意独飞扬。","把袂看人过，论诗到尔长。","世情摇白首，吾道指沧浪。","去住俱贫病，风尘动渺茫。"]},{"t":"再游南溪同应驾部徐比部赋 其一","f":"五言律诗","c":["此日南溪约，应徐赋客同。","据床千竹下，进艇百花中。","天入华阳馆，云生碣石宫。","昔贤何惨淡，吾醉任鸿濛。"]},{"t":"再游南溪同应驾部徐比部赋 其二","f":"五言律诗","c":["覆席花如待，窥帘鸟似知。","到来拚共醉，坐久见吾诗。","吏迹江湖傲，仙才日月欺。","幸逢休浣出，不顾尚书期。"]},{"t":"再游南溪同应驾部徐比部赋 其三","f":"五言律诗","c":["晏游无俗吏，休沐有殊恩。","碧草堪同藉，红尘可重论。","溪声留倚仗，山色取当樽。","夙昔疑吾醉，维舟尚在门。"]},{"t":"再游南溪同应驾部徐比部赋 其四","f":"五言律诗","c":["花鸟从春过，嬉游到夏偏。","白云行酒上，清吹起舟前。","世路身何得，吾徒赋必传。","宁须千日醉，不拟众人怜。"]},{"t":"郊行 其一","f":"五言律诗","c":["稍似武陵溪，人家绿树迷。","桔槔茅屋上，荷蓧蓟门西。","清吹生衣袂，繁阴散马蹄。","红尘才只尺，城郭意多暌。"]},{"t":"郊行 其二","f":"五言律诗","c":["并马未央前，看云过灞川。","时逢黄鸟住，欲就绿阴眠。","宦岂登临拙，名非案牍传。","风尘朋好在，回首汶阳田。"]},{"t":"柬元美 其一","f":"五言律诗","c":["偃蹇宁知病，今如药裹何。","清斋山雨至，高枕夏云多。","词赋芳颜妒，风尘壮志过。","相怜谁最久，把臂此蹉跎。"]},{"t":"柬元美 其二","f":"五言律诗","c":["久矣疲朝谒，深惟傲吏情。","临风看玉树，消渴望金茎。","返照虹霓出，浮云驷马行。","惭无枚叔赋，起尔蓟门城。"]},{"t":"夜过元美 其一","f":"五言律诗","c":["眼厎谁同病，天涯好自亲。","放歌依白日，纵饮向风尘。","世态摇知己，时名走众人。","朝参君莫懒，汉主忆词臣。"]},{"t":"夜过元美 其二","f":"五言律诗","c":["病即科头出，狂仍枕腹眠。","礼非因我设，污不受人怜。","兴尽衔杯外，言深把烛前。","开门看堕月，骑马问朝天。"]},{"t":"夏日同元美子与子相天宁寺送别公实 其一","f":"五言律诗","c":["晏坐人天近，清斋僧夏深。","出门成远道，驻马向祗林。","益愧风尘色，相看湖海心。","惠休能怨别，为拟碧云吟。"]},{"t":"夏日同元美子与子相天宁寺送别公实 其二","f":"五言律诗","c":["西域黄金地，南讹大火天。","赠言回白雪，寒色动青莲。","幻迹抽簪外，浮名把袂前。","古今皆涕泪，去住各风烟。"]},{"t":"夏日同元美子与集子相宅","f":"五言律诗","c":["佳客堪常见，幽期暑亦过。","披襟度风雨，把酒出星河。","懒拙元相藉，文章敢自多。","夜深忘白羽，玉树倚蹉跎。"]},{"t":"柬子相 其一","f":"五言律诗","c":["已负西山约，将无惜壮游。","怀人当落日，卧病复清秋。","时事君高枕，风尘我敝裘。","加餐看物理，天地一虚舟。"]},{"t":"柬子相 其二","f":"五言律诗","c":["楚客秋多病，羁心私自怜。","各天散朋好，八月见烽烟。","白露寒砧下，青枫过雁前。","岂应裁恨赋，写任故人传。"]},{"t":"别汪正叔员外","f":"五言律诗","c":["几年金虎署，与尔结交欢。","傲吏庄生似，诗家鲍叔看。","春光燕树合，雨色蓟门寒。","各抆临岐泪，风尘去住难。"]},{"t":"怀魏顺甫","f":"五言律诗","c":["白云同署客，相念意悠哉。","交道萧朱失，文章屈宋来。","风尘还傲吏，案牍岂时才。","不见黄金骏，秋高蓟北台。"]},{"t":"登黄榆马陵诸山是太行绝顶处 其一","f":"五言律诗","c":["黄榆高不极，临眺亦奇哉。","河势中原坼，山形上党来。","白云横塞断，寒峡倚天开。","摇落清秋色，多惭作赋才。"]},{"t":"登黄榆马陵诸山是太行绝顶处 其二","f":"五言律诗","c":["不尽寒云外，青峰落照多。","秋阴生大卤，木叶下滹沱。","巨壑藏风雨，飞梁挂薜萝。","重关三辅地，跃马意如何。"]},{"t":"登黄榆马陵诸山是太行绝顶处 其三","f":"五言律诗","c":["振衣岩木下，倚杖白云层。","落日悬狐塞，清秋度马陵。","千峰寒自出，大泽莽相仍。","左瞰邢襄郡，分符忆股肱。"]},{"t":"登黄榆马陵诸山是太行绝顶处 其四","f":"五言律诗","c":["秋色自冥冥，风烟接井陉。","关门开落日，山路出寒星。","太守方乘障，清时敢勒铭。","杉松回朔气，哀壑未堪听。"]},{"t":"答明卿病后见寄 其一","f":"五言律诗","c":["蓟门摇落后，楚客病如何。","秋色高金掌，西风满玉珂。","开樽鸿雁至，染翰五云过。","应忆山阳会，疏狂阮籍多。"]},{"t":"答明卿病后见寄 其二","f":"五言律诗","c":["吴生何偃蹇，称病不朝天。","侍从官非拙，浮沉世所怜。","黄金燕士里，白雪郢人前。","自识衔杯趣，逾看结袜贤。"]},{"t":"寄元美 其一","f":"五言律诗","c":["宿昔神仙省，青云向尔亲。","偿金聊玩世，抱玉故调人。","气色高题柱，文章老斲轮。","别来多所忆，卧病上林春。"]},{"t":"寄元美 其二","f":"五言律诗","c":["岂不为同舍，于时愧重名。","佳人谁独立，大将尔横行。","病起高诗兴，春光美宦情。","悬知思远道，落日蓟门城。"]},{"t":"即事 其一","f":"五言律诗","c":["浮云如浪迹，春色且邢州。","磬折人堪老，萧条客自愁。","孤城山下出，大陆日西流。","请郡终何意，风尘复倦游。"]},{"t":"即事 其二","f":"五言律诗","c":["天涯看薄宦，何以异漂蓬。","才岂分符后，名非荐疏中。","黄尘霾落日，白羽插春风。","闻道渔阳战，方论卫霍功。"]},{"t":"即事 其三","f":"五言律诗","c":["懒嫚终疑傲，和光意远哉。","元龙无客礼，方朔有仙才。","疾苦褰帷过，风尘领郡来。","那须论往事，作赋柏梁台。"]},{"t":"即事 其四","f":"五言律诗","c":["使者殊旁午，吾生自不辰。","文章看长物，道路竟何人。","寒食孤城外，襜帷大泽滨。","那堪杨柳色，风雨傍行春。"]},{"t":"寄宗考功 其一","f":"五言律诗","c":["别离如昨日，岂厌广陵涛。","春色渔阳满，烽烟海上高。","文章回白雪，顾盻解绨袍。","下走犹三辅，萧条欲二毛。"]},{"t":"寄宗考功 其二","f":"五言律诗","c":["春色还堪起，青云固可披。","振缨人不病，把袂客能诗。","奏事明光殿，抡才藻镜司。","稽康犹自懒，早辱巨源知。"]},{"t":"寄殿卿 其一","f":"五言律诗","c":["人情原惨淡，世路故蹉跎。","意气弹冠少，风尘按剑多。","客居深雨雪，春梦远漳河。","赖有西山色，犹堪载酒过。"]},{"t":"寄殿卿 其二","f":"五言律诗","c":["燕山为客地，莫共酒人居。","吾辈诗名大，其徒剑术疏。","风尘官不调，雨雪岁将除。","何限东归意，春花满旧庐。"]},{"t":"春兴 其一","f":"五言律诗","c":["短发黄尘里，浮生白日徂。","诗名堪自见，经术敢相诬。","荐列终才吏，逢迎岂壮图。","有年轻召杜，不病足江湖。"]},{"t":"春兴 其二","f":"五言律诗","c":["案牍将能事，文章敢具陈。","跳梁看此物，隐几过时人。","返照生残雨，浮云矫上春。","夙心唯病免，不欲滞风尘。"]},{"t":"重送许永宁 其一","f":"五言律诗","c":["绝域天应断，扬波海未平。","浮云随薄宦，华发系微名。","传檄西南定，褰帷瘴疠清。","看君饶卧理，经术晚逾成。"]},{"t":"重送许永宁 其二","f":"五言律诗","c":["世情今可见，此谪竟堪陈。","偃蹇难容汝，文章不利人。","清秋炎海外，落日大荒滨。","莫更埋铜柱，功名老汉臣。"]},{"t":"郡斋送张肖甫 其一","f":"五言律诗","c":["蓟门相忆处，岂不问加餐。","卧理非吾意，诗名向尔看。","白云尊酒尽，山色郡斋寒。","莫惜重投辖，秋风道路难。"]},{"t":"郡斋送张肖甫 其二","f":"五言律诗","c":["送君何所有，城上太行山。","落日堪相忆，浮云未可攀。","俱言张翰去，得御李膺还。","莫自悲秋色，能摧壮士颜。"]},{"t":"阁夜示茂秦 其一","f":"五言律诗","c":["相逢殊不恶，久别竟谁驩。","贫病他乡老，交游古道难。","开樽山欲出，说剑雪逾寒。","如此萧条色，高斋尔自看。"]},{"t":"阁夜示茂秦 其二","f":"五言律诗","c":["为客今犹在，浮名信已劳。","病来衰綵笔，老至恋绨袍。","阁卧风尘过，衔杯夜色高。","旧知江夏守，不厌祢生豪。"]},{"t":"阁夜示茂秦 其三","f":"五言律诗","c":["病起看时事，归心不可裁。","著书官欲罢，问字客还来。","月出樽堪满，霜清角自哀。","相怜成白首，明日阻三台。"]},{"t":"阁夜示茂秦 其四","f":"五言律诗","c":["把袂今何夕，高斋雨雪清。","诗才君矍铄，酒兴我从横。","同病无交态，相依岂世情。","春来徵渤海，陈对引王生。"]},{"t":"寄元美 其一","f":"五言律诗","c":["我昔朝宗日，君停使者轩。","并驱皆上驷，相遇复中原。","草昧时人起，风尘国士恩。","别来春色满，无处不销䰟。"]},{"t":"寄元美 其二","f":"五言律诗","c":["若问除书意，君何异积薪。","姓名常借客，踪迹竟疑人。","为郡空高第，当朝各要津。","拂衣吾所欲，不是避风尘。"]},{"t":"寄元美 其三","f":"五言律诗","c":["渔阳春欲尽，汉使未堪愁。","边郡多豪侠，风尘一壮游。","浮云寒大漠，白日澹幽州。","莫更观辽海，萧条正北流。"]},{"t":"寄元美 其四","f":"五言律诗","c":["何悟淹为郡，风尘日以难。","宦情疏自解，人事拙相看。","高枕西山色，清斋大麓寒。","期君秋月满，从此挂吾冠。"]},{"t":"夏日行部遇明卿子与于瘿陶邑","f":"五言律诗","c":["何来漳水上，早晚发长安。","放逐吾曹在，风尘此道难。","孤城高自卧，万事醉相看。","莫击邹阳剑，霜飞五月寒。"]},{"t":"郡斋与元美赋","f":"五言律诗","c":["握手今何在，高斋共此樽。","众人方睥睨，二子向乾坤。","经术从吾浅，诗名得尔尊。","当时杨马辈，谁复在金门。"]},{"t":"送元美 其一","f":"五言律诗","c":["吾曹天地在，不惜滞风尘。","意气能无合，文章自有真。","齐名他日事，侧目此时人。","为别还秋色，樽前白发新。"]},{"t":"送元美 其二","f":"五言律诗","c":["把酒论离索，褰帷送友生。","白云高大麓，秋色重孤城。","偃蹇还诗句，萧条自世情。","赠君无赵璧，落日片心明。"]},{"t":"黄河","f":"五言律诗","c":["复就三秦役，还为四牡歌。","北风扬片席，大雪渡黄河。","才岂诸郎少，名非一郡多。","儒官明主意，吾道好蹉跎。"]},{"t":"关门雪望","f":"五言律诗","c":["西来千里雪，斜日满函关。","秋水何当落，浮云自不还。","积阴高紫气，寒色壮秦山。","似欲欺双鬓，苍茫到客颜。"]},{"t":"发长安","f":"五言律诗","c":["此处看春色，萧条客自禁。","风尘为郡过，踪迹抱关深。","不尽传经意，难言作赋心。","故人多道路，薄宦有登临。"]},{"t":"泾州","f":"五言律诗","c":["回磴层云上，孤城返照间。","人烟趋白阪，睥睨走青山。","刍粟浮泾下，旌旗度陇还。","时看乘障吏，车马出萧关。"]},{"t":"秋日 其一","f":"五言律诗","c":["薄游寒暑换，仍自滞孤城。","华发看人事，浮云识宦情。","拂衣驱病色，悬榻避时名。","但欲眠清昼，相嘲任友生。"]},{"t":"秋日 其二","f":"五言律诗","c":["此物还堪惜，何官不可休。","驱驰如昨日，药饵更清秋。","名已千人废，家徒四壁愁。","南山归自好，沮溺本同流。"]},{"t":"秋日 其三","f":"五言律诗","c":["倦游非一日，乘兴复三秦。","多病难为客，浮名喜中人。","未堪沈案牍，何以走风尘。","祖帐东门外，贤哉一老臣。"]},{"t":"秋日 其四","f":"五言律诗","c":["还乡明日事，可奈簿书劳。","弃置看同病，风尘避二毛。","酒如泾水浊，枕对华山高。","不是清秋色，何人见反骚。"]},{"t":"五日和许傅湖亭宴集 其一","f":"五言律诗","c":["城头片雨悬，客醉㟙湖边。","酒奈榴花妒，人堪桂树怜。","五丝还令节，双鬓抵流年。","莫蹋王孙草，淮南赋已传。"]},{"t":"五日和许傅湖亭宴集 其二","f":"五言律诗","c":["青樽临北渚，一为故人开。","此事成今昔，浮云自往来。","花间携枕簟，镜里出楼台。","忽就投湘赋，深知贾谊才。"]},{"t":"寄元美","f":"五言律诗","c":["寥落文章事，相逢白首新。","微吾竟长夜，念尔和阳春。","把酒千门雪，论交四海人。","即今燕市里，击筑好谁亲。"]},{"t":"赠子与","f":"五言律诗","c":["握手论文者，春来限各天。","即今行乐处，不似旧游年。","神物风尘里，时名我辈前。","岂令徐孺榻，白日此长悬。"]},{"t":"汪员外移水部时城京师汪为植","f":"五言律诗","c":["闻有金城役，抡兹水部才。","中原忧被发，使者咏于䰄。","睥睨燕山接，风云瀚海来。","悬知胡骑遁，天子宴蓬莱。"]},{"t":"即事 其一","f":"五言律诗","c":["羽书秋色外，飞挽海陵回。","日上犁庭议，时难度漠才。","物情奇士过，天造异人来。","侧席劳明主，黄金正满台。"]},{"t":"即事 其二","f":"五言律诗","c":["即今难授钺，谁可静胡尘。","谈笑存能事，艰虞失众人。","大军归掌握，王者自经纶。","不复忧骄悍，如林护北辰。"]},{"t":"即事 其三","f":"五言律诗","c":["使者晨驰壁，夺归平虏章。","自天悬斧钺，择日设坛场。","万马中原集，诸军上苑旁。","主恩无可报，一战取名王。"]},{"t":"即事 其四","f":"五言律诗","c":["天子何神武，乘秋欲破胡。","儒臣擐甲胄，大将解兵符。","叱咤风云合，艰危日月扶。","北瞻陵寝色，葱郁近皇都。"]},{"t":"广阳山道中","f":"五言律诗","c":["出峡还何地，杉松郁不开。","雷声千嶂落，雨色万峰来。","地胜纡王事，年饥损吏才。","难将忧旱意，涕泣向蒿莱。"]},{"t":"赵州道中","f":"五言律诗","c":["独往何为者，栖栖意不欢。","褰帷秋雨过，伏轼夏云残。","潦水阴相积，蒹葭晚自寒。","大夫方跋涉，天步属艰难。"]},{"t":"吴舍人丧内 其一","f":"五言律诗","c":["楚妃色殊众，不独下堂悲。","鼓瑟潇湘夜，秋云未可持。","河流双露掌，月出万年枝。","属有将雏曲，能无泣凤池。"]},{"t":"吴舍人丧内 其二","f":"五言律诗","c":["可怜御沟水，见此白头吟。","病客思江郡，词臣在上林。","春风动花树，秋月散清砧。","唯有陵阳泪，知君抱玉心。"]},{"t":"和殿卿白云亭醉歌","f":"五言律诗","c":["狂杀王门客，空亭日啸歌。","那知珠履散，自爱白云多。","短发明秋水，长裾曳芰荷。","独怜枚叟在，不复厌婆娑。"]},{"t":"元美以家难羁京作此为唁 其一","f":"五言律诗","c":["驰骋淄渑日，功名与宦情。","高堂一为坐，世路遂相轻。","行乞还燕市，悲歌复蓟城。","佩刀风雨夜，堪作箾中鸣。"]},{"t":"元美以家难羁京作此为唁 其二","f":"五言律诗","c":["一自抽簪后，漂零见此身。","通章寻悟主，怀刺更依人。","寒入绨袍色，愁生黍谷春。","不因家难剧，君岂在风尘。"]},{"t":"元美以家难羁京作此为唁 其三","f":"五言律诗","c":["海内论兄弟，萧条二子才。","一时称病罢，万里拂衣来。","雨雪人高卧，蓬蒿客自回。","偶然占剑气，夜夜向燕台。"]},{"t":"元美以家难羁京作此为唁 其四","f":"五言律诗","c":["闻道周旋地，偏承老父颜。","橐饘时在侧，宾客稍居閒。","函谷更封出，夷门执辔还。","莫将公子泪，乱漫洒燕山。"]},{"t":"春日闲居 其一","f":"五言律诗","c":["即令关请谒，何用乞江湖。","僻性终难狎，浮名本易污。","杜门人事过，欹枕岁华徂。","薄俗还堪畏，崎岖比宦途。"]},{"t":"春日闲居 其二","f":"五言律诗","c":["白日移高枕，青山答放歌。","病才宜偃蹇，老自厌婆娑。","礼数诸生绝，交游二仲多。","江湖春正满，更欲混渔蓑。"]},{"t":"春日闲居 其三","f":"五言律诗","c":["药饵休官懒，蓬高谢客深。","浊醪殊解事，高枕自知音。","老大翻陵劲，文章岂陆沈。","浮云终日在，潇洒竟何心。"]},{"t":"春日闲居 其四","f":"五言律诗","c":["五羖功名薄，双龙羽翼乖。","风尘凋短褐，雨雪闭高斋。","惨淡幽人色，飞扬壮士怀。","少年何太苦，妖冶事形骸。"]},{"t":"春日闲居 其五","f":"五言律诗","c":["奉使谈经日，单车西入关。","抡才牛口下，得士凤毛间。","白雪千人失，黄河万里还。","即今高卧处，犹不减商山。"]},{"t":"春日闲居 其六","f":"五言律诗","c":["乞归君已见，削迹我何求。","交态疏能变，时名久自休。","中原来病色，万里入春愁。","不是忘机客，还惊海上鸥。"]},{"t":"春日闲居 其七","f":"五言律诗","c":["结舌论文地，甘心养拙年。","朱门人自老，白雪调空传。","世路蓬蒿外，浮名燕雀前。","中原二三子，夙昔共周旋。"]},{"t":"春日闲居 其八","f":"五言律诗","c":["病起独登台，春光万里来。","浮沉还我辈，俯仰见人才。","华发风尘过，青山雨雪开。","浮云堪倚杖，落日好衔杯。"]},{"t":"春日闲居 其九","f":"五言律诗","c":["漂零唯浊酒，落拓总狂生。","彭泽差闻道，高阳横得名。","罢来诗惨淡，卧久兴凄清。","日对春湖色，潺湲懒濯缨。"]},{"t":"春日闲居 其十","f":"五言律诗","c":["五柳㟙湖滨，先生隐是真。","文章堪侧目，潦倒竟全身。","何必论交地，长须纵酒人。","即令东蹈海，断不混风尘。"]},{"t":"夏日东村卧病 其一","f":"五言律诗","c":["平生偏伏枕，睱日是抽簪。","病著青山色，愁高白雪音。","云霄悬出处，踪迹间浮沉。","不必名俱毁，方知二仲心。"]},{"t":"夏日东村卧病 其二","f":"五言律诗","c":["放歌知帝力，纵饮见天真。","綵笔风云老，青樽日月新。","诗惊啖蔗客，酒让采薇人。","即使妨幽事，何须傍隐沦。"]},{"t":"夏日东村卧病 其三","f":"五言律诗","c":["自甘成独往，谁复病相怜。","金尽论交地，囊馀解摈篇。","清斋芳药饵，华发媚林泉。","不必忧生事，深耕种秫田。"]},{"t":"夏日东村卧病 其四","f":"五言律诗","c":["不谓幽栖处，还堪抱膝吟。","大云千里驻，片雨二湖阴。","暑逼藤萝浅，凉生栝柏深。","鲍山终日在，知己愧黄金。"]},{"t":"夏日东村卧病 其五","f":"五言律诗","c":["未同疏雨至，勿剪夏云繁。","片华樽前出，双流树杪翻。","红颜辞上国，白眼入中原。","慢世吾何敢，风尘且避喧。"]},{"t":"夏日东村卧病 其六","f":"五言律诗","c":["拂衣先达怪，高枕故人疑。","世路衡门左，轩车负郭迟。","少年誇解事，薄俗讳言诗。","何处堪遥集，悠悠未有期。"]},{"t":"夏日东村卧病 其七","f":"五言律诗","c":["每逢河朔饮，辄忆广陵涛。","起色含佳句，流光逼浊醪。","兴缘知己尽，名岂罢官高。","髀肉看如此，何论长二毛。"]},{"t":"夏日东村卧病 其八","f":"五言律诗","c":["空林风雨过，潇洒一樽开。","看竹俄蠲疾，漂蓬敢负才。","杜门辞问字，落日罢登台。","不是怜嵇阮，谁堪把臂来。"]},{"t":"夏日东村卧病 其九","f":"五言律诗","c":["夜半忽风雨，层楼四望孤。","雷盘华不注，电划大明湖。","云雾连屏叠，蛟龙抱剑呼。","飞扬天地意，垂老见吾徒。"]},{"t":"夏日东村卧病 其十","f":"五言律诗","c":["何物子虚赋，深承汉主知。","一逢杨得意，千载遂同时。","谏猎功名薄，为郎日月私。","閒居堪避事，称病足逶迤。"]},{"t":"夏日东村卧病 其十一","f":"五言律诗","c":["更阅人间语，谁堪出处同。","江湖星自客，词赋日犹工。","物色馀争席，生涯见转蓬。","延陵皮相士，竟失被裘翁。"]},{"t":"夏日东村卧病 其十二","f":"五言律诗","c":["白头明日事，君不见交情。","千载论知己，中原命友生。","青云高病色，沧海傍诗名。","一为弹冠误，徒令国士轻。"]},{"t":"秋日村居 其一","f":"五言律诗","c":["隐几怜清晓，开轩命浊醪。","西风行薜荔，白露缀蒲桃。","气逼蝉声苦，天含雁影高。","壮心堪自见，秋色正滔滔。"]},{"t":"秋日村居 其二","f":"五言律诗","c":["病色还相假，秋光溘自开。","清羸堪傍竹，潦倒重衔杯。","返照湖边尽，浮云海上来。","即今知九辩，无处不悲哉。"]},{"t":"秋日村居 其三","f":"五言律诗","c":["秋意长西北，苕荛望里分。","青含仙署雨，白动帝乡云。","屈宋终难达，巢由故不群。","江湖三十载，摇落好谁闻。"]},{"t":"秋日村居 其四","f":"五言律诗","c":["南山伏枕前，北渚濯缨边。","林薄秋逾厉，云霞晓自鲜。","谈诗成白首，把酒望青天。","万里中原色，萧条此地偏。"]},{"t":"秋日村居 其五","f":"五言律诗","c":["不必知名姓，中原一病夫。","柴荆存古色，药饵泥穷途。","落日悬鱼笱，西风缠辘轳。","生涯君自见，百亩白云湖。"]},{"t":"秋日村居 其六","f":"五言律诗","c":["高斋清自掩，遥夕病相看。","片月花间净，明河树杪乾。","流萤含火著，宿鹭抱霜寒。","何限同袍意，江湖坐渺漫。"]},{"t":"秋日村居 其七","f":"五言律诗","c":["白云不摇落，湖上长悠悠。","世事衔杯过，人情把袂休。","秋光栖自老，日色澹相愁。","况复多风雨，萧条傍倚楼。"]},{"t":"秋日村居 其八","f":"五言律诗","c":["摇落唯高枕，风尘且闭关。","醉来双白眼，病起一青山。","交态元难作，诗名已自闲。","有人湖海上，无事马蹄间。"]},{"t":"冬日村居 其一","f":"五言律诗","c":["高卧堪人事，幽栖岂世情。","老松寒更拙，片竹冷逾清。","拥褐江湖色，鸣琴雨雪声。","懒心常近傲，不是学庄生。"]},{"t":"冬日村居 其二","f":"五言律诗","c":["百年长药裹，三径且蓬蒿。","华发抽簪短，青山伏枕高。","漂零知浊酒，雨雪见绨袍。","似解冥鸿意，翻然变羽毛。"]},{"t":"冬日村居 其三","f":"五言律诗","c":["寒邳不可望，萧瑟掩柴扉。","宿雾含霜苦，斜阳带雪微。","清斋宜病色，生事合渔矶。","欲奏沧浪曲，江湖此调稀。"]},{"t":"冬日村居 其四","f":"五言律诗","c":["遥夜怜幽独，南山傍户庭。","泉流霜下白，野色海边青。","风乱将残烧，寒疏欲晓星。","偶因樵唱起，延眺及林坰。"]},{"t":"寄华从龙比以鱼橘见致","f":"五言律诗","c":["多少人间事，谁能便作书。","罢官君更早，谢客我何疏。","八月来吴橘，三江下楚鱼。","因风裁数字，一问子云庐。"]},{"t":"月","f":"五言律诗","c":["不是山中月，谁能坐郁陶。","蟾孤怜冻影，兔老爱霜毫。","晕叠金波动，寒侵玉树高。","为题团扇句，千里寄同袍。"]},{"t":"和殿卿神通寺见贻之作","f":"五言律诗","c":["花宫留妙唱，綵笔遍高僧。","说法从初起，谈诗出上乘。","五言争刻烛，一字了传灯。","玄度前身是，风流益可凭。"]},{"t":"同许右史游南山寺宿天井寺","f":"五言律诗","c":["古寺马蹄前，荒山断复连。","阶危孤石倒，厓响乱泉悬。","乔木堪知午，回峰半隐天。","不因许玄度，谁此得攀缘。"]},{"t":"龙集寺","f":"五言律诗","c":["千林窥壑险，一径入云愁。","峰落青莲色，灯悬白日幽。","香台高枕出，涧水闭门流。","闻道群龙集，明珠自可求。"]},{"t":"锦阳川九塔寺观许右史碑","f":"五言律诗","c":["名山谐夙好，况复近吾庐。","岚影浮斜照，兹川锦不如。","空林双树老，寒塔九华疏。","一片头陀石，新文六代馀。"]},{"t":"元日","f":"五言律诗","c":["五十江湖客，风尘一事违。","渔樵供药饵，雨雪偃荆扉。","白发诗篇苦，清斋病色微。","平生拚纵酒，今日不知非。"]},{"t":"立春前夜斋居殿卿携具见枉","f":"五言律诗","c":["茅斋残雪在，新月况当门。","春动西园盖，寒空北海樽。","诗篇闲自遣，交态老难论。","似觉行厨色，能清病客魂。"]},{"t":"立春日斋居对雪忆元美","f":"五言律诗","c":["斋居何所作，春雪是佳期。","净入年华浅，光含暝色迟。","鸣弦流艳曲，拂简映新诗。","此夕山阴客，扁舟兴可知。"]},{"t":"袭生初度与郭子坤集开元寺饯许右史","f":"五言律诗","c":["论交三十载，此地重寻盟。","夏腊高初度，人天恋远行。","青莲澄笔彩，白马识经声。","曾是春山夜，谈禅对友生。"]},{"t":"逃暑","f":"五言律诗","c":["无处堪逃暑，高楼坐夜分。","河流缠宿雾，电影迸重云。","纨扇含冰彩，珠帘网露文。","汉宫多贵幸，何以荅南熏。"]},{"t":"暴雨","f":"五言律诗","c":["西来氛甚恶，夏至此何祥。","雨伏千厓怒，风回万壑长。","雷声盘暗牖，电影缠空梁。","少选虹霓出，园林媚夕阳。"]},{"t":"寄子与使君 其一","f":"五言律诗","c":["一郡看如此，扁舟意若何。","白云天目遍，春水太湖多。","怪事宁词赋，幽人自薜萝。","平生无俗客，三径许谁过。"]},{"t":"寄子与使君 其二","f":"五言律诗","c":["我辈还堪见，人间已厌闻。","大都常谢客，不次各离群。","病酒仍耽句，青山自白云。","春来论数子，飘泊有如君。"]},{"t":"袭克懋托疾不肯入试赋赠","f":"五言律诗","c":["似得冥鸿意，兼深抱璧情。","一鸣堪自失，三献转相经。","白雪看前辈，青云让后生。","已须横四海，且复爱连城。"]},{"t":"寄怀余德甫 其一","f":"五言律诗","c":["岂亦逢秋色，登临若远行。","江通灌婴井，山到越王城。","何见非交态，难言一宦情。","大东千里月，石镜好同明。"]},{"t":"寄怀余德甫 其二","f":"五言律诗","c":["即闻彭蠡雁，应上武阳台。","华发文章到，青山放逐回。","时名堪下榻，秋兴足衔杯。","不是求羊辈，蓬蒿断往来。"]},{"t":"二月十五日诞子","f":"五言律诗","c":["三十卢家妾，明珠报使君。","国香元有种，天马自超群。","月应悬弧满，春迎剪绂分。","负薪还尔事，岂敢望青云。"]},{"t":"席上别王吴徐宗四子","f":"五言律诗","c":["仙吏满蓬莱，离筵气色开。","襜帷寒食过，风雨太行来。","一失中原遇，难论我辈才。","华阳犹骏马，涓者载金回。"]},{"t":"荅元美喜于鳞被召见寄 其一","f":"五言律诗","c":["十年君所见，已分老蓬蒿。","安得浮名在，将无执事劳。","海鸥群自下，天马步元高。","五柳还须种，徵君不姓陶。"]},{"t":"荅元美喜于鳞被召见寄 其二","f":"五言律诗","c":["那堪成僻性，非不爱明时。","白发终怜我，青山好属谁。","连城高一抱，流水妙相知。","君自墙东客，行藏岂更疑。"]},{"t":"过吕梁","f":"五言律诗","c":["十年称病客，系楫在楼船。","澌下波方溜，风鸣水正悬。","青山高卧里，白发壮游前。","起色聊相假，终惭傲吏贤。"]},{"t":"宦情 其一","f":"五言律诗","c":["初服终能事，徐生已自违。","浮云知失计，沤鸟见忘机。","越酒经春老，江鱼入夏肥。","他乡如不病，一任宦情微。"]},{"t":"宦情 其二","f":"五言律诗","c":["我辈诚何意，于今自解难。","累宁知众嫭，侬已罢新欢。","白雪狂歌尽，青云病疏看。","江湖终日在，一任宦情阑。"]},{"t":"刘太保文安公挽章 其一 赠谥","f":"五言律诗","c":["上公沾异典，美谥表馀恩。","文并三光丽，安同五岳尊。","朝廷先达在，社稷大名存。","庙议当时事，称天有世孙。"]},{"t":"刘太保文安公挽章 其二 谕祭","f":"五言律诗","c":["遣奠烦容物，临轩忆典刑。","祠官开正寝，法从辍明庭。","筵几知存问，钟彝藉宠灵。","老臣如就飨，帷幄见谈经。"]},{"t":"刘太保文安公挽章 其三 赐葬","f":"五言律诗","c":["使从三省至，地自九原开。","不作祁连象，宁知汉代才。","佳城跑踯躅，法驾拥徘徊。","文剑今埋照，于焉烛夜台。"]},{"t":"刘太保文安公挽章 其四 颁诰","f":"五言律诗","c":["国史从王事，经筵饫帝慈。","龙章纡后宠，鱼水见前知。","雨露含天藻，山河勒制辞。","门生堪视草，犹作起家疑。"]},{"t":"刘太保文安公挽章 其五 立碑","f":"五言律诗","c":["岘首羊公石，千秋泪不禁。","孤坟寒自出，华表郁相临。","阴雨龙文动，风霜鸟迹深。","更闻辞妙绝，一字可生金。"]},{"t":"刘太保文安公挽章 其六 遗文","f":"五言律诗","c":["自复遗书出，相传片字工。","史才依晋乘，诗调托唐风。","草疏回天力，谈经发圣聪。","少年眈作赋，颇欲拟河东。"]},{"t":"刘太保文安公挽章 其七 特祠","f":"五言律诗","c":["祠堂何所有，遗像鹿台山。","为是悬车处，常闻曳履还。","诸生从上党，三老自壶关。","伏腊蘋蘩外，谈经俎豆间。"]},{"t":"刘太保文安公挽章 其八 世科","f":"五言律诗","c":["诸刘称令族，群从复清操。","家自驹千里，人皆凤一毛。","文章争左袒，礼乐盛东曹。","五世传经术，推公甲第高。"]},{"t":"刘太保文安公挽章 其九 达尊坊","f":"五言律诗","c":["一时求旧德，千载忆皇都。","北斗高元气，南山永帝图。","青云馀几杖，白首自江湖。","此日乘骢客，闾门意不孤。"]},{"t":"刘太保文安公挽章 其十 从祀乡贤","f":"五言律诗","c":["小子元吾党，前贤亦故乡。","春秋存俎豆，日月望宫墙。","血食堪千载，精灵自一堂。","唯应杨伯起，秦晋郁相望。"]},{"t":"再过子与","f":"五言律诗","c":["浮名难自托，佳会岂相图。","日月高诗社，河山壮酒垆。","岁星时一出，白雪调元孤。","缱绻非为佞，风流不可无。"]},{"t":"送赵户部出守淮阳","f":"七言律诗","c":["仙郎起草汉明光，几载军储事朔方。","五马新为淮海郡，三台旧署度支章。","行车麦秀随春雨，卧阁花深对夕阳。","时忆上林词赋客，鸿书遥下楚云长。"]},{"t":"崔驸马山池燕集得无字","f":"七言律诗","c":["主家池馆帝城隅，上客相如汉大夫。","十里芙蓉迎剑舄，一樽风雨对江湖。","桥边取石鲸飞动，台上吹箫凤有无。","向夕不堪车马散，朱门空锁月明孤。"]},{"t":"送彰德陈使君迎侍浙中","f":"七言律诗","c":["帝里初分郡檄回，便迎青鸟建章台。","东方千骑风云下，南国双帆河岳来。","公子西园池上宴，使君秋宪府中才。","邺天露冕行春日，更许何人托乘陪。"]},{"t":"送郭子坤下第还济南","f":"七言律诗","c":["华省栖迟白发新，因怜失意转怜春。","樽前病起逢寒食，客里花开别故人。","赋就自堪生顾眄，才高岂合老风尘。","燕台郭隗君家事，不拟骅骝不致身。"]},{"t":"送王郎守安庆","f":"七言律诗","c":["花满胡姬春酒楼，使君五马五骅骝。","明光起草推高第，三十专城领上游。","天柱西悬江汉影，海门东控帝王州。","到来纡画思同舍，万里风烟白雁秋。"]},{"t":"送丰城杜少府谪滇南","f":"七言律诗","c":["共惜投荒万里天，当朝起草事空传。","主恩绿鬓神仙尉，客梦青云侍从年。","盘水秋帆开瘴疠，黔阳春树隔风烟。","孤臣自有丰城剑，遥夜思家向斗边。"]},{"t":"酬谷明府见寄","f":"七言律诗","c":["清时词客满公车，独向漂零叹不如。","老去已拚常纵酒，秋来何意为裁书。","薄游更自淹华省，多病惟堪返敝庐。","共道子云长笔札，知君近日五侯疏。"]},{"t":"秋前一日同元美茂秦吴峻伯徐汝思集城南楼","f":"七言律诗","c":["万里银河接御沟，千门夜色映南楼。","城头客醉燕山月，笛里寒生蓟北秋。","胡地帛书鸿雁动，汉宫纨扇婕妤愁。","西风明日吹双鬓，且逐飞蓬赋远游。"]},{"t":"送孙郎中守承天","f":"七言律诗","c":["郁葱佳气汉江边，今上龙飞北极年。","过幸沛宫三日饮，裁留郢曲大风篇。","仙郎珂散蓬莱月，太守帷开橘柚天。","明到为存汤沐邑，须知父老借才贤。"]},{"t":"刘员外家宸翰楼","f":"七言律诗","c":["君家司寇此楼居，奕叶承恩片帖馀。","帝自经筵传翰墨，人从册府见图书。","烟云绕槛生春色，牛斗开函散楚墟。","弦诵只今诸弟满，韦贤相业好谁如。"]},{"t":"送刘员外使黔中","f":"七言律诗","c":["牂牁万里越王台，北眺中原秋色来。","江嶂忽分三楚断，海天不尽百蛮开。","白云使者乘轺过，金马祠官拥节回。","为泛昆明誇上苑，令知汉主自雄才。"]},{"t":"送大司寇之金陵","f":"七言律诗","c":["闻道铜标护百蛮，当朝共拟伏波还。","来持滇海中丞节，入领西曹法从班。","曳履春云高北斗，迥车秋色照钟山。","顾期门客江城满，草奏时时达汉关。"]},{"t":"送瑞安刘明府","f":"七言律诗","c":["刘桢词赋不群才，百里新承汉宠回。","吴地青山飞舄下，大江秋雨挂帆来。","白云堪赠神明宰，海色遥临睥睨开。","到日自逢花满县，更怜春树接天台。"]},{"t":"送许元复还姑苏","f":"七言律诗","c":["蓟门鸿雁满高秋，张翰思家罢远游。","入洛故人名下士，度江寒梦雨边舟。","客来白发谁相忆，赋就黄花不可留。","兴发鲈鱼堪自钓，吴枫摇落未须愁。"]},{"t":"与茂秦金山寺亭上望西湖","f":"七言律诗","c":["孤亭遥上翠微重，槛外空林何处钟。","秋到诸天开薝卜，湖连双阙散芙蓉。","云光忽落鼋鼍窟，雨色飞来鸑鷟峰。","自信登临能作赋，肯令陶谢不相从。"]},{"t":"送汪伯阳出守庆阳","f":"七言律诗","c":["中原万骑却胡兵，客领铜符塞上行。","大漠清秋迷陇树，黄河落日见秦城。","邠人自美西羌俗，汉守谁高北地名。","郡吏可能无荐达，还令介子乞长缨。"]},{"t":"送黄侍御按滇中","f":"七言律诗","c":["去矣乘风瘴疠开，西南万里壮游哉。","登台越巂山形合，揽辔昆明秋色来。","周礼职方天外尽，汉臣封事日边回。","征蛮幕府今凋落，安得楼船下濑才。"]},{"t":"送包大中长芦知事","f":"七言律诗","c":["九河水流何溅溅，君去春花车马前。","入幕官僚清宴久，挥毫渤海白云天。","相将牛酒劳从事，未少鱼盐给俸钱。","此去陆沉无不可，于今蓟北静烽烟。"]},{"t":"除夕","f":"七言律诗","c":["几年仙省白云间，此夕归心醉里閒。","九塞烽烟连北极，千门雪色照西山。","还知傲吏能违俗，未拟浮名好驻颜。","长孺淮阳今不薄，春花或恐滞燕关。"]},{"t":"元日早朝","f":"七言律诗","c":["禁城春色引朝天，接迹夔龙近法筵。","云里金茎通御气，宫中玉树隐祈年。","西山亭障遥临蓟，朔漠旌旗满护燕。","闻道至尊歌白雪，小臣还献郢人篇。"]},{"t":"早春得汝思蜀中书","f":"七言律诗","c":["万里谁传锦字回，楚天摇落正堪哀。","扬舲巫峡江声合，立马岷峨雪色来。","西极使星遥入部，中原人日好登台。","莫言羽猎誇胡后，不数扬雄作赋才。"]},{"t":"送恽员外按察郢中","f":"七言律诗","c":["醉拥骊驹不可留，送君花发凤凰楼。","青春开府西陵色，到日登台北雁愁。","寒雨远分荆楚望，白云无尽汉江流。","共知人世悲难合，傥得隋珠莫暗投。"]},{"t":"初春元美席上赠茂秦得关字","f":"七言律诗","c":["凤城杨柳又堪攀，谢朓西园未拟还。","客久高吟生白发，春来归梦满青山。","明时抱病风尘下，短褐论交天地间。","闻道鹿门妻子在，祗今词赋且燕关。"]},{"t":"送大中丞王丈赴山东","f":"七言律诗","c":["天下军储飞挽来，中原胡虏战争回。","汉柱旧题骢马使，名家接武佩刀才。","按章时拂风尘入，宪府秋临海岱开。","主恩偏忆严城日，什二东秦保障哉。"]},{"t":"答宗考功斋居见赠","f":"七言律诗","c":["金茎夜擢建章高，汉主祈年祀事劳。","仙吏诗投青玉案，故人秋卧白云曹。","此生湖海供多病，何物风尘抵浊醪。","中散近来疏懒甚，更无书札到山涛。"]},{"t":"呈大司寇何公","f":"七言律诗","c":["汉臣韦氏有玄成，旧德中朝曳履声。","督部曾持沧海节，总戎亲破绿林兵。","重瞻执法临天座，自失流言荷帝情。","千载云蒸龙变日，更期文剑署高名。"]},{"t":"再呈何公","f":"七言律诗","c":["几年开府汉中丞，去后功名何武称。","荆楚军储遮海过，潢池兵气向秋澄。","尚书北斗天喉舌，司寇西曹帝股肱。","耆旧即今推济美，清朝剑履坐相仍。"]},{"t":"春夜同元美子与子相过公实","f":"七言律诗","c":["西山落日照金茎，北阙春阴覆禁城。","湖海百年今夜酒，风尘五子异时情。","和来白雪俱高唱，自附青云起大名。","不独诸郎关象纬，真人应更为东行。"]},{"t":"送万言卿明府之长兴","f":"七言律诗","c":["逐虏将军度漠回，黄金犹自满燕台。","请缨惭我为齐客，制锦多君更楚材。","城上春云天目出，帘前秋色太湖来。","弦歌暇日能相忆，花里新诗过雁裁。"]},{"t":"送范敬甫之闽中","f":"七言律诗","c":["共看骢马使君贤，开府东南日月偏。","海峤秋阴分越树，人家雨色散闽天。","朝廷记忆江城久，词赋知名水部前。","还拟主恩头白里，时危相赠祖生鞭。"]},{"t":"五日同子与子相过公实时公实在告","f":"七言律诗","c":["空堂隐映石榴殷，花里幽期白昼间。","染翰风云随上客，开樽雷雨过西山。","赋成敢避能惊座，酒罢何妨善闭关。","况值怀沙千古怨，那堪骑马独醒还。"]},{"t":"韦氏池亭同元美子与子相赋 其一","f":"七言律诗","c":["贳酒新丰解佩刀，相逢意气为君豪。","孤亭昼敞杉松色，乱石青含薜荔高。","自向风尘偏胜迹，岂令湖海傲吾曹。","从他桂树山中发，招隐何劳更反骚。"]},{"t":"韦氏池亭同元美子与子相赋 其二","f":"七言律诗","c":["华发文章愧不工，独怜诸子调相同。","西京矫矫多奇气，东海泱泱自大风。","三署仙郎携酒后，一时词客此亭中。","白云寥廓迷幽蓟，驺衍谈天碣石宫。"]},{"t":"韦氏池亭同元美子与子相赋 其三","f":"七言律诗","c":["幽亭斜日乱松声，下有沧浪可濯缨。","求友花间黄鸟出，垂天城上夏云生。","梁园作赋千年事，河朔衔杯万古情。","莫恨风流吾辈晚，邹阳袁绍汉时名。"]},{"t":"韦氏池亭同元美子与子相赋 其四","f":"七言律诗","c":["韦曲高临汉苑开，城南连骑紫宸回。","闭门流水花间过，倚槛青山席上来。","客难似矜能避世，子虚谁见不怜才。","若论承宠无先后，安得吾曹共酒杯。"]},{"t":"送张元谕虞部谪常州别驾","f":"七言律诗","c":["赋就黄花别季鹰，还从迁谪问飞腾。","悬知汉柱名当藉，况复虔刀事可凭。","寒雨大江临楚望，千家秋色暗毗陵。","阖闾城外逢摇落，何限吴山客里登。"]},{"t":"送吴人陆之箕","f":"七言律诗","c":["客有登台赋远游，蓟门金尽坐高秋。","总怜岐路无知己，不向风尘为白头。","木落毗陵看过雁，月明张翰倚扁舟。","未将簪绂论多病，草色姑苏到自愁。"]}]};